const HCA_BANK={"communication":[{"id":"communication-core","question":"A fictional patient has nodded through a discharge explanation. Time is limited. What most directly checks how clearly you explained the next step?","answers":["Repeat the key points, then ask whether any questions remain.","Invite the patient to explain the next step in their own words.","Give a written summary, then ask them to read it after discharge."],"correct":1,"rationales":["Repeating information can help, but does not itself reveal understanding.","An open teach-back prompt reveals what needs clarification without blaming the patient.","Written support is useful, but does not confirm understanding before the conversation ends."]},{"id":"communication-practice-2","question":"The person says, “I still do not know what happens next.” What should you clarify?","answers":["Repeat every detail from the beginning.","Agree the next action, who is responsible, and how follow-up will happen.","Ask them to reread the leaflet."],"correct":1,"rationales":["Repeating everything may leave the next step unclear.","A useful close makes action and responsibility explicit.","A leaflet can support a conversation but does not resolve the current uncertainty."]},{"id":"communication-practice-3","question":"Which prompt makes teach-back a check on your explanation?","answers":["“Why have you forgotten what I said?”","“Are you a good listener?”","“To check I explained it clearly, how would you describe the next step?”"],"correct":2,"rationales":["Blame can discourage someone from sharing a gap.","Listening ability is not what this check establishes.","This invites the person to explain the plan and keeps responsibility for clarity with you."]}],"safety":[{"id":"safety-core","question":"A fictional transfer record differs from the patient’s medication account. Both could be incomplete. What best addresses the uncertainty?","answers":["Use the latest record while adding the patient’s account as a note.","Ask the patient to confirm which version they followed most recently.","Reconcile the difference with the responsible clinician or pharmacist."],"correct":2,"rationales":["A later timestamp does not resolve an unexplained discrepancy.","The patient’s account matters, but verification with the responsible team is still needed.","Reconciliation resolves the discrepancy through the appropriate responsible team."]},{"id":"safety-practice-2","question":"An instruction is unclear in a fictional exercise. What supports safer practice?","answers":["Pause and clarify it through the responsible team and approved process.","Choose the interpretation that seems most familiar.","Continue and document the uncertainty afterwards."],"correct":0,"rationales":["Clarification is the useful action when intention is uncertain.","Familiarity does not establish the intended action.","Documentation does not replace resolving the uncertainty."]},{"id":"safety-practice-3","question":"What makes a near-miss report useful for learning?","answers":["Naming the person you think is to blame.","Recording the relevant facts through the approved process so the system can learn.","Keeping the incident informal because no harm occurred."],"correct":1,"rationales":["Blame can obscure system conditions and discourage reporting.","Relevant facts and the approved reporting route support learning.","A near miss can reveal a process gap before harm occurs."]}],"empathy":[{"id":"empathy-core","question":"A fictional patient says the plan is difficult. What is the most useful next response before offering a solution?","answers":["Ask which part is difficult and what is getting in the way.","Offer the simplest available version of the current plan.","Explain why following the plan matters for their recovery."],"correct":0,"rationales":["Understanding the barrier allows a more useful shared response.","Simplification may help, but may miss the actual barrier.","Explaining importance may help later; first understand what is making the plan difficult."]},{"id":"empathy-practice-2","question":"A person hesitates before agreeing to a fictional plan. What is the useful next question?","answers":["“Everyone else agrees. Why not you?”","“Shall I mark that as refusal?”","“What concerns you about this plan?”"],"correct":2,"rationales":["Comparison may make it harder to voice a concern.","A hesitation does not establish the reason for it.","Curiosity makes space for the person’s actual priorities and concerns."]},{"id":"empathy-practice-3","question":"What is an appropriate way to acknowledge emotion?","answers":["“That sounds like a lot to manage. What matters most to you now?”","“There is no reason to feel that way.”","“I promise everything will be fine.”"],"correct":0,"rationales":["Acknowledgment and curiosity support a useful conversation.","Dismissing a feeling does not help you understand it.","A promise beyond your control can undermine trust."]}],"sbar":[{"id":"sbar-core","question":"Your fictional SBAR message has been acknowledged. Which closing response best establishes a shared plan?","answers":["Document that the concern was communicated to the receiving team.","Confirm the owner, agreed timing, and contingency if the plan fails.","Repeat the key findings to make sure the message was heard."],"correct":1,"rationales":["Documentation matters, but does not establish what the receiving team will do.","Ownership, timing, and contingency make the shared plan actionable.","Repeating findings checks part of the message but can leave the action unclear."]},{"id":"sbar-practice-2","question":"Which part of an SBAR message states the action you need?","answers":["Background","Recommendation","An introduction alone"],"correct":1,"rationales":["Background gives relevant context.","Recommendation makes the request, ownership and timing explicit.","An introduction does not specify the next action."]},{"id":"sbar-practice-3","question":"The receiver acknowledges your message but no owner is named. What remains to do?","answers":["Assume acknowledgment means the task is assigned.","Send the same message to more people.","Confirm who will act, when, and the agreed contingency."],"correct":2,"rationales":["Acknowledgment alone does not establish responsibility.","More recipients can leave ownership less clear.","Closing the loop includes ownership, timing and what happens if the plan is not carried out."]}],"infection":[{"id":"infection-core","question":"Shared equipment looks clean and the next fictional patient has no known infection. What determines preparation for reuse?","answers":["Whether the prior patient was under additional precautions.","Whether the equipment contacted visibly contaminated material.","The approved cleaning or reprocessing process for that equipment."],"correct":2,"rationales":["Additional precautions can change requirements but are not the only reason to prepare equipment.","Visible contamination is not the only trigger for an approved reuse process.","Use the approved process and instructions; standard precautions apply to all patient care."]},{"id":"infection-practice-2","question":"Which statement about gloves supports the lesson’s infection-prevention principles?","answers":["Gloves do not replace hand hygiene when it is indicated.","Gloves make every contact risk-free.","The same gloves can be kept on if the task is brief."],"correct":0,"rationales":["Use hand hygiene and appropriate protective equipment according to the task and local policy.","No single protective measure makes every contact risk-free.","Equipment and hand-hygiene decisions depend on task and exposure, not simply duration."]},{"id":"infection-practice-3","question":"A fictional task changes. What should guide precautions?","answers":["Keep the same precautions because you already started.","Reassess the anticipated exposure and follow the applicable local guidance.","Copy another person without checking the task."],"correct":1,"rationales":["A changed task may change the relevant exposure.","Precautions should be matched to the current task and guidance.","Another person may be performing a different task."]}],"reasoning":[{"id":"reasoning-core","question":"New information conflicts with the initial explanation in a fictional case. What best supports a safe reassessment?","answers":["Name the mismatch and discuss alternatives with the responsible team.","Collect more observations before revisiting the explanation with anyone.","Ask a colleague whether the original explanation remains the most likely."],"correct":0,"rationales":["Making the mismatch explicit helps the team reconsider rather than anchor on an early explanation.","More information can help, but should not delay communicating a significant concern.","A second opinion helps, but the question should actively invite alternatives and address the mismatch."]},{"id":"reasoning-practice-2","question":"An observation does not fit your first explanation. What is useful?","answers":["Ignore it because your initial idea is likely correct.","Seek only information that confirms your first idea.","Revisit assumptions and consider credible alternatives."],"correct":2,"rationales":["Unexpected information can be important.","Confirmation alone can reinforce an incomplete explanation.","Separating facts from interpretation and revisiting assumptions supports clearer reasoning."]},{"id":"reasoning-practice-3","question":"Which wording distinguishes a fact from an interpretation?","answers":["“I observed this change; I am concerned it may mean something else and need review.”","“My first explanation is the only possible one.”","“It feels obvious, so further discussion is unnecessary.”"],"correct":0,"rationales":["This makes the observation and the uncertainty explicit.","Certainty without considering alternatives can hide uncertainty.","An impression is not a substitute for appropriate review."]}],"speakup":[{"id":"speakup-core","question":"A junior colleague raises a concern during a busy fictional handover. What response best supports speaking up?","answers":["Ask them to write down the concern for the next team meeting.","Thank them, ask what they observed, and check the concern now.","Explain the reasoning behind the current plan before discussing changes."],"correct":1,"rationales":["An active safety concern should be assessed rather than routinely deferred.","Acknowledgment and a timely check help the team understand and act on the concern.","Context can help, but explaining first may close down the concern before it is understood."]},{"id":"speakup-practice-2","question":"A concern remains unresolved. What supports constructive speaking up?","answers":["Focus on a colleague’s personality.","Name the observed issue, its impact, and the response you need.","Withdraw the concern to keep the conversation comfortable."],"correct":1,"rationales":["Personal criticism can distract from the problem.","Specific observations and requests keep the discussion actionable.","Comfort does not resolve an important uncertainty."]},{"id":"speakup-practice-3","question":"Which response supports a colleague who raises a concern?","answers":["“We have always done it this way.”","“You should have been more confident.”","“Thank you. Let us clarify the concern and agree the next action.”"],"correct":2,"rationales":["Habit does not establish that a concern is resolved.","A concern should be evaluated for its content.","Acknowledging and following up helps the team learn and act."]}],"shared":[{"id":"shared-core","question":"Two reasonable options have different burdens for a fictional patient. What should shape the next conversation?","answers":["Which option has the simplest instructions for the team to explain.","Which option most patients with similar circumstances have chosen.","The options’ trade-offs alongside the person’s priorities and needs."],"correct":2,"rationales":["Simplicity matters but is only one part of a balanced discussion.","Others’ choices cannot establish this person’s values or needs.","Balanced evidence, uncertainty, and personal priorities belong in the same discussion."]},{"id":"shared-practice-2","question":"Two reasonable options have different practical burdens. What should the conversation explore?","answers":["What matters to the person, the options and uncertainty, and practical barriers.","Only the option easiest for the team.","Which option sounds most impressive."],"correct":0,"rationales":["A shared decision connects evidence and options to the person’s priorities.","Team convenience alone does not establish the best shared plan.","Presentation does not replace a balanced explanation."]},{"id":"shared-practice-3","question":"What is a useful response when a person wants more time to consider options?","answers":["Treat the request as a failure to cooperate.","Discuss what information or support they need and agree appropriate follow-up.","Tell them the team cannot discuss uncertainty."],"correct":1,"rationales":["Needing time or support is information for the discussion.","Support and a clear follow-up plan can help informed involvement.","Uncertainty should be explained honestly within your role."]}],"ai":[{"id":"ai-core","question":"An AI-generated summary includes a plausible claim with an unfamiliar citation. What is the strongest verification step?","answers":["Locate the actual source and check whether it supports the claim.","Ask the tool to provide a more detailed explanation of its citation.","Compare the claim with a second answer from the same tool."],"correct":0,"rationales":["Independent source checking tests both the reference and the claim.","More detail from the same system can repeat or elaborate an error.","Agreement between generated answers is not independent verification."]},{"id":"ai-practice-2","question":"An AI response contains a polished citation. What does that establish?","answers":["That the source exists and supports the claim.","That qualified review is unnecessary.","Only that a citation was supplied; the source and claim still need independent checking."],"correct":2,"rationales":["A citation can be inaccurate or unrelated.","AI output does not remove the need for appropriate review.","Locate the real source and compare the actual claim and context."]},{"id":"ai-practice-3","question":"What belongs in an unapproved public AI tool?","answers":["Only fictional, non-confidential practice material permitted by your organization.","A patient note with the name removed, without further checks.","A colleague’s private information if the answer will be useful."],"correct":0,"rationales":["Use approved workflows and protect confidential information.","Names are not the only possible identifiers.","Convenience does not authorize disclosure."]}],"wellbeing":[{"id":"wellbeing-core","question":"A fictional colleague reports persistent fatigue affecting concentration. What response addresses both the immediate and continuing concern?","answers":["Suggest a quiet break and review how they feel at the next shift.","Offer immediate support and discuss workload through the proper route.","Share self-care resources and ask them to choose one to practise."],"correct":1,"rationales":["A break may help now, but waiting can leave ongoing safety and workload concerns unaddressed.","Immediate support and attention to working conditions address more than individual coping.","Resources can help, but should not replace practical support and organizational responsibility."]},{"id":"wellbeing-practice-2","question":"What makes a small wellbeing action realistic?","answers":["It requires a perfect uninterrupted day.","It fits the person’s circumstances and can be adapted.","It is judged by how much harder someone works afterwards."],"correct":1,"rationales":["An action that needs ideal conditions may be difficult to repeat.","A manageable, adaptable action is a useful starting point.","Wellbeing is not a measure of productivity or personal worth."]},{"id":"wellbeing-practice-3","question":"Workload makes a personal reset difficult. What else may be needed?","answers":["Assume the person simply needs more resilience.","Keep the problem private in all circumstances.","Appropriate support and attention to the workplace conditions."],"correct":2,"rationales":["Individual actions cannot resolve every system problem.","Trusted support may help identify useful next steps.","Personal wellbeing and working conditions both matter."]}],"equity":[{"id":"equity-core","question":"A fictional patient agrees to a plan, but language and access needs have not been explored. What is the best next step?","answers":["Offer the standard leaflet and invite the family to explain it.","Ask whether the patient is comfortable continuing in this language.","Ask about preferred communication support and practical access needs."],"correct":2,"rationales":["A standard leaflet and family explanation may not meet the person’s communication needs.","This opens the discussion but can still miss format, interpretation, and practical barriers.","A direct, respectful needs check supports an accessible and workable plan."]},{"id":"equity-practice-2","question":"A person’s circumstances differ from your assumptions. What helps?","answers":["Ask respectfully about their needs and preferred support.","Apply the same assumptions more confidently.","Infer their priorities from their appearance."],"correct":0,"rationales":["Direct, respectful questions are more useful than assumptions.","Confidence does not make an assumption accurate.","Appearance does not establish someone’s priorities."]},{"id":"equity-practice-3","question":"Which approach supports a more accessible explanation?","answers":["Use the same format even when it is not understood.","Ask about communication needs and arrange the appropriate accessible format or support.","Speak more quickly to cover everything."],"correct":1,"rationales":["A consistent format is not necessarily an accessible one.","The person’s needs should inform the communication approach.","Speed may make information harder to use."]}],"improvement":[{"id":"improvement-core","question":"A fictional team wants to reduce missing task owners at handover. Which next step supports learning from a small test?","answers":["Agree a limited change, a measure, and a check for added burden.","Introduce an ownership field across the service and gather comments.","Repeat the handover training and count how many staff attend."],"correct":0,"rationales":["A defined test, measure, and balancing check make the result interpretable.","A wider change can create avoidable disruption before a small test has generated learning.","Attendance is an activity measure; it does not show whether missing ownership improved."]},{"id":"improvement-practice-2","question":"A team has a possible explanation for a process problem. What next?","answers":["Treat the explanation as a proven cause.","Change the whole system immediately.","Identify evidence that could test the explanation."],"correct":2,"rationales":["A plausible explanation remains a hypothesis until investigated.","A broad change can introduce unexamined effects.","Collecting relevant evidence helps distinguish a cause from an assumption."]},{"id":"improvement-practice-3","question":"What belongs in a small improvement test?","answers":["An aim, a limited approved change, measures and a balancing check.","Only a count of emails announcing the change.","A guarantee that the change will work."],"correct":0,"rationales":["A test should define what will change, what will be measured and what else might be affected.","Communication activity does not establish a process improvement.","A test is a way to learn, not a promise of success."]}],"health-literacy":[{"id":"health-literacy-core","question":"A person follows a conversation until new abbreviations appear. What helps?","answers":["Repeat the abbreviations more slowly.","Replace abbreviations, explain one action and check understanding.","Assume agreement means understanding."],"correct":1,"rationales":["This leaves the key issue unresolved. Understanding can change with stress, unfamiliar language and a new setting. Use clear information for everyone rather than trying to identify who appears to have low literacy.","This applies the principle: Understanding can change with stress, unfamiliar language and a new setting. Use clear information for everyone rather than trying to identify who appears to have low literacy.","This leaves the key issue unresolved. Understanding can change with stress, unfamiliar language and a new setting. Use clear information for everyone rather than trying to identify who appears to have low literacy."]},{"id":"health-literacy-practice-2","question":"What should guide an accessible format?","answers":["How confident the person appears.","The cheapest format in every case.","The person’s communication needs and preferences."],"correct":2,"rationales":["This leaves the key issue unresolved. Prioritise what the person needs to do next. Use everyday words, a short written summary and accessible formats. Ask about language and communication preferences.","This leaves the key issue unresolved. Prioritise what the person needs to do next. Use everyday words, a short written summary and accessible formats. Ask about language and communication preferences.","This applies the principle: Prioritise what the person needs to do next. Use everyday words, a short written summary and accessible formats. Ask about language and communication preferences."]},{"id":"health-literacy-practice-3","question":"A clear explanation still produces an impractical plan. What next?","answers":["Explore practical barriers and involve the appropriate team.","Give the same explanation again.","Label the person unmotivated."],"correct":0,"rationales":["This applies the principle: Use an open teach-back invitation, listen for gaps, rephrase and check again. Ask whether the plan can work with the person’s practical circumstances.","This leaves the key issue unresolved. Use an open teach-back invitation, listen for gaps, rephrase and check again. Ask whether the plan can work with the person’s practical circumstances.","This leaves the key issue unresolved. Use an open teach-back invitation, listen for gaps, rephrase and check again. Ask whether the plan can work with the person’s practical circumstances."]}],"risk-evidence":[{"id":"risk-evidence-core","question":"A fictional risk changes from 4% to 2%. What is the absolute reduction?","answers":["50 percentage points.","2 percentage points.","2% of the original 4%."],"correct":1,"rationales":["This leaves the key issue unresolved. Ask how many people, over what time, and with which outcome. Compare the same population, denominator and period. A count without a denominator is hard to interpret.","This applies the principle: Ask how many people, over what time, and with which outcome. Compare the same population, denominator and period. A count without a denominator is hard to interpret.","This leaves the key issue unresolved. Ask how many people, over what time, and with which outcome. Compare the same population, denominator and period. A count without a denominator is hard to interpret."]},{"id":"risk-evidence-practice-2","question":"Two rates use different follow-up periods. What is needed?","answers":["A more impressive chart.","The larger percentage alone.","A comparable time frame before interpreting the difference."],"correct":2,"rationales":["This leaves the key issue unresolved. In a fictional example, an outcome falls from 4 in 100 to 2 in 100. That is 2 percentage points less, and a 50% relative reduction. These describe the same change in different ways.","This leaves the key issue unresolved. In a fictional example, an outcome falls from 4 in 100 to 2 in 100. That is 2 percentage points less, and a 50% relative reduction. These describe the same change in different ways.","This applies the principle: In a fictional example, an outcome falls from 4 in 100 to 2 in 100. That is 2 percentage points less, and a 50% relative reduction. These describe the same change in different ways."]},{"id":"risk-evidence-practice-3","question":"A before-and-after study shows improvement. What is justified?","answers":["An observed association, with design limitations considered.","Proof that the change caused every improvement.","A guarantee of the same effect locally."],"correct":0,"rationales":["This applies the principle: Examine the study setting, design and uncertainty. An association is not automatically a causal effect, and a result from one setting is not a forecast for another.","This leaves the key issue unresolved. Examine the study setting, design and uncertainty. An association is not automatically a causal effect, and a result from one setting is not a forecast for another.","This leaves the key issue unresolved. Examine the study setting, design and uncertainty. An association is not automatically a causal effect, and a result from one setting is not a forecast for another."]}],"human-factors":[{"id":"human-factors-core","question":"A recurring omission survives repeated reminders. What is useful?","answers":["Send a stronger reminder.","Study the workflow and test a support at the fragile step.","Identify the least experienced person."],"correct":1,"rationales":["This leaves the key issue unresolved. Map the actual task, tools, environment, handoffs and competing demands. Ask the people doing the work where the process becomes difficult.","This applies the principle: Map the actual task, tools, environment, handoffs and competing demands. Ask the people doing the work where the process becomes difficult.","This leaves the key issue unresolved. Map the actual task, tools, environment, handoffs and competing demands. Ask the people doing the work where the process becomes difficult."]},{"id":"human-factors-practice-2","question":"What is a balancing measure for a new checklist?","answers":["Only attendance at the launch.","Only the number of printed copies.","Added time or duplication caused by the checklist."],"correct":2,"rationales":["This leaves the key issue unresolved. Reduce unnecessary complexity. Use a visible task owner, a clear cue or an approved checklist at the point of work. A reminder to concentrate is a weak response to a recurring design problem.","This leaves the key issue unresolved. Reduce unnecessary complexity. Use a visible task owner, a clear cue or an approved checklist at the point of work. A reminder to concentrate is a weak response to a recurring design problem.","This applies the principle: Reduce unnecessary complexity. Use a visible task owner, a clear cue or an approved checklist at the point of work. A reminder to concentrate is a weak response to a recurring design problem."]},{"id":"human-factors-practice-3","question":"Why involve people doing the work?","answers":["They can reveal constraints absent from the written procedure.","They can guarantee the solution will work.","They replace the need for approval."],"correct":0,"rationales":["This applies the principle: Try a limited approved change and check its effect on errors, time and workarounds. Include people who might experience new barriers.","This leaves the key issue unresolved. Try a limited approved change and check its effect on errors, time and workarounds. Include people who might experience new barriers.","This leaves the key issue unresolved. Try a limited approved change and check its effect on errors, time and workarounds. Include people who might experience new barriers."]}],"med-transitions":[{"id":"med-transitions-core","question":"A medicine appears on only one transfer list. What can you conclude?","answers":["The medicine should be stopped.","There is a discrepancy requiring appropriate verification.","The older record is wrong."],"correct":1,"rationales":["This leaves the key issue unresolved. Use the approved reconciliation process to compare available records and the person’s account. Identify an unexplained omission, duplication or change.","This applies the principle: Use the approved reconciliation process to compare available records and the person’s account. Identify an unexplained omission, duplication or change.","This leaves the key issue unresolved. Use the approved reconciliation process to compare available records and the person’s account. Identify an unexplained omission, duplication or change."]},{"id":"med-transitions-practice-2","question":"Which person’s account is relevant?","answers":["Only the receiving team’s assumptions.","Only the newest computer entry.","The patient or caregiver, alongside approved reliable sources."],"correct":2,"rationales":["This leaves the key issue unresolved. Record the uncertainty and route it to the responsible clinician or pharmacist. Do not decide to start, stop or change a medicine from this learning exercise.","This leaves the key issue unresolved. Record the uncertainty and route it to the responsible clinician or pharmacist. Do not decide to start, stop or change a medicine from this learning exercise.","This applies the principle: Record the uncertainty and route it to the responsible clinician or pharmacist. Do not decide to start, stop or change a medicine from this learning exercise."]},{"id":"med-transitions-practice-3","question":"Verification resolves a discrepancy. What follows?","answers":["Communicate and document the agreed plan through the approved process.","Keep the answer in memory.","Delete the uncertainty without communicating."],"correct":0,"rationales":["This applies the principle: Ensure the agreed resolution reaches the authorised record, receiving team and person through the approved workflow. Confirm ownership of unresolved items.","This leaves the key issue unresolved. Ensure the agreed resolution reaches the authorised record, receiving team and person through the approved workflow. Confirm ownership of unresolved items.","This leaves the key issue unresolved. Ensure the agreed resolution reaches the authorised record, receiving team and person through the approved workflow. Confirm ownership of unresolved items."]}],"deterioration":[{"id":"deterioration-core","question":"Urgent concern emerges during a practice handover. What takes priority?","answers":["Finishing a perfect SBAR script.","The immediate local escalation pathway within your role.","Waiting for the next routine handover."],"correct":1,"rationales":["This leaves the key issue unresolved. Describe the observed change and relevant context within your role. Do not let a reassuring label replace current observations or the person’s expressed concern.","This applies the principle: Describe the observed change and relevant context within your role. Do not let a reassuring label replace current observations or the person’s expressed concern.","This leaves the key issue unresolved. Describe the observed change and relevant context within your role. Do not let a reassuring label replace current observations or the person’s expressed concern."]},{"id":"deterioration-practice-2","question":"What does a reassuring earlier note establish?","answers":["That any new concern is incorrect.","That reassessment is unnecessary.","Earlier context; it does not negate a new change."],"correct":2,"rationales":["This leaves the key issue unresolved. For urgent concern, use the local emergency or escalation pathway immediately. A communication mnemonic must not become a waiting sequence or substitute for clinical assessment.","This leaves the key issue unresolved. For urgent concern, use the local emergency or escalation pathway immediately. A communication mnemonic must not become a waiting sequence or substitute for clinical assessment.","This applies the principle: For urgent concern, use the local emergency or escalation pathway immediately. A communication mnemonic must not become a waiting sequence or substitute for clinical assessment."]},{"id":"deterioration-practice-3","question":"Acknowledgment arrives but no action owner is named. What remains?","answers":["Confirm responsibility, response timing and contingency.","Assume the task is assigned.","End the conversation to avoid repetition."],"correct":0,"rationales":["This applies the principle: Confirm the receiving person, expected response and contingency if help does not arrive. Re-escalate through local policy if the concern remains unresolved.","This leaves the key issue unresolved. Confirm the receiving person, expected response and contingency if help does not arrive. Re-escalate through local policy if the concern remains unresolved.","This leaves the key issue unresolved. Confirm the receiving person, expected response and contingency if help does not arrive. Re-escalate through local policy if the concern remains unresolved."]}],"data-stewardship":[{"id":"data-stewardship-core","question":"A note has no name but includes a rare event and location. Is it anonymous?","answers":["Yes, because the name was removed.","Not necessarily; combinations of details can identify someone.","Yes, if shared only once."],"correct":1,"rationales":["This leaves the key issue unresolved. Use organisationally approved systems and authorised access for a defined purpose. Consult current information-governance policy rather than inferring permission from convenience.","This applies the principle: Use organisationally approved systems and authorised access for a defined purpose. Consult current information-governance policy rather than inferring permission from convenience.","This leaves the key issue unresolved. Use organisationally approved systems and authorised access for a defined purpose. Consult current information-governance policy rather than inferring permission from convenience."]},{"id":"data-stewardship-practice-2","question":"A file is sent to the wrong recipient. What helps?","answers":["Assume deletion resolves every consequence.","Wait to see whether anyone complains.","Follow the local reporting and containment process promptly."],"correct":2,"rationales":["This leaves the key issue unresolved. Names are not the only identifiers. Dates, locations, rare details and combinations can identify someone. Removing a name alone does not establish anonymity.","This leaves the key issue unresolved. Names are not the only identifiers. Dates, locations, rare details and combinations can identify someone. Removing a name alone does not establish anonymity.","This applies the principle: Names are not the only identifiers. Dates, locations, rare details and combinations can identify someone. Removing a name alone does not establish anonymity."]},{"id":"data-stewardship-practice-3","question":"A digital output is fluent and well formatted. What does that establish?","answers":["Presentation quality; accuracy and suitability still require checks.","Independent verification.","Organisational permission to use it."],"correct":0,"rationales":["This applies the principle: Independently check material before relying on it. If information is sent to the wrong place, follow the local incident process promptly and preserve relevant facts.","This leaves the key issue unresolved. Independently check material before relying on it. If information is sent to the wrong place, follow the local incident process promptly and preserve relevant facts.","This leaves the key issue unresolved. Independently check material before relying on it. If information is sent to the wrong place, follow the local incident process promptly and preserve relevant facts."]}],"teachback-skill":[{"id":"teachback-skill-core","question":"Which prompt invites teach-back?","answers":["Do you understand everything?","How would you describe the next step, so I can check my explanation?","Why did you forget?"],"correct":1,"rationales":["This leaves the key issue unresolved. Use plain language, then pause. Ask about preferred language, format and interpretation support. Focus on one useful next action.","This applies the principle: Use plain language, then pause. Ask about preferred language, format and interpretation support. Focus on one useful next action.","This leaves the key issue unresolved. Use plain language, then pause. Ask about preferred language, format and interpretation support. Focus on one useful next action."]},{"id":"teachback-skill-practice-2","question":"An explanation gap appears. What next?","answers":["Record agreement anyway.","Repeat the whole script unchanged.","Rephrase the unclear part and check again."],"correct":2,"rationales":["This leaves the key issue unresolved. Say: To check that I explained it clearly, how would you describe what happens next? Frame the check around your explanation.","This leaves the key issue unresolved. Say: To check that I explained it clearly, how would you describe what happens next? Frame the check around your explanation.","This applies the principle: Say: To check that I explained it clearly, how would you describe what happens next? Frame the check around your explanation."]},{"id":"teachback-skill-practice-3","question":"Who is being checked in teach-back?","answers":["The clarity of the explanation and shared understanding.","The person’s intelligence.","The person’s willingness to please the team."],"correct":0,"rationales":["This applies the principle: Thank the person, identify the gap and explain it in a different way. Repeat the check until the next step is clear, using appropriate support.","This leaves the key issue unresolved. Thank the person, identify the gap and explain it in a different way. Repeat the check until the next step is clear, using appropriate support.","This leaves the key issue unresolved. Thank the person, identify the gap and explain it in a different way. Repeat the check until the next step is clear, using appropriate support."]}],"conflict":[{"id":"conflict-core","question":"Which opening keeps a disagreement actionable?","answers":["You never care about the team.","The task has no named owner; can we clarify responsibility?","Everyone knows who is at fault."],"correct":1,"rationales":["This leaves the key issue unresolved. Separate what happened from your interpretation of motives. Use a calm statement about a specific event and its effect.","This applies the principle: Separate what happened from your interpretation of motives. Use a calm statement about a specific event and its effect.","This leaves the key issue unresolved. Separate what happened from your interpretation of motives. Use a calm statement about a specific event and its effect."]},{"id":"conflict-practice-2","question":"A colleague offers a different account. What helps?","answers":["Infer their motives.","Dismiss it because your account came first.","Explore their observations and the shared goal."],"correct":2,"rationales":["This leaves the key issue unresolved. Ask for the other perspective and name the common aim. Explore constraints without assuming that disagreement reflects poor intent.","This leaves the key issue unresolved. Ask for the other perspective and name the common aim. Explore constraints without assuming that disagreement reflects poor intent.","This applies the principle: Ask for the other perspective and name the common aim. Explore constraints without assuming that disagreement reflects poor intent."]},{"id":"conflict-practice-3","question":"A serious concern remains unresolved. What next?","answers":["Use the appropriate organisational escalation or support route.","Treat agreement as more important than safety.","Keep repeating a personal accusation."],"correct":0,"rationales":["This applies the principle: Make a specific request, confirm an owner and arrange follow-up. Use the appropriate support or escalation route for unresolved concerns or unacceptable conduct.","This leaves the key issue unresolved. Make a specific request, confirm an owner and arrange follow-up. Use the appropriate support or escalation route for unresolved concerns or unacceptable conduct.","This leaves the key issue unresolved. Make a specific request, confirm an owner and arrange follow-up. Use the appropriate support or escalation route for unresolved concerns or unacceptable conduct."]}],"documentation":[{"id":"documentation-core","question":"What is missing from team aware, follow up later?","answers":["More reassuring wording.","An explicit action owner and timing.","A longer paragraph."],"correct":1,"rationales":["This leaves the key issue unresolved. Use relevant, accurate observations and the time or source where appropriate. Distinguish a person’s account, your observation and an interpretation.","This applies the principle: Use relevant, accurate observations and the time or source where appropriate. Distinguish a person’s account, your observation and an interpretation.","This leaves the key issue unresolved. Use relevant, accurate observations and the time or source where appropriate. Distinguish a person’s account, your observation and an interpretation."]},{"id":"documentation-practice-2","question":"Which sentence separates observation from interpretation?","answers":["It is obviously fine.","This must be the only possible explanation.","I observed a change; I am concerned it needs review."],"correct":2,"rationales":["This leaves the key issue unresolved. Include the agreed action, responsible person, timing and unresolved questions according to your local documentation requirements.","This leaves the key issue unresolved. Include the agreed action, responsible person, timing and unresolved questions according to your local documentation requirements.","This applies the principle: Include the agreed action, responsible person, timing and unresolved questions according to your local documentation requirements."]},{"id":"documentation-practice-3","question":"Is writing an urgent concern enough?","answers":["No; use the appropriate direct escalation as well.","Yes, if the note is long.","Yes, if the record has a timestamp."],"correct":0,"rationales":["This applies the principle: Ask whether another authorised colleague could identify what to do next. Correct errors through the approved record process; documentation does not replace urgent communication.","This leaves the key issue unresolved. Ask whether another authorised colleague could identify what to do next. Correct errors through the approved record process; documentation does not replace urgent communication.","This leaves the key issue unresolved. Ask whether another authorised colleague could identify what to do next. Correct errors through the approved record process; documentation does not replace urgent communication."]}],"risk-dialogue":[{"id":"risk-dialogue-core","question":"A fictional outcome changes from 10/100 to 8/100. Which explanation is balanced?","answers":["A 20% change with no baseline.","2 fewer in 100 over the same period, alongside harms and uncertainty.","80 fewer people in 100."],"correct":1,"rationales":["This leaves the key issue unresolved. Use the same denominator, time horizon and outcome for benefits and harms. Include the baseline and avoid relative percentages on their own.","This applies the principle: Use the same denominator, time horizon and outcome for benefits and harms. Include the baseline and avoid relative percentages on their own.","This leaves the key issue unresolved. Use the same denominator, time horizon and outcome for benefits and harms. Include the baseline and avoid relative percentages on their own."]},{"id":"risk-dialogue-practice-2","question":"What should accompany a visual risk chart?","answers":["A promise of individual benefit.","A statement that the chart chooses the best option.","An accessible explanation and a check of interpretation."],"correct":2,"rationales":["This leaves the key issue unresolved. Invite the person to describe their interpretation. A visual display can support a conversation, but it does not replace accessible explanation.","This leaves the key issue unresolved. Invite the person to describe their interpretation. A visual display can support a conversation, but it does not replace accessible explanation.","This applies the principle: Invite the person to describe their interpretation. A visual display can support a conversation, but it does not replace accessible explanation."]},{"id":"risk-dialogue-practice-3","question":"A person prioritises a different burden. What next?","answers":["Explore that priority with the responsible clinician.","Repeat the percentage until they agree.","Assume they misunderstood because they disagree."],"correct":0,"rationales":["This applies the principle: Explore the person’s preferences, practical burden and need for more information. Involve the responsible clinician and arrange a way to revisit the decision.","This leaves the key issue unresolved. Explore the person’s preferences, practical burden and need for more information. Involve the responsible clinician and arrange a way to revisit the decision.","This leaves the key issue unresolved. Explore the person’s preferences, practical burden and need for more information. Involve the responsible clinician and arrange a way to revisit the decision."]}],"feedback":[{"id":"feedback-core","question":"Which feedback is most actionable?","answers":["You are careless.","The owner was unclear; let us practise naming one.","Try to be better."],"correct":1,"rationales":["This leaves the key issue unresolved. Use a respectful setting and clarify the learning purpose. Address urgent safety concerns immediately through the appropriate route rather than saving them for routine feedback.","This applies the principle: Use a respectful setting and clarify the learning purpose. Address urgent safety concerns immediately through the appropriate route rather than saving them for routine feedback.","This leaves the key issue unresolved. Use a respectful setting and clarify the learning purpose. Address urgent safety concerns immediately through the appropriate route rather than saving them for routine feedback."]},{"id":"feedback-practice-2","question":"Why invite the learner’s perspective?","answers":["It removes the need to discuss impact.","It guarantees agreement.","It can reveal context and shape a useful next step."],"correct":2,"rationales":["This leaves the key issue unresolved. Describe an observable behaviour and its effect. Ask how the other person saw the situation before offering a conclusion. Avoid labels about character.","This leaves the key issue unresolved. Describe an observable behaviour and its effect. Ask how the other person saw the situation before offering a conclusion. Avoid labels about character.","This applies the principle: Describe an observable behaviour and its effect. Ask how the other person saw the situation before offering a conclusion. Avoid labels about character."]},{"id":"feedback-practice-3","question":"What completes a feedback conversation?","answers":["An agreed action, support and review point.","A label about personality.","A score without explanation."],"correct":0,"rationales":["This applies the principle: Choose a manageable behaviour to try, the support needed and a time to review. Feedback becomes useful when it changes what can happen next.","This leaves the key issue unresolved. Choose a manageable behaviour to try, the support needed and a time to review. Feedback becomes useful when it changes what can happen next.","This leaves the key issue unresolved. Choose a manageable behaviour to try, the support needed and a time to review. Feedback becomes useful when it changes what can happen next."]}],"debrief":[{"id":"debrief-core","question":"Which question opens a useful debrief?","answers":["Who made us look bad?","What did we expect, and what actually happened?","How can we prove nothing went wrong?"],"correct":1,"rationales":["This leaves the key issue unresolved. Clarify that the discussion aims to learn and improve. Use the appropriate formal reporting or investigation process where required. Do not include confidential case details in this app.","This applies the principle: Clarify that the discussion aims to learn and improve. Use the appropriate formal reporting or investigation process where required. Do not include confidential case details in this app.","This leaves the key issue unresolved. Clarify that the discussion aims to learn and improve. Use the appropriate formal reporting or investigation process where required. Do not include confidential case details in this app."]},{"id":"debrief-practice-2","question":"A debrief identifies three ideas but no owner. What is missing?","answers":["A longer meeting title.","More ideas alone.","An agreed action, owner and review point."],"correct":2,"rationales":["This leaves the key issue unresolved. Ask what was expected, what happened, what helped and what made the task difficult. Invite different roles and distinguish facts from assumptions.","This leaves the key issue unresolved. Ask what was expected, what happened, what helped and what made the task difficult. Invite different roles and distinguish facts from assumptions.","This applies the principle: Ask what was expected, what happened, what helped and what made the task difficult. Invite different roles and distinguish facts from assumptions."]},{"id":"debrief-practice-3","question":"Does a learning debrief replace required incident reporting?","answers":["No; follow the appropriate formal process as well.","Yes, if everyone attends.","Yes, if the discussion is supportive."],"correct":0,"rationales":["This applies the principle: Agree one improvement question or action with a named owner and review date. Share learning through approved channels and arrange support when needed.","This leaves the key issue unresolved. Agree one improvement question or action with a named owner and review date. Share learning through approved channels and arrange support when needed.","This leaves the key issue unresolved. Agree one improvement question or action with a named owner and review date. Share learning through approved channels and arrange support when needed."]}],"humility":[{"id":"humility-core","question":"Which statement shows useful humility?","answers":["I cannot be wrong.","Here is my current view and the uncertainty we need to resolve.","No one should question a confident explanation."],"correct":1,"rationales":["This leaves the key issue unresolved. Distinguish a working explanation from a verified fact. State uncertainty in useful terms, including the information or review needed.","This applies the principle: Distinguish a working explanation from a verified fact. State uncertainty in useful terms, including the information or review needed.","This leaves the key issue unresolved. Distinguish a working explanation from a verified fact. State uncertainty in useful terms, including the information or review needed."]},{"id":"humility-practice-2","question":"A patient identifies a mismatch. What helps?","answers":["Explain why the first view must be right.","Dismiss it because it was not in the record.","Explore it and review the working explanation."],"correct":2,"rationales":["This leaves the key issue unresolved. Ask what does not fit and who may have another perspective. A patient, caregiver or colleague may notice something missing from the current account.","This leaves the key issue unresolved. Ask what does not fit and who may have another perspective. A patient, caregiver or colleague may notice something missing from the current account.","This applies the principle: Ask what does not fit and who may have another perspective. A patient, caregiver or colleague may notice something missing from the current account."]},{"id":"humility-practice-3","question":"What should follow a revised explanation?","answers":["Communicate the change and next action to relevant people.","Keep the update private.","Erase the learning discussion."],"correct":0,"rationales":["This applies the principle: Revise the explanation when evidence changes. Tell relevant people what changed and what happens next within the appropriate clinical process.","This leaves the key issue unresolved. Revise the explanation when evidence changes. Tell relevant people what changed and what happens next within the appropriate clinical process.","This leaves the key issue unresolved. Revise the explanation when evidence changes. Tell relevant people what changed and what happens next within the appropriate clinical process."]}],"dignity":[{"id":"dignity-core","question":"A companion answers every question. What supports dignity?","answers":["Assume the companion should decide.","Address the person directly and ask their preferred involvement.","Avoid the person to save time."],"correct":1,"rationales":["This leaves the key issue unresolved. Use the person’s preferred name and communication approach. Do not talk over someone to their companion or assume preferences from appearance or disability.","This applies the principle: Use the person’s preferred name and communication approach. Do not talk over someone to their companion or assume preferences from appearance or disability.","This leaves the key issue unresolved. Use the person’s preferred name and communication approach. Do not talk over someone to their companion or assume preferences from appearance or disability."]},{"id":"dignity-practice-2","question":"What should guide communication support?","answers":["The standard format regardless of need.","An assumption based on age.","The person’s expressed needs and appropriate service support."],"correct":2,"rationales":["This leaves the key issue unresolved. Explain your role and the intended conversation or task. Ask permission within the applicable consent process, protect privacy and respect the person’s questions.","This leaves the key issue unresolved. Explain your role and the intended conversation or task. Ask permission within the applicable consent process, protect privacy and respect the person’s questions.","This applies the principle: Explain your role and the intended conversation or task. Ask permission within the applicable consent process, protect privacy and respect the person’s questions."]},{"id":"dignity-practice-3","question":"What makes permission meaningful in a conversation?","answers":["Explain the purpose and allow questions within the applicable process.","Treat silence as agreement in every setting.","Rely only on the room number."],"correct":0,"rationales":["This applies the principle: Ask what support would help. Arrange approved interpretation or accessible formats and involve companions according to the person’s preferences and applicable policy.","This leaves the key issue unresolved. Ask what support would help. Arrange approved interpretation or accessible formats and involve companions according to the person’s preferences and applicable policy.","This leaves the key issue unresolved. Ask what support would help. Arrange approved interpretation or accessible formats and involve companions according to the person’s preferences and applicable policy."]}],"just-culture":[{"id":"just-culture-core","question":"What does a systems approach require?","answers":["Ignoring every individual action.","Understanding conditions alongside fair accountability.","Blaming the newest colleague."],"correct":1,"rationales":["This leaves the key issue unresolved. Use the appropriate response, reporting and support process. Record what is known and avoid speculation about an individual’s motives.","This applies the principle: Use the appropriate response, reporting and support process. Record what is known and avoid speculation about an individual’s motives.","This leaves the key issue unresolved. Use the appropriate response, reporting and support process. Record what is known and avoid speculation about an individual’s motives."]},{"id":"just-culture-practice-2","question":"A near miss caused no harm. What is useful?","answers":["Wait for harm before reviewing.","Assume the process is safe.","Report and learn through the approved process."],"correct":2,"rationales":["This leaves the key issue unresolved. Ask about workload, tools, interruptions, unclear responsibilities and other influences. A systems approach does not mean ignoring deliberate unsafe behaviour or professional obligations.","This leaves the key issue unresolved. Ask about workload, tools, interruptions, unclear responsibilities and other influences. A systems approach does not mean ignoring deliberate unsafe behaviour or professional obligations.","This applies the principle: Ask about workload, tools, interruptions, unclear responsibilities and other influences. A systems approach does not mean ignoring deliberate unsafe behaviour or professional obligations."]},{"id":"just-culture-practice-3","question":"Which response supports learning?","answers":["Investigate facts and context through an established fair process.","Publicly speculate about motives.","Replace the whole investigation with a reminder."],"correct":0,"rationales":["This applies the principle: Use the organisation’s established process to evaluate conduct and context fairly. Agree changes, support and follow-up rather than treating a single training reminder as the whole solution.","This leaves the key issue unresolved. Use the organisation’s established process to evaluate conduct and context fairly. Agree changes, support and follow-up rather than treating a single training reminder as the whole solution.","This leaves the key issue unresolved. Use the organisation’s established process to evaluate conduct and context fairly. Agree changes, support and follow-up rather than treating a single training reminder as the whole solution."]}],"accountability":[{"id":"accountability-core","question":"A task is beyond your authority. What is accountable?","answers":["Accept silently and improvise.","Clarify the limit and route it to the appropriate responsible person.","Ignore it without communicating."],"correct":1,"rationales":["This leaves the key issue unresolved. State what you can do within your role and what needs another person’s authority or expertise. Do not accept a task by implication when responsibility is unclear.","This applies the principle: State what you can do within your role and what needs another person’s authority or expertise. Do not accept a task by implication when responsibility is unclear.","This leaves the key issue unresolved. State what you can do within your role and what needs another person’s authority or expertise. Do not accept a task by implication when responsibility is unclear."]},{"id":"accountability-practice-2","question":"You cannot meet an agreed timing. What helps?","answers":["Mark it complete to avoid concern.","Wait until someone notices.","Communicate early and agree a safe alternative or escalation."],"correct":2,"rationales":["This leaves the key issue unresolved. If a commitment cannot be met, communicate the constraint early through the appropriate route. Agree an alternative owner or contingency rather than allowing a silent gap.","This leaves the key issue unresolved. If a commitment cannot be met, communicate the constraint early through the appropriate route. Agree an alternative owner or contingency rather than allowing a silent gap.","This applies the principle: If a commitment cannot be met, communicate the constraint early through the appropriate route. Agree an alternative owner or contingency rather than allowing a silent gap."]},{"id":"accountability-practice-3","question":"At transition, an item is unfinished. What next?","answers":["Make its status and receiving owner explicit.","Assume the next team will find it.","Delete it from the discussion."],"correct":0,"rationales":["This applies the principle: Confirm the agreed action and record or communicate completion through the approved process. Make outstanding items visible at transition.","This leaves the key issue unresolved. Confirm the agreed action and record or communicate completion through the approved process. Make outstanding items visible at transition.","This leaves the key issue unresolved. Confirm the agreed action and record or communicate completion through the approved process. Make outstanding items visible at transition."]}],"compassion-boundaries":[{"id":"compassion-boundaries-core","question":"Which response is compassionate and realistic?","answers":["I promise everything will be fine.","I can help with this step and connect you with the right support.","You just need to be stronger."],"correct":1,"rationales":["This leaves the key issue unresolved. Ask what is difficult and listen without judgment. Avoid promises that are outside your control or assumptions about what another person needs.","This applies the principle: Ask what is difficult and listen without judgment. Avoid promises that are outside your control or assumptions about what another person needs.","This leaves the key issue unresolved. Ask what is difficult and listen without judgment. Avoid promises that are outside your control or assumptions about what another person needs."]},{"id":"compassion-boundaries-practice-2","question":"What does a short reset address?","answers":["The need for organisational support.","Every cause of workplace distress.","A possible momentary pause, not persistent workload problems."],"correct":2,"rationales":["This leaves the key issue unresolved. Explain what you can help with and what needs a different service or professional. Clear boundaries can make support more reliable.","This leaves the key issue unresolved. Explain what you can help with and what needs a different service or professional. Clear boundaries can make support more reliable.","This applies the principle: Explain what you can help with and what needs a different service or professional. Clear boundaries can make support more reliable."]},{"id":"compassion-boundaries-practice-3","question":"A support need exceeds your role. What helps?","answers":["Acknowledge it and connect to appropriate qualified support.","Promise unlimited availability.","Try an unfamiliar intervention without support."],"correct":0,"rationales":["This applies the principle: For persistent strain, use appropriate supervisory, occupational-health or qualified support. A short personal reset does not replace workload review or organisational responsibility.","This leaves the key issue unresolved. For persistent strain, use appropriate supervisory, occupational-health or qualified support. A short personal reset does not replace workload review or organisational responsibility.","This leaves the key issue unresolved. For persistent strain, use appropriate supervisory, occupational-health or qualified support. A short personal reset does not replace workload review or organisational responsibility."]}],"inclusive-leadership":[{"id":"inclusive-leadership-core","question":"A colleague is silent in a meeting. What can you infer?","answers":["They agree with every decision.","Their view is unknown; create an appropriate way to contribute.","They have nothing useful to add."],"correct":1,"rationales":["This leaves the key issue unresolved. Ask which roles and perspectives are absent from a decision. Consider who cannot attend, speak easily or access the materials.","This applies the principle: Ask which roles and perspectives are absent from a decision. Consider who cannot attend, speak easily or access the materials.","This leaves the key issue unresolved. Ask which roles and perspectives are absent from a decision. Consider who cannot attend, speak easily or access the materials."]},{"id":"inclusive-leadership-practice-2","question":"Which meeting change supports inclusion?","answers":["Using only the fastest discussion format.","Requiring everyone to speak without preparation.","Accessible materials and more than one route to contribute."],"correct":2,"rationales":["This leaves the key issue unresolved. Offer accessible materials and appropriate ways to contribute before, during or after the discussion. Invite concerns without putting someone on display.","This leaves the key issue unresolved. Offer accessible materials and appropriate ways to contribute before, during or after the discussion. Invite concerns without putting someone on display.","This applies the principle: Offer accessible materials and appropriate ways to contribute before, during or after the discussion. Invite concerns without putting someone on display."]},{"id":"inclusive-leadership-practice-3","question":"After gathering input, what closes the loop?","answers":["Explain the decision and how contributions shaped it.","File the comments without response.","Count comments as proof of agreement."],"correct":0,"rationales":["This applies the principle: Acknowledge contributions, explain how they influenced the decision and assign follow-up. An invitation without a response can leave people unheard.","This leaves the key issue unresolved. Acknowledge contributions, explain how they influenced the decision and assign follow-up. An invitation without a response can leave people unheard.","This leaves the key issue unresolved. Acknowledge contributions, explain how they influenced the decision and assign follow-up. An invitation without a response can leave people unheard."]}]};
const HCA_FINALES={"handover":{"event":"In this fictional handover, a colleague replies: “I have heard the concern, but the review is still unassigned.”","question":"Which next message most clearly closes the remaining gap?","answers":["“Thank you. I will assume the review will happen.”","“Can we confirm the named owner, agreed timing and what to do if the plan is not carried out?”","“I will mention it again at the end of the week.”"],"correct":1,"rationales":["Hearing a concern does not establish responsibility.","The message makes ownership, timing and contingency explicit. Urgent concerns require the immediate local route.","A later discussion does not resolve the current responsibility."]},"teachback":{"event":"The fictional patient describes the plan differently from what you intended. They are worried about asking again.","question":"Which response best keeps the conversation useful?","answers":["“I have explained it already.”","“I will record that you agreed.”","“Thank you for explaining. I need to make that part clearer. Let us try it another way and check again.”"],"correct":2,"rationales":["Repetition with blame can discourage someone from describing a gap.","Agreement does not establish understanding.","Acknowledge the response, clarify the explanation and check understanding without blame."]},"ai-case":{"event":"You find the actual source. It studies a different population from the one described in the fictional AI output.","question":"How should that affect your use of the claim?","answers":["Do not generalize the claim; examine the actual population, outcome and uncertainty with appropriate review.","Use the claim because the reference is real.","Ask the AI to sound more certain."],"correct":0,"rationales":["Finding a real source is only one step. Relevance and the actual findings still matter.","A real citation may not support the stated claim.","Confidence of wording is not verification."]},"med-case":{"event":"In the fictional transfer exercise, the responsible clinician has clarified the unexplained difference between the lists.","question":"What supports a clearer transition next?","answers":["Keep the clarification in memory.","Update the appropriate record, communicate the agreed plan and check understanding within your role.","Leave both lists unchanged so nobody loses information."],"correct":1,"rationales":["Memory alone does not communicate a resolved plan to others.","The resolution should reach the approved record, receiving team and patient through the appropriate workflow.","Unresolved conflicting records can allow the discrepancy to recur."]}};
const HCA_ACTIVITIES=[{"id":"handover","type":"scenarios","title":"The handover that almost missed it","desc":"During a simulated shift handover, a colleague describes a patient as “stable.” You notice newly documented deterioration and the review plan is unclear. You are concerned.","meta":"Scenario · 3 decisions · About 4 min","image":"activity-handover","action":"startCase('handover')","icon":"dialogue"},{"id":"teachback","type":"scenarios","title":"“Yes, I understand.” But do they?","desc":"In a simulated discharge conversation, a patient agrees with every explanation but cannot describe the follow-up plan. You have limited time.","meta":"Scenario · 3 decisions · About 4 min","image":"activity-teachback","action":"startCase('teachback')","icon":"dialogue"},{"id":"ai-case","type":"scenarios","title":"The confident answer that needs a check","desc":"In a fictional training exercise, an AI tool produces a polished summary with a clinical claim and a reference you do not recognize.","meta":"Scenario · 3 decisions · About 4 min","image":"activity-ai-case","action":"startCase('ai-case')","icon":"dialogue"},{"id":"med-case","type":"scenarios","title":"Two lists. One important pause.","desc":"In a simulated transfer, a medication appears on one list but not another. The reason for the difference is not documented.","meta":"Scenario · 3 decisions · About 4 min","image":"activity-med-case","action":"startCase('med-case')","icon":"dialogue"},{"id":"room","type":"studios","title":"The room. The pause. The decision.","desc":"Rotate an illustrated care room, explore five zones and reason through six hand-hygiene moments.","meta":"3D illustration · Six vignettes","action":"hcaOpenRoom()","icon":"room","image":"activity-room"},{"id":"hygiene","type":"studios","title":"The moments that matter","desc":"Explore six hand-hygiene decisions with an animated scene, contextual hotspots and immediate feedback.","meta":"Interactive Studio · Six decisions","action":"hcaLaunchStudio('hygiene')","image":"activity-hygiene","icon":"spark"},{"id":"sbar-studio","type":"studios","title":"Pass the message clearly","desc":"Arrange the message, check the structure and confirm how the next action will happen.","meta":"Interactive Studio · SBAR sequencing","action":"hcaLaunchStudio('sbar')","image":"activity-sbar-studio","icon":"dialogue"},{"id":"movement","type":"studios","title":"A little space to move","desc":"Watch three optional seated movement demonstrations. Pause, slow down or step through the illustration.","meta":"Wellbeing Studio · Three demonstrations","action":"hcaLaunchStudio('movement')","image":"activity-movement","icon":"spark"},{"id":"cus","type":"team","title":"Speak up with clarity","desc":"Name a concern, make the uncertainty explicit and ask for a useful response.","meta":"Team practice · CUS conversation","action":"openAdv('cus')","icon":"dialogue","image":"activity-cus"},{"id":"huddle","type":"team","title":"Bring the team into alignment","desc":"Identify named ownership, respond to changed conditions and learn from the shared plan.","meta":"Team practice · Brief, huddle, debrief","action":"openAdv('huddle')","icon":"team","image":"activity-huddle"},{"id":"flow","type":"team","title":"Test a change. Watch the flow.","desc":"Adjust a transparent fictional process, compare two capacities and explain what the model can show.","meta":"QI sandbox · Synthetic process model","action":"openAdv('flow')","icon":"growth","image":"activity-flow"},{"id":"cc-teach","type":"studios","title":"Build the teach-back loop","desc":"Sequence a conversation from a manageable explanation to a repaired understanding gap.","meta":"Interactive Studio · Sequence & explain","action":"ccOpenStudio('cc-teach')","icon":"dialogue","image":"activity-cc-teach"},{"id":"cc-risk","type":"studios","title":"See the absolute difference","desc":"Move two fictional risks and compare an absolute difference with a relative change.","meta":"Interactive Studio · Numbers & visual model","action":"ccOpenStudio('cc-risk')","icon":"growth","image":"activity-cc-risk"},{"id":"cc-reconcile","type":"studios","title":"Spot the transfer discrepancy","desc":"Compare two fictional lists, classify the differences and route the unresolved questions.","meta":"Interactive Studio · Compare & classify","action":"ccOpenStudio('cc-reconcile')","icon":"tools","image":"activity-cc-reconcile"},{"id":"cc-bias","type":"studios","title":"Catch the first-story trap","desc":"Work through three reasoning moments and seek information that could challenge an assumption.","meta":"Interactive Studio · Three decisions","action":"ccOpenStudio('cc-bias')","icon":"dialogue","image":"activity-cc-bias"},{"id":"cc-verify","type":"studios","title":"Trace the AI claim","desc":"Inspect a fictional citation, its population and a proposed sharing workflow.","meta":"Interactive Studio · Three decisions","action":"ccOpenStudio('cc-verify')","icon":"dialogue","image":"activity-cc-verify"},{"id":"cc-access","type":"studios","title":"Make participation possible","desc":"Spot an access barrier, ask the person and adapt the interaction.","meta":"Interactive Studio · Three decisions","action":"ccOpenStudio('cc-access')","icon":"dialogue","image":"activity-cc-access"},{"id":"cc-interrupt","type":"studios","title":"Recover after an interruption","desc":"Build a deliberate return to a fictional administrative task after competing demands.","meta":"Interactive Studio · Sequence & explain","action":"ccOpenStudio('cc-interrupt')","icon":"dialogue","image":"activity-cc-interrupt"},{"id":"cc-compassion","type":"studios","title":"Support with warmth and limits","desc":"Practise empathetic responses, honest boundaries and a practical support route.","meta":"Interactive Studio · Three decisions","action":"ccOpenStudio('cc-compassion')","icon":"dialogue","image":"activity-cc-compassion"},{"id":"sim-handover","type":"simulations","title":"The handover control room","desc":"Explore a 3D room, locate three communication gaps and make the next action explicit.","meta":"3D simulation · Three interactive checkpoints","action":"ccOpenSimulation('sim-handover')","image":"generated-sim-handover","icon":"room"},{"id":"sim-interruptions","type":"simulations","title":"The interruption recovery desk","desc":"Inspect a task desk, distinguish competing demands and recover a verified task state.","meta":"3D simulation · Three interactive checkpoints","action":"ccOpenSimulation('sim-interruptions')","image":"generated-sim-interruptions","icon":"room"},{"id":"sim-shared-choice","type":"simulations","title":"The shared-choice consultation","desc":"Explore a consultation space, compare fictional numbers and bring the person’s priorities into the plan.","meta":"3D simulation · Three interactive checkpoints","action":"ccOpenSimulation('sim-shared-choice')","image":"generated-sim-shared-choice","icon":"room"}];
const CC_SECTIONS={"dashboard":["Your next useful step","A workspace for resuming, choosing practice and returning to a review.","A clear next action reduces the effort of finding a useful activity.","At the beginning of a learning session.","Choose your focus and available time; resume or select the suggested activity.","Any practitioner; use Preferences to describe your role.","harm"],"library":["Learn: three connected dimensions","Thirty lessons connect Knowledge, Skills and Attitudes.","Understanding, practical action and professional habits need to develop together.","When you want a principle, a worked example and a recall check.","Filter a dimension, open a lesson, attempt a check and save a next action.","Practitioners, learners and educators across care settings.","harm"],"knowledge":["Knowledge: understand the reason","Ten foundations in safety, evidence, human factors and digital practice.","A useful principle helps you explain why a particular action matters.","Before practice or when an assumption needs examination.","Read a principle, compare the worked example, then answer a recall prompt.","Any practitioner working within their own role.","harm"],"skills":["Skills: rehearse the action","Ten practical topics for communication, documentation, feedback and team learning.","Specific rehearsal helps turn an intention into an observable next step.","Before a difficult conversation or when refining a routine.","Practise with fictional material, inspect feedback and try a different response.","Individuals, peer pairs and facilitated learning groups.","handoff"],"attitudes":["Attitudes: shape the response","Ten lessons on empathy, humility, fairness, dignity and sustainable practice.","How a concern is received can influence whether the next voice is heard.","When reflecting on a decision or the way people are treated.","Compare responses, question an assumption and choose one behaviour to practise.","Every team member, including people who lead or supervise.","access"],"pathways":["Learning pathways","Three routes organise ten lessons per dimension.","A route can make an extended learning goal easier to navigate.","When choosing a longer sequence rather than one short lesson.","Start with your confidence reflection or any dimension, then revisit your progress.","Self-directed learners and educators planning a session.","harm"],"practice":["Interactive practice","Scenarios, Studios and team exercises with feedback and preserved attempts.","Practice makes reasoning visible in a fictional setting.","When you want to try a response before using it in your own role.","Choose a format, make a decision, read the debrief and save the completed attempt.","Individual learners, peer pairs and facilitated groups.","simulation"],"studios":["Interactive Studios","Visual workspaces for sorting, calculating, comparing and rehearsing.","Different tasks benefit from different kinds of interaction.","When you want to test a principle actively rather than read about it.","Choose an activity, follow its instructions, review feedback and save your practice.","Any learner; all new activities work with buttons and keyboard controls.","simulation"],"team":["Teams & improvement","Exercises for speaking up, team alignment and process testing.","Shared ownership and visible constraints make a team plan easier to act on.","For a fictional team rehearsal or planning an approved improvement.","Try a CUS response, explore a huddle or inspect the transparent flow model.","Team members, facilitators and improvement leads.","harm"],"tools":["Toolkit: make a principle usable","Editable prompts for handovers, understanding, reflection and improvement.","A structured prompt can expose an omitted action or unanswered question.","When drafting a fictional rehearsal or a non-confidential learning plan.","Open a tool, compare examples, edit your draft and keep a private backup.","Practitioners and educators; approved local tools govern actual care.","audit"],"progress":["My Growth: a learning record","A history of attempts, reflections, actions and due recall reviews.","Revisiting a decision helps you notice what you can now explain or do differently.","After practice and when returning to a planned review.","Read an attempt, review your action, export a record or create a backup.","The learner using this browser; the record is not certification.","harm"],"saved":["Your saved collection","Bookmarks for lessons you want to revisit.","Saving creates a personal route through a larger catalogue.","When a topic is relevant but you cannot explore it now.","Use the bookmark on a lesson; return here to resume it.","Anyone building a personal learning collection.","harm"],"search":["Find a useful activity","Search across lessons, scenarios, tools, terms and Studios.","A concrete question is often a useful starting point.","When you know a topic or skill you need to explore.","Search a keyword such as teach-back, risk, dignity or medication.","Learners and educators finding a relevant activity.","harm"]};
const CC_STUDIOS=[{"id":"cc-teach","title":"Build the teach-back loop","description":"Sequence a conversation from a manageable explanation to a repaired understanding gap.","mode":"sequence","evidence":"teachback","lesson":"teachback-skill","why":"A check becomes useful when an explanation gap leads to repair.","when":"Before a follow-up or information conversation.","how":"Select the five moves in order, check your sequence and read the feedback.","steps":["Explain one next step in plain language.","Invite the person to explain it in their own words.","Listen and identify the understanding gap.","Re-explain the unclear part in a different way.","Invite teach-back again to check the repair."],"intro":"The person describes a different next step from the one intended. Build the full loop, including the repair."},{"id":"cc-risk","title":"See the absolute difference","description":"Move two fictional risks and compare an absolute difference with a relative change.","mode":"risk","evidence":"engagement","lesson":"risk-evidence","why":"Relative percentages can sound large without revealing a baseline.","when":"When preparing to explain a study or compare two options.","how":"Adjust the fictional figures, calculate the change, and compare your answer with the visual model."},{"id":"cc-reconcile","title":"Spot the transfer discrepancy","description":"Compare two fictional lists, classify the differences and route the unresolved questions.","mode":"match","evidence":"medication","lesson":"med-transitions","why":"A list mismatch must be verified rather than turned into an assumed prescription.","when":"Before practising an approved reconciliation workflow.","how":"Compare the records and classify each row; inspect the debrief before saving.","rows":[["Medicine A","Listed as current","Not listed","Omission / status to verify"],["Medicine B","Listed once","Listed twice","Possible duplicate to verify"],["Medicine C","Listed as current","Listed as current","No visible discrepancy in these records"]],"options":["Omission / status to verify","Possible duplicate to verify","No visible discrepancy in these records"]},{"id":"cc-bias","title":"Catch the first-story trap","description":"Work through three reasoning moments and seek information that could challenge an assumption.","mode":"decisions","evidence":"harm","lesson":"humility","why":"A plausible first explanation can obscure a mismatch.","when":"During a fictional case review or peer discussion.","how":"Choose a response at each moment and compare the reasons for all options.","scenes":[["The early label","A fictional team has an early explanation. A new observation does not fit.","What should happen next?",["Name the mismatch and revisit alternatives with the responsible team.","Set the new information aside.","Ask only for evidence confirming the first explanation."],0,["The mismatch should inform reassessment and appropriate review.","This preserves the first explanation without examining new evidence.","Confirming evidence alone can reinforce an incomplete explanation."]],["The confident colleague","A senior colleague sounds certain, but the relevant source has not been checked.","What makes the discussion more useful?",["Accept certainty as proof.","Ask which observations support the view and what would change it.","Wait until no uncertainty remains before discussing it."],1,["Confidence alone does not establish a claim.","This invites the evidence and its limits into the conversation.","Uncertainty can be communicated and managed now."]],["The updated view","Review changes the fictional team’s working explanation.","What closes the loop?",["Keep the update among the people in the room.","Treat the earlier uncertainty as a personal failure.","Communicate the revised view and next action to the relevant people."],2,["Relevant others may still be working with the earlier plan.","Updating a view is part of careful reasoning.","An updated explanation must reach those who need to act."]]]},{"id":"cc-verify","title":"Trace the AI claim","description":"Inspect a fictional citation, its population and a proposed sharing workflow.","mode":"decisions","evidence":"digital","lesson":"data-stewardship","why":"A fluent claim can still be unsupported, irrelevant or unsafe to share.","when":"Before relying on digital material in an approved workflow.","how":"Choose what to check at each stage, then inspect your complete decision trail.","scenes":[["A polished reference","A fictional AI draft names an unfamiliar study but gives no retrievable source.","What is the useful next check?",["Locate the actual publication and inspect the claim independently.","Ask the same model to promise accuracy.","Treat the citation’s formatting as verification."],0,["Independent checking tests whether the source and support exist.","Reassurance from the same system is not independent evidence.","Presentation does not establish that a reference is real."]],["A different population","You locate a real paper. Its participants and outcome differ from the draft.","What should change?",["Use it because the journal is real.","Do not generalise the claim; examine relevance and seek appropriate review.","Remove the population details to simplify the claim."],1,["A real paper may not support this particular claim.","Relevance is necessary in addition to source existence.","Removing context makes the claim harder to assess."]],["An unsafe shortcut","A colleague suggests uploading a note without its name to an unapproved public tool.","What is appropriate?",["Upload it if the answer is useful.","Assume removing a name makes it anonymous.","Use the approved information-governance workflow; other details may identify someone."],2,["Usefulness does not authorise disclosure.","Other details and combinations can identify someone.","Purpose, authorisation and the full information content matter."]]]},{"id":"cc-access","title":"Make participation possible","description":"Spot an access barrier, ask the person and adapt the interaction.","mode":"decisions","evidence":"access","lesson":"dignity","why":"The usual format may create a barrier that is not immediately visible.","when":"When preparing a conversation, appointment or learning session.","how":"Explore three fictional moments, choose an adaptation and review the reasoning.","scenes":[["A quiet agreement","A fictional person nods during an unfamiliar-language explanation.","What is the useful next step?",["Ask about preferred language and arrange appropriate support.","Assume the nod confirms understanding.","Ask a nearby child to translate clinical details."],0,["A direct preference check and appropriate support improve access.","Agreement alone does not reveal understanding.","Use qualified interpretation through the service where needed."]],["An inaccessible format","The person says the standard written sheet is difficult to use.","How should you respond?",["Give a second copy of the same sheet.","Ask what format or support works for them and arrange it through the service.","Infer the person’s ability from appearance."],1,["Repeating the same format may repeat the barrier.","The person’s expressed needs should shape the adaptation.","Appearance cannot establish what support is useful."]],["A companion speaks","A companion answers everything while the person is present.","What supports participation?",["Address all questions only to the companion.","Assume the person does not want involvement.","Speak directly to the person and ask how they want the companion involved."],2,["This can leave the person’s own voice unheard.","Ask rather than assume their preference.","Direct address and a preference check preserve participation."]]]},{"id":"cc-interrupt","title":"Recover after an interruption","description":"Build a deliberate return to a fictional administrative task after competing demands.","mode":"sequence","evidence":"interruptions","lesson":"human-factors","why":"An interruption can leave task status and responsibility unclear.","when":"When reflecting on interruptions in non-clinical learning work.","how":"Sequence the four recovery moves, then consider which system support would help.","intro":"Fictional task: preparing a learning pack. An interruption leaves you unsure which checks were completed. This sequence is not a clinical procedure.","steps":["Pause and identify the task’s current status.","Verify completed and outstanding steps against the approved task record.","Clarify uncertainty or ownership before continuing.","Resume from the verified point and record the next action."]},{"id":"cc-compassion","title":"Support with warmth and limits","description":"Practise empathetic responses, honest boundaries and a practical support route.","mode":"decisions","evidence":"wellbeing","lesson":"compassion-boundaries","why":"Support is more dependable when it acknowledges the person and your role.","when":"Before a peer-support or workload conversation.","how":"Choose a response in three moments, then review the action and the boundary.","scenes":[["The first response","A fictional colleague says the workload feels unmanageable.","Which response opens a useful discussion?",["That sounds difficult. What is the most pressing concern right now?","Everyone is busy.","A one-minute reset will solve it."],0,["Acknowledgment and an open question invite the person’s actual concern.","Comparison can close the discussion.","A short reset does not resolve continuing workload conditions."]],["A realistic offer","You can listen now but cannot change the rota yourself.","What can you say?",["I guarantee your workload will change.","I can listen and help identify the appropriate person to discuss the workload.","I will take sole responsibility for fixing everything."],1,["Avoid promising an outcome outside your control.","This combines a useful action with an honest boundary.","An unlimited promise can create an unreliable support plan."]],["Beyond a short pause","The strain is persistent and affecting concentration.","What should the response include?",["Only another breathing exercise.","Keeping it private in every circumstance.","Appropriate support and a workload or safety discussion through the local route."],2,["Continuing strain may need more than an immediate pause.","Appropriate trusted support may be important.","A response should consider the person and working conditions."]]]}];
const CC_EVIDENCE={"harm":{"title":"Preventable harm across care settings","numbers":[["6%","pooled prevalence of preventable harm"],["70","studies; 337,025 patients"]],"kind":"bar","ratio":6,"source":"Panagioti et al. · BMJ · 2019","url":"https://www.bmj.com/content/366/bmj.l4185","type":"Systematic review","finding":"Preventable harm was reported across multiple care settings.","population":"70 observational studies; 337,025 patients across medical care settings.","context":"Pooled estimate 6% (95% CI 5–7%). Rates and definitions varied between studies. This is historical synthesis, not a local incident rate or Carecraft outcome."},"handoff":{"title":"A structured handoff programme","numbers":[["23%","relative reduction in medical errors"],["30%","relative reduction in preventable adverse events"]],"kind":"bar","ratio":23,"source":"Starmer et al. · NEJM · 2014","url":"https://www.nejm.org/doi/abs/10.1056/NEJMsa1405556","type":"Multicentre before-and-after study","finding":"Error rates fell after implementation of the I-PASS bundle.","population":"Nine paediatric residency programmes; 10,740 patient admissions.","context":"A multicomponent intervention, not an SBAR-only effect. Before-and-after associations do not isolate every cause or predict this app’s effect."},"medication":{"title":"Medication reconciliation at transitions","numbers":[["2.85","discrepancies per patient at the start"],["0.98","discrepancies per patient at the end"]],"kind":"compare","ratio":34.3859649122807,"source":"Schnipper et al. · BMJ Quality & Safety · 2022","url":"https://qualitysafety.bmj.com/content/31/4/278","type":"Multicentre quality-improvement study","finding":"Discrepancy rates fell during the MARQUIS2 implementation.","population":"18 North American hospitals or hospital systems, with data collection at 17; 2016–2018.","context":"Observed rates across an 18-month, mentored, multicomponent intervention. A discrepancy is not synonymous with injury. No individual tool effect or dose decision is inferred."},"ipc":{"title":"A bundle for catheter-related infection","numbers":[["Up to 66%","reduction in infection rates"],["103","ICUs reporting data"]],"kind":"bar","ratio":66,"source":"Pronovost et al. · NEJM · 2006","url":"https://www.nejm.org/doi/abs/10.1056/NEJMoa061115","type":"Collaborative cohort study","finding":"A coordinated infection-prevention programme was associated with sustained improvement.","population":"Michigan intensive-care units; catheter-related bloodstream infections; 18-month study.","context":"Historical, multicomponent ICU programme. This is not the effect of hand hygiene alone, a general infection rate, or proof that a Studio prevents infections."},"access":{"title":"Accessibility is a routine need","numbers":[["28.7%","of US adults reported functional disability"],["~70m","US adults, based on 2022 data"]],"kind":"bar","ratio":28.7,"source":"CDC · Disability and Health Data Now · 2025","url":"https://www.cdc.gov/disability-and-health/articles-documents/disability-and-health-data-now.html","type":"Population surveillance","finding":"Accessible services matter to a substantial part of the adult population.","population":"2022 US Behavioral Risk Factor Surveillance System, reported by CDC.","context":"US self-reported survey data, not global or Saudi prevalence. Definitions differ from other surveys. The figure does not reveal any individual’s needs: ask the person."},"wellbeing":{"title":"Burnout and reported safety incidents","numbers":[["2.04","odds ratio for patient-safety incidents"],["170","studies in the full review"]],"kind":"none","source":"Hodkinson et al. · BMJ · 2022","url":"https://www.bmj.com/content/378/bmj-2022-070442","type":"Observational meta-analysis","finding":"Physician burnout was associated with higher odds of safety incidents.","population":"239,246 physicians in the full review. The overall-burnout/safety analysis used 35 studies and 41,059 physicians.","context":"OR 2.04 (95% CI 1.69–2.45); substantial heterogeneity. Odds are not risk. Association does not establish causation or the effect of an individual wellbeing exercise."},"engagement":{"title":"Decision aids improve understanding","numbers":[["+11.9","points on a 100-point knowledge scale"],["209","studies in the complete review"]],"kind":"none","source":"Stacey et al. · Cochrane · 2024","url":"https://www.cochrane.org/evidence/CD001431_patient-decision-aids-help-people-who-are-facing-decisions-about-health-treatment-or-screening","type":"Review of randomised trials","finding":"Decision aids improved knowledge compared with usual care.","population":"107,698 adults in the full review. The knowledge estimate pooled 107 studies and 25,492 participants.","context":"Mean difference 11.90/100 (95% CI 10.60–13.19), high-certainty evidence for this outcome. Evidence searched to March 2022; aids supplement clinical consultation."},"teachback":{"title":"Teach-back across different settings","numbers":[["20","studies included"],["19","reported benefit on at least one outcome"]],"kind":"none","source":"Talevski et al. · PLOS ONE · 2020","url":"https://journals.plos.org/plosone/article?id=10.1371/journal.pone.0231350","type":"Systematic review","finding":"Teach-back showed promising results, with varied methods and outcomes.","population":"Studies across different populations and care settings, searched to July 2019.","context":"Counts of studies, not a 95% treatment benefit. Seven studies were rated weak and outcomes were heterogeneous; no single pooled clinical effect is claimed."},"empathy":{"title":"Empathy and positive communication","numbers":[["28","trials in the full review"],["6,017","participants overall"]],"kind":"none","source":"Howick et al. · Journal of the Royal Society of Medicine · 2018","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC6047264/","type":"Review of randomised trials","finding":"The empathy subgroup found a small improvement in pooled patient outcomes.","population":"Seven trials tested empathic consultations; other trials tested positive expectations.","context":"Empathy subgroup SMD −0.18 (95% CI −0.32 to −0.03). This standardised effect is not a percentage reduction. Conditions, outcomes and certainty varied."},"interruptions":{"title":"Interruptions during medication work","numbers":[["53.1%","of observed administrations were interrupted"],["4,271","medication administrations observed"]],"kind":"bar","ratio":53.1,"source":"Westbrook et al. · Archives of Internal Medicine · 2010","url":"https://pubmed.ncbi.nlm.nih.gov/20421552/","type":"Direct observational study","finding":"More interruptions were associated with more errors in the observed setting.","population":"98 nurses, six wards, two Sydney teaching hospitals; 2006–2008 observations.","context":"Each interruption was associated with a 12.7% increase in clinical errors in the study model. Observational association, not a universal error probability or a rationale to delay urgent communication."},"digital":{"title":"A citation can look real and still be false","numbers":[["55%","fabricated citations in the GPT-3.5 sample"],["18%","fabricated citations in the GPT-4 sample"]],"kind":"compare","ratio":32.72727272727273,"source":"Walters & Wilder · Scientific Reports · 2023","url":"https://www.nature.com/articles/s41598-023-41032-5","type":"Model-output benchmark study","finding":"The sampled outputs contained fabricated and erroneous references.","population":"636 citations generated for the study’s prompts using 2023-era models.","context":"Historical benchmark, not a current error rate for all AI systems or clinical outputs. Different prompts, versions and verification workflows can produce different results."},"simulation":{"title":"Why actively rehearse?","numbers":[["609","studies included"],["35,226","health-professions trainees"]],"kind":"none","source":"Cook et al. · JAMA · 2011","url":"https://jamanetwork.com/journals/jama/article-abstract/1104300","type":"Systematic review and meta-analysis","finding":"Simulation training outperformed no intervention on pooled learning outcomes.","population":"Multiple health professions and simulation formats; 137 randomised studies plus other designs.","context":"Large heterogeneity and predominantly pre/post studies. The comparison was no intervention; it does not establish superiority to every teaching method or validate these particular simulations."},"audit":{"title":"Feedback can support better practice","numbers":[["+6.2","percentage-point mean improvement"],["292","studies in the full review"]],"kind":"none","source":"Ivers et al. · Cochrane · 2025","url":"https://pubmed.ncbi.nlm.nih.gov/40130784/","type":"Systematic review","finding":"Audit and feedback improved desired professional practice on average.","population":"The mean estimate pooled 177 studies comparing audit and feedback with control.","context":"95% CI 4.1–8.2 percentage points; moderate-certainty evidence. Effects varied and interventions often included education or reminders. This is not an effect of informal feedback alone."}};
