const ui={filters:{category:'all',topic:'all',length:'all',status:'all',sort:'recommended'},practice:{format:'all',duration:'all',topic:'all',mode:'all'},layout:'grouped',onboard:0,minutes:[2,5,10].includes(+state.goal)?+state.goal:5,query:'',searchIndex:0,selectedQuote:'',noteLesson:null,review:null,completion:null,activity:null,dirty:false,tool:null,modalTrigger:null,forceClose:false,undo:null,present:false,reveal:true,timer:null,seconds:0,ticking:false,readSpeed:1,previousActivity:null};
let currentPage='dashboard',currentFilter='all',query='',activeLesson=null,lessonTab='learn',lessonReturn='library',lessonAnswers={},hcaQuestionIndex=0,hcaAnswerMaps={},exampleModes={},quoteIndex=0,assessmentIndex=0,assessmentAnswers=[],breathTimer=null,toastTimer=null,availableMinutes=5;
function btn(label,action,args=[],variant='primary',extra=''){return `<button ${/\btype=/.test(extra)?'':'type="button"'} class="button ${variant}" data-action="${action}" ${args.map((v,i)=>`data-arg${i}="${esc(v)}"`).join(' ')} ${extra}>${label}</button>`;}
function icon(name){return `<span class="icon" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round">${HCA_PATHS[name]||CC_ART_ICONS[name]||HCA_PATHS.spark}</svg></span>`;}
function hcaIcon(name){return icon(name);}
function chip(label,kind=''){return `<span class="chip ${kind}">${esc(label)}</span>`;}
function disclosure(text='Illustrative · fictional learning'){return `<span class="disclosure">${icon('shield')}${esc(text)}</span>`;}
function empty(title,text,action='library',label='Explore learning'){return `<div class="empty"><span class="empty-symbol">${icon('book')}</span><h3>${title}</h3><p>${text}</p>${btn(label,'navigate',[action],'secondary')}</div>`;}
function header(title,subtitle,eyebrow='YOUR LEARNING SPACE'){return `<header class="page-heading"><span class="eyebrow">${eyebrow}</span><h1>${title}</h1><p>${subtitle}</p></header>`;}
function progress(value,label){return `<div class="progress" role="progressbar" aria-label="${esc(label)}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.round(value)}"><span style="width:${Math.max(0,Math.min(100,value))}%"></span></div>`;}
function ring(value){return `<span class="ring" style="--progress:${Math.round(value)}" aria-label="${Math.round(value)} percent complete"><b>${Math.round(value)}%</b></span>`;}
function ccIsDark(){return state.theme==='dark'||(state.theme==='system'&&matchMedia('(prefers-color-scheme: dark)').matches);}
function studioReducedMotion(){return state.reduceMotion||matchMedia('(prefers-reduced-motion: reduce)').matches;}
function applyPreferences(){const root=document.documentElement;root.dataset.theme=ccIsDark()?'dark':'light';root.dataset.motion=studioReducedMotion()?'reduce':'full';root.dataset.dyslexia=String(state.dyslexia===true);root.style.setProperty('--text-scale',state.textSize===21?'1.25':state.textSize===19?'1.125':'1');document.body.classList.toggle('theme-dark',ccIsDark());document.body.classList.toggle('hca-reduce',studioReducedMotion());}
function persist(){store.save();}function persistQuiet(){store.save();}function hcaSave(){store.save();}
function localDay(date=new Date()){return date.getFullYear()+'-'+String(date.getMonth()+1).padStart(2,'0')+'-'+String(date.getDate()).padStart(2,'0');}
function laterDay(days=1){const d=new Date();d.setDate(d.getDate()+days);return localDay(d);}
function due(id){return !!state.reviewQueue[id]&&state.reviewQueue[id].due<=localDay();}
function hcaDue(){return lessons.filter(l=>due(l.id)).map(lesson=>({lesson,...state.reviewQueue[lesson.id]}));}
function status(l){return due(l.id)?'Review due':state.completed.includes(l.id)?'Reviewed':state.checkRecords.some(r=>r.lesson===l.id)||state.lastSession?.lesson===l.id?'In progress':'Not started';}
function footer(){return `<footer class="app-footer"><span>© ${new Date().getFullYear()} Healthcare Crown Academy</span><nav aria-label="Legal information">${btn('About','info',['about'],'ghost')}${btn('Privacy','info',['privacy'],'ghost')}${btn('Sources','info',['sources'],'ghost')}</nav></footer>`;}
function shell(){document.getElementById('app').innerHTML=`<a class="skip" href="#main">Skip to content</a><aside class="sidebar" id="sidebar" aria-label="Main navigation"><button class="brand" data-action="navigate" data-arg0="dashboard"><img src="${ccIsDark()?HCA_CREST_DARK:HCA_CREST}" alt="Healthcare Crown Academy crest"><span><b>Carecraft</b><small>A Healthcare Crown<br>Academy companion</small></span></button><div class="sidebar-scroll"><nav>${NAV.map(([route,i,t])=>`<button data-action="navigate" data-arg0="${route}" data-nav="${route}">${icon(i)}<span>${t}</span></button>`).join('')}</nav></div></aside><button class="scrim" data-action="menu" data-arg0="close" aria-label="Close navigation"></button><div class="workspace"><header class="topbar"><button class="icon-button menu-toggle" data-action="menu" aria-label="Open navigation" aria-controls="sidebar" aria-expanded="false"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" aria-hidden="true"><path d="M4 7h16M4 12h16M4 17h16"/></svg></button><div class="breadcrumb"><span>Carecraft</span><span class="hs-sep" aria-hidden="true">/</span><b id="crumb">My Day</b></div><button class="search-launch" data-action="palette" aria-haspopup="dialog" aria-label="Search lessons, tools and notes">${icon('search')}<span>Search lessons, tools and notes</span><kbd>Ctrl K</kbd></button><button class="icon-button" data-action="appearance" aria-label="Choose System, Light or Dark"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M21 12.8A9 9 0 1 1 11.2 3a7 7 0 0 0 9.8 9.8z"/></svg></button><details class="profile-menu"><summary aria-label="Profile and learning preferences">${esc(state.name?state.name.slice(0,2).toUpperCase():'You')}</summary><div class="menu-panel"><strong>${esc(state.name||'Your learning space')}</strong><small>${esc(state.role)}</small>${btn('Preferences','settings',[],'ghost')}${btn('Saved lessons','navigate',['saved'],'ghost')}${btn('Your data','data',[],'ghost')}${btn('About Carecraft','info',['about'],'ghost')}${btn('Evidence & sources','evidence',[],'ghost')}${btn('Privacy','info',['privacy'],'ghost')}</div></details></header><main id="main" tabindex="-1"></main></div><nav class="bottom-nav" aria-label="Primary navigation">${NAV.map(([route,i,t])=>`<button data-action="navigate" data-arg0="${route}" data-nav="${route}">${icon(i)}<span>${t}</span></button>`).join('')}</nav><dialog id="modal" class="modal" aria-labelledby="modalHeading"></dialog><div class="toast" id="toast" role="status" aria-live="polite"></div><div id="quickGuide" class="popover" popover="auto"></div><div id="selectionTools" class="selection-tools" hidden>${btn('Highlight','highlight',[],'secondary')}${btn('Add note','note',[],'primary')}</div><section id="learningRecord" class="print-record"></section>`;}
function titleFor(page){return NAV.find(x=>x[0]===page)?.[2]||({lesson:'Learn',studio:'Practice',pathways:'Learning pathways',saved:'Saved',search:'Search'})[page]||'Carecraft';}
function navigate(page,filter='all'){captureDraft();captureActivity();exitPresent();clearSelection();ui.review=null;document.body.classList.remove('focus-view');if($('#modal')?.open)closeModal(true);stopSpeech();studioDispose();advStop();currentPage=page;currentFilter=filter;if(page==='library'&&filter!=='all')ui.filters.category=filter;if(page==='saved')ui.filters.status='Saved';else if(page==='library'&&ui.filters.status==='Saved')ui.filters.status='all';ui.activity=null;ui.dirty=false;toggleMenu(false);render();recordRoute();window.scrollTo({top:0,behavior:'auto'});$('#main').focus({preventScroll:true});}
function routeString(){if(currentPage==='lesson')return 'lesson/'+activeLesson.id+'/'+lessonTab;if(currentPage==='studio')return 'studio/'+studioTab;if(currentPage==='search')return 'search/'+encodeURIComponent(ui.query);return currentPage+(currentFilter!=='all'?'/'+currentFilter:'');}
function recordRoute(replace=false){const hash='#/'+routeString();if(location.hash===hash)return;try{history[replace?'replaceState':'pushState']({},'',hash);}catch{if(replace&&location.replace)location.replace(hash);else location.hash=hash;}}
function restoreRoute(){captureDraft();captureActivity();if($('#modal')?.open)closeModal(true);exitPresent();clearSelection();studioDispose();advStop();stopSpeech();ui.activity=null;ui.activitySaved=false;ui.dirty=false;ui.review=null;document.body.classList.remove('focus-view');const p=location.hash.replace(/^#\/?/,'').split('/');if(p[0]==='lesson'&&lessons.some(l=>l.id===p[1])){activeLesson=lessons.find(l=>l.id===p[1]);lessonTab=LX_TABS.includes(p[2])?p[2]:'learn';currentPage='lesson';hcaConfigureQuestion(activeLesson.id,state.lastSession?.lesson===p[1]?state.lastSession.question||0:0);}else{currentPage=['dashboard','library','pathways','practice','studio','tools','progress','saved','search'].includes(p[0])?p[0]:'dashboard';currentFilter=['knowledge','skills','attitudes'].includes(p[1])?p[1]:'all';if(currentPage==='library')ui.filters.category=currentFilter;if(currentPage==='saved')ui.filters.status='Saved';else if(ui.filters.status==='Saved')ui.filters.status='all';if(currentPage==='search')try{ui.query=decodeURIComponent(p.slice(1).join('/'));}catch{ui.query='';}if(currentPage==='studio'){studioTab=['hygiene','sbar','movement'].includes(p[1])?p[1]:'hygiene';ui.activity=studioTab==='sbar'?'sbar-studio':studioTab;}}render();}
function render(){const focus=ui.renderedPage===currentPage?rememberFocus($('#main')):null;ui.renderedPage=currentPage;if(studioRuntime)studioDispose();applyPreferences();syncProfile();const renderers={dashboard:renderHome,library:renderLearn,saved:renderLearn,pathways:renderPathways,practice:renderPractice,tools:renderToolkit,progress:renderGrowth,search:renderSearch,lesson:renderLesson,studio:renderActivity};$('#main').innerHTML=`<div class="page page-${currentPage}">${(renderers[currentPage]||renderHome)()}${footer()}</div>`;$('#crumb').textContent=titleFor(currentPage);document.querySelectorAll('[data-nav]').forEach(b=>{const on=b.dataset.nav===(['lesson','pathways','saved'].includes(currentPage)?'library':currentPage==='studio'?'practice':currentPage);b.classList.toggle('active',on);if(on)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});if(studioReducedMotion()&&ui.quoteTimer){clearInterval(ui.quoteTimer);ui.quoteTimer=null;}const crest=$('.brand img');if(crest)crest.src=ccIsDark()?HCA_CREST_DARK:HCA_CREST;hydrate();if(currentPage==='dashboard')ccAfterRender();if(currentPage==='studio'){studioInit();captureActivity();}if(currentPage==='lesson'){state.lastSession={kind:'lesson',lesson:activeLesson.id,tab:lessonTab,question:hcaQuestionIndex,date:new Date().toISOString()};persist();}if(ui.present)document.body.classList.add('present-mode');syncActivityUI();restoreFocus($('#main'),focus);}
function toggleMenu(force){const side=$('#sidebar');if(!side)return;const open=force==='close'||force===false?false:force===true?true:!side.classList.contains('open');side.classList.toggle('open',open);const phone=matchMedia('(max-width:760px)').matches;side.inert=phone&&!open;$('.workspace').inert=phone&&open;$('.bottom-nav').inert=phone&&open;document.body.classList.toggle('menu-open',phone&&open);$('.menu-toggle').setAttribute('aria-expanded',String(open));if(phone&&open)side.querySelector('[data-nav]')?.focus();}
function toast(message,undo){clearTimeout(toastTimer);ui.undo=undo||null;$('#toast').innerHTML=`<span>${esc(message)}</span>${undo?btn('Undo','undo',[],'ghost'):''}`;$('#toast').classList.add('visible');toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),undo?9000:4000);}
function downloadFile(text,name,type='text/plain'){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type}));a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function showModal(title,subtitle,body,tag='',tabs=''){captureDraft();advStop();studioPause();clearInterval(breathTimer);const d=$('#modal'),already=d.open,focus=already?rememberFocus(d):null;if(!already){ui.modalTrigger=document.activeElement;if($('#sidebar').classList.contains('open')){toggleMenu(false);if(matchMedia('(max-width:760px)').matches)ui.modalTrigger=$('.menu-toggle');}}d.className='modal';d.innerHTML=`<header class="modal-header"><div class="modal-title">${tag}<h2 id="modalHeading" tabindex="-1">${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div>${ui.activity?btn(icon('play'),'present',[],'icon-button','aria-label="Present this activity"'):''}${btn('×','close',[],'icon-button','aria-label="Close dialog"')}</header>${tabs}<div class="modal-content" id="modalBody">${body}${finishExtras()}</div>${ui.activity?activityStepBar():''}`;if(!already)d.showModal();hydrate(d);captureActivity();if(ui.present)applyPresent();syncActivityUI();if(already)restoreFocus(d,focus);if(!already)requestAnimationFrame(()=>$('#modalHeading')?.focus({preventScroll:true}));}
function closeModal(force=false){clearTimeout(searchTimer);if($('#modal').classList.contains('command-palette')&&ui.paletteReturn&&!force){const previous=ui.paletteReturn;ui.paletteReturn=null;$('#modal').replaceChildren(...previous.nodes);$('#modal').className=previous.classes;ui.activity=previous.activity;ui.tool=previous.tool;previous.focus?.focus();return true;}if(force)ui.paletteReturn=null;captureDraft();if(!force&&ui.dirty&&ui.activity&&!activityFinished()){if(!$('#leavePrompt'))$('#modalBody').insertAdjacentHTML('afterbegin',`<section class="notice leave-prompt" id="leavePrompt" role="alert"><h3>Leave this activity for now?</h3><p>Your progress is saved on this device so you can return.</p>${btn('Keep practising','stay',[],'secondary')}${btn('Save & close','close-saved',[],'primary')}</section>`);$('#leavePrompt button')?.focus();return false;}advStop();studioPause();clearInterval(breathTimer);if(ccSim)ccSim.playing=false;captureActivity();$('#modal').close();$('#modal').className='modal';exitPresent();ui.activity=currentPage==='studio'?(studioTab==='sbar'?'sbar-studio':studioTab):null;ui.paletteInlineActivity=null;ui.dirty=false;ui.tool=null;ui.present=false;document.body.classList.remove('present-mode');if(ui.modalTrigger?.isConnected)ui.modalTrigger.focus({preventScroll:true});return true;}
function hydrate(root=document){root.querySelectorAll('img').forEach(img=>{img.decoding='async';if(!img.closest('.hero'))img.loading='lazy';});root.querySelectorAll('button').forEach(b=>{for(const n of b.childNodes)if(n.nodeType===3)n.nodeValue=n.nodeValue.replaceAll('↗','→');});root.querySelectorAll('.notice,.source-context,.studio-safety-band,.studio-references,.adv-source,.illustrative-tag,.cc-sim-caption').forEach(e=>e.classList.add('disclosure-note'));}
function captureDraft(){if(ui.suspendCapture)return;const el=$('#reflection');if(el){const id=el.dataset.draft||activeLesson?.id||'general';state.reflections[id]=el.value;store.save();}const a=$('#actionText');if(a&&activeLesson){state.toolDrafts['action-'+activeLesson.id]=[a.value,$('#actionDue')?.value||laterDay(7)];store.save();}}
function openLesson(id,tab='learn',keepReview=false){if(!lessons.some(l=>l.id===id)){toast('That lesson is unavailable. Choose one from Learn.');return;}captureDraft();captureActivity();exitPresent();clearSelection();studioDispose();advStop();if(!keepReview)ui.review=null;if($('#modal').open)closeModal(true);ui.activity=null;ui.dirty=false;ui.completion=null;stopSpeech();activeLesson=lessons.find(l=>l.id===id);if(!activeLesson)return;lessonTab=tab;currentPage='lesson';hcaConfigureQuestion(id,0);delete lessonAnswers[id];render();recordRoute();$('#main').focus({preventScroll:true});}
function changeLessonTab(tab){captureDraft();stopSpeech();lessonTab=tab;render();recordRoute();$('#lessonPanel')?.focus({preventScroll:true});}
function completeLesson(){if(!state.checkRecords.some(r=>r.lesson===activeLesson.id)){toast('Try one practice prompt before recording this lesson as reviewed.');changeLessonTab('practice');return;}captureDraft();saveAction(activeLesson.id,true);if(!state.completed.includes(activeLesson.id))state.completed.push(activeLesson.id);ui.completion=activeLesson.id;persist();render();toast('One useful step, reviewed.');}
function toggleSave(id){const before=state.saved.slice(),was=before.includes(id);state.saved=was?before.filter(x=>x!==id):[...before,id];persist();render();toast(was?'Removed from Saved.':'Saved for later.',()=>{state.saved=before;persist();render();});}
function answerLesson(i){if(lessonAnswers[activeLesson.id]!==undefined)return;const q=HCA_BANK[activeLesson.id][hcaQuestionIndex],mapped=hcaAnswerMaps[q.id][i],correct=mapped===q.correct;lessonAnswers[activeLesson.id]=i;state.checkRecords.push({lesson:activeLesson.id,questionId:q.id,answerId:q.id+'-answer-'+mapped,choice:i,correct,date:new Date().toISOString()});const old=state.reviewQueue[activeLesson.id],streak=correct?Math.min(5,(old?.streak||0)+1):0;state.reviewQueue[activeLesson.id]={due:laterDay(correct?[1,3,7,14,30][Math.max(0,streak-1)]:1),streak};persist();render();}
function nextPrompt(){hcaConfigureQuestion(activeLesson.id,(hcaQuestionIndex+1)%3);delete lessonAnswers[activeLesson.id];render();}
function startReview(){const ids=lessons.filter(l=>due(l.id)).map(l=>l.id);if(!ids.length){toast('Nothing due. Choose a lesson at your own pace.');return;}ui.review={ids,index:0};openLesson(ids[0],'practice',true);}
function advanceReview(){if(!ui.review)return;if(++ui.review.index>=ui.review.ids.length){const n=ui.review.ids.length;ui.review=null;navigate('progress');toast(`${n} review ${n===1?'prompt':'prompts'} explored. A learning aid, not an assessment.`);}else openLesson(ui.review.ids[ui.review.index],'practice',true);}
function hcaStartReview(id){openLesson(id,'practice');}

function syncProfile(){const menu=$('.profile-menu');if(!menu)return;menu.querySelector('summary').textContent=state.name?state.name.slice(0,2).toUpperCase():'You';menu.querySelector('.menu-panel>strong').textContent=state.name||'Your learning space';menu.querySelector('.menu-panel>small').textContent=state.role;}
function clearSelection(){if($('#quickGuide')?.classList.contains('is-open'))closeGuide();ui.selectedQuote='';ui.noteLesson=null;ui.noteEdit=null;const tools=$('#selectionTools');if(tools)tools.hidden=true;}
function refreshAppearance(){captureDraft();applyPreferences();const crest=$('.brand img');if(crest)crest.src=ccIsDark()?HCA_CREST_DARK:HCA_CREST;document.querySelectorAll('[data-card-id] .card-art img').forEach(img=>{const l=lessons.find(l=>l.id===img.closest('[data-card-id]').dataset.cardId);if(l)img.src=INFO_PNG[l.id][0];});document.querySelectorAll('[data-activity-id] .card-art img').forEach(img=>{const a=HCA_ACTIVITIES.find(a=>a.id===img.closest('[data-activity-id]').dataset.activityId);if(a)img.src=ccTopicArtwork(a.id,a.type==='scenarios'?'knowledge':a.type==='team'?'attitudes':'skills');});if(currentPage==='lesson'&&activeLesson){const img=$('.reading-art img');if(img)img.src=INFO_PNG[activeLesson.id][0];}syncProfile();}

function rememberFocus(root){const el=document.activeElement;if(!el||!root?.contains(el))return null;return {id:el.id,tag:el.tagName,action:el.dataset.action,field:el.dataset.field,key:el.dataset.key,args:Array.from(el.attributes).filter(a=>/^data-(?:arg\d+|engine-\d+)$/.test(a.name)).map(a=>[a.name,a.value]),start:el.selectionStart,end:el.selectionEnd};}
function restoreFocus(root,record){if(!record||!root)return;let el=record.id?Array.from(root.querySelectorAll('[id]')).find(el=>el.id===record.id):null;if(!el&&(record.action||record.field))el=Array.from(root.querySelectorAll('[data-action],[data-field]')).find(el=>el.tagName===record.tag&&el.dataset.action===record.action&&el.dataset.field===record.field&&el.dataset.key===record.key&&record.args.every(([k,v])=>el.getAttribute(k)===v));if(!el||el.disabled){el=root.querySelector('.feedback,.studio-feedback,.cc-studio-report');if(el)el.tabIndex=-1;}el?.focus({preventScroll:true});if(el&&Number.isInteger(record.start)&&el.setSelectionRange)try{el.setSelectionRange(record.start,record.end);}catch{}}

function lessonCard(l){const s=status(l),saved=state.saved.includes(l.id);return `<article class="card lesson-card" data-action="lesson" data-arg0="${l.id}" data-card-id="${l.id}" role="link" tabindex="0" aria-label="Open ${esc(l.title)}"><button type="button" class="card-art infographic-card-art" data-action="infographics" data-arg0="${l.id}" aria-label="Open infographic pages for ${esc(l.title)}"><img src="${INFO_PNG[l.id][0]}" alt="" loading="lazy" decoding="async"><span>View visual guide ↗</span></button><div class="card-copy"><div class="card-meta"><span class="category ${l.cat}">${l.cat}</span><span>${l.time} min</span></div><h3>${esc(l.title)}</h3><p>${esc(l.description)}</p><div class="cs-card-row">${btn('Open visual guide ↗','infographics',[l.id],'secondary infographic-entry',`aria-label="View infographics: ${esc(l.title)}"`)}${studioCardButton(l)}</div><div class="card-status ${s==='Review due'?'is-due':''}">${icon(s==='Reviewed'?'check':'clock')}${s} · Start lesson →</div></div><div class="card-controls">${btn(icon('save'),'save',[l.id],'icon-button',`aria-label="${saved?'Unsave':'Save'} ${esc(l.title)}" aria-pressed="${saved}"`)}${btn(icon('preview'),'preview',[l.id],'icon-button quick-look',`aria-label="Preview ${esc(l.title)}"`)}</div></article>`;}
function activityCard(a){const category=a.type==='scenarios'?'knowledge':a.type==='team'?'attitudes':'skills';return `<article class="card activity-card" data-activity-id="${a.id}" data-action="activity" data-arg0="${a.id}" role="link" tabindex="0"><div class="card-art"><img src="${ccTopicArtwork(a.id,category)}" alt="Topic artwork for ${esc(a.title)}" loading="lazy" decoding="async"></div><div class="card-copy"><div class="card-meta"><span>${({scenarios:'Scenario',studios:'Interactive studio',simulations:'3D simulation',team:'Team practice'})[a.type]}</span><span>${activityMinutes(a)} min</span></div><h3>${esc(a.title)}</h3><p>${esc(a.desc)}</p><div class="card-status">${icon('practice')}Explore the activity →</div></div><div class="card-controls">${btn('ⓘ','guide',[a.id],'icon-button',`aria-label="Activity guide: ${esc(a.title)}"`)}</div></article>`;}
function activityMinutes(a){return a.type==='scenarios'?cases.find(c=>c.id===a.id)?.time||4:a.id==='movement'?3:5;}
function renderOnboarding(){const step=ui.onboard;return `<section class="onboarding"><div class="section-title"><div><span class="eyebrow">MAKE THIS SPACE YOURS · ${step+1} OF 3</span><h2>${['Your work. Your perspective.','What would help you today?','Make room for learning.'][step]}</h2></div><span class="onboard-steps">${[0,1,2].map(i=>`<i class="${i<=step?'active':''}"></i>`).join('')}</span></div><p>No account. Choose a starting point; you can change it later.</p>${step===0?`<label>Your learning role<select id="onboardRole">${roleOptions(state.role)}</select></label>`:step===1?`<label>Learning focus<select id="onboardFocus">${focusOptions(state.learningFocus)}</select></label>`:`<label>Minutes you would like to make room for<select id="onboardMinutes">${[2,5,10].map(n=>`<option value="${n}" ${n===ui.minutes?'selected':''}>${n} minutes</option>`).join('')}</select></label><p>Choose what fits; there are no streaks or penalties.</p>`}<div class="row">${step?btn('Back','onboard-back',[],'secondary'):''}${btn(step===2?'Begin my learning space →':'Continue →','onboard-next',[],'primary')}</div></section>`;}
function focusLessons(){const ids=({communication:['communication','sbar','shared','teachback-skill'],safety:['safety','infection','human-factors','med-transitions'],leadership:['inclusive-leadership','improvement','debrief','speakup'],digital:['ai','data-stewardship','reasoning','risk-evidence'],wellbeing:['wellbeing','compassion-boundaries','empathy','humility']})[state.learningFocus]||['communication'];return [...ids.map(id=>lessons.find(l=>l.id===id)),...lessons.filter(l=>!ids.includes(l.id))];}
function option(value,label,current){return `<option value="${esc(value)}" ${value===current?'selected':''}>${esc(label)}</option>`;}
function filteredLessons(){const f=ui.filters;let list=(currentPage==='saved'?lessons.filter(l=>state.saved.includes(l.id)):lessons).filter(l=>(f.category==='all'||l.cat===f.category)&&(f.topic==='all'||l.tag===f.topic)&&(f.length==='all'||l.time<=+f.length)&&(f.status==='all'||(f.status==='Saved'?state.saved.includes(l.id):status(l)===f.status)));if(f.sort==='shortest')list.sort((a,b)=>a.time-b.time);else if(f.sort==='az')list.sort((a,b)=>a.title.localeCompare(b.title));else list.sort((a,b)=>focusLessons().findIndex(l=>l.id===a.id)-focusLessons().findIndex(l=>l.id===b.id));return list;}
function filterSelect(name,label,values,value,scope='learn-filter'){return `<label class="filter-select"><span>${label}</span><select data-field="${scope}" data-key="${name}">${values.map(([v,t])=>option(v,t,value)).join('')}</select></label>`;}
function renderLearn(){const f=ui.filters,list=filteredLessons(),defaultGroup=ui.layout==='grouped'&&f.category==='all'&&f.topic==='all'&&f.length==='all'&&f.status==='all';return `${header(currentPage==='saved'?'Saved':'Learn','Knowledge for the work you do. Practical, connected essentials.')}<div class="collection-tabs">${btn('All lessons','navigate',['library'],currentPage==='library'?'selected':'ghost')}${btn('Pathways','navigate',['pathways'],'ghost')}${btn('Saved ('+state.saved.length+')','navigate',['saved'],currentPage==='saved'?'selected':'ghost')}</div>${currentPage==='library'?`<section class="learn-intro"><div><span class="eyebrow">THE LEARNING STUDIO</span><h2>Learn it as a guided slide journey.</h2><p>All 30 lessons are below: 10 Knowledge, 10 Skills and 10 Attitudes. Each opens as a slideshow with three ideas, a spotlight tour of its infographics, a worked example, three checks and a reflection. Annotate any slide as you go, or open a card to read the full lesson.</p>${studioIntroActions()}</div><div class="learn-intro-stats">${studioIntroStats()}</div></section>`:''}<div class="filter-bar" aria-label="Filter learning">${filterSelect('category','Category',[['all','All dimensions'],['knowledge','Knowledge'],['skills','Skills'],['attitudes','Attitudes']],f.category)}${filterSelect('topic','Topic',[['all','All topics'],...lessons.map(l=>[l.tag,l.tag])],f.topic)}${filterSelect('length','Length',[['all','Any length'],['5','5 min or less'],['10','10 min or less']],f.length)}${filterSelect('status','Status',[['all','Any status'],...['Not started','In progress','Reviewed','Review due','Saved'].map(x=>[x,x])],f.status)}${filterSelect('sort','Sort',[['recommended','Recommended'],['shortest','Shortest'],['az','A–Z']],f.sort)}<div class="layout-options">${btn(icon('room'),'layout',['grouped'],ui.layout==='grouped'?'selected':'icon-button','aria-label="Grouped grid"')}${btn(icon('book'),'layout',['list'],ui.layout==='list'?'selected':'icon-button','aria-label="Compact list"')}${btn('Reset','reset-filters',[],'ghost')}</div></div><div class="result-count">${list.length} lessons · 90 practice prompts · 3 visual pages for each lesson</div>${list.length?defaultGroup?['knowledge','skills','attitudes'].map(cat=>`<section class="learning-group"><div class="section-title"><h2>${cat[0].toUpperCase()+cat.slice(1)}</h2><span class="group-count">10 lessons · read, check, reflect</span></div><div class="card-grid">${list.filter(l=>l.cat===cat).map(lessonCard).join('')}</div></section>`).join(''):`<div class="card-grid ${ui.layout==='list'?'list-layout':''}">${list.map(lessonCard).join('')}</div>`:`<div class="empty"><h3>A different route might help.</h3><p>Clear the filters to return to all lessons.</p>${btn('Reset your view','reset-filters',[],'secondary')}</div>`}`;}
function renderPathways(){return `${header('Learning pathways','Five connected routes through existing lessons and practice.')}<div class="pathway-grid">${PATHWAYS.map(p=>{const count=p.lessons.filter(id=>state.completed.includes(id)).length+p.activities.filter(id=>state.studioAttempts.some(r=>activityRecordMatches(r.activity,id))||state.branchRecords.some(r=>r.case===id)).length,total=p.lessons.length+p.activities.length;return `<article class="card pathway-card"><div class="section-title">${ring(count/total*100)}${chip(count+' / '+total+' explored')}</div><h2>${p.title}</h2><p>${p.description}</p><ol>${p.lessons.map(id=>`<li>${btn((state.completed.includes(id)?'✓ ':'')+esc(lessons.find(l=>l.id===id).title),'lesson',[id],'ghost')}</li>`).join('')}</ol><div class="pathway-activities">${p.activities.map(id=>btn(icon('practice')+' '+esc(HCA_ACTIVITIES.find(a=>a.id===id).title),'activity',[id],'secondary')).join('')}</div>${count===total?`<div class="completion"><h3>You explored this pathway.</h3><p>Choose one action to try and return to reflect. This records learning activity, not clinical competence.</p></div>`:btn('Continue pathway →','lesson',[p.lessons.find(id=>!state.completed.includes(id))||p.lessons[0]])}</article>`;}).join('')}</div>`;}
function readingText(t,id=activeLesson?.id){let result=esc(t);for(const note of state.notes.filter(n=>n.lesson===id&&n.quote)){const q=esc(note.quote);if(result.includes(q))result=result.split(q).join(`<mark data-note-id="${esc(note.id)}">${q}</mark>`);}return result;}
function renderLesson(){const l=activeLesson,tab=lessonTab,index=['learn','practice','reflect'].indexOf(tab),notes=state.notes.filter(n=>n.lesson===l.id),speech=!!window.speechSynthesis;const context=CC_USE[l.id]||['Healthcare learners and practitioners.','When preparing or reflecting on this topic.'];let body='';if(tab==='learn')body=`${studioLessonCard(l)}<section class="lesson-opening"><div class="lesson-opening-copy"><span class="eyebrow">THE LESSON · ${l.time} MINUTES</span><h3>Start here</h3><p class="lead">${readingText(l.description)}</p><p>Read the three ideas below, compare the fictional responses, then test your understanding. The visual guide is a companion to this full lesson.</p><div class="lesson-map"><span><b>01</b> Learn the ideas</span><span><b>02</b> Compare a response</span><span><b>03</b> Check & reflect</span></div></div><button type="button" class="reading-art" data-action="infographics" data-arg0="${l.id}" aria-label="Open three infographic pages for ${esc(l.title)}"><img src="${INFO_PNG[l.id][0]}" alt="Preview of the ${esc(l.title)} visual guide" decoding="async"><span>Explore 3 infographic pages ↗</span></button></section><section class="learning-brief"><div><strong>Who it helps</strong><p>${esc(context[0])}</p></div><div><strong>Use it when</strong><p>${esc(context[1])}</p></div><div class="full"><strong>One action to practise</strong><p>${readingText(P2_DATA.examples[l.id].action)}</p></div></section><section class="outcomes"><h3>By the end, you can…</h3><ul><li>${esc(l.outcome||'Explain '+l.tag.toLowerCase()+' using a clear principle and a worked example.')}</li><li>Recognise a less helpful response and explain a stronger alternative.</li><li>Choose one action to rehearse within your role and local policy.</li></ul></section><div class="lesson-reading-title"><span class="eyebrow">CORE READING</span><h3>Three ideas to use in practice</h3><p>Take these in order. Each explains what to notice and how to respond within your role and local policy.</p></div>${l.steps.map(([t,b],i)=>`<section class="learning-step" data-paragraph="${i}"><span class="step-num">${i+1}</span><div><h3>${esc(t)}</h3><p>${readingText(b)}</p></div></section>`).join('')}<section class="lesson-transfer"><span class="eyebrow">DEEPER READING</span><h3>What to notice and carry forward</h3>${LESSON_NOTES[l.id].map((note,i)=>`<div class="transfer-note"><span>${i===0?'Notice':'Use it'}</span><p>${readingText(note)}</p></div>`).join('')}</section>${renderWorkedExample(l)}<aside class="takeaway"><span class="eyebrow">ONE THING TO REMEMBER</span><p>${readingText(l.takeaway)}</p></aside>${btn('Check understanding →','lesson-tab',['practice'])}`;
 if(tab==='practice'){const chosen=lessonAnswers[l.id];body=`${ui.review?`<div class="review-session">Smart Review · ${ui.review.index+1} of ${ui.review.ids.length} · A learning aid, not an assessment</div>`:''}<span class="eyebrow">PROMPT ${hcaQuestionIndex+1} OF 3</span><p>Choose a response, then explore the reasoning for every option.</p><h3 class="question">${esc(l.question)}</h3><div class="answer-list">${l.answers.map((a,i)=>btn(`<span class="letter">${'ABC'[i]}</span><span>${esc(a)}</span>`,'answer',[i],`answer ${chosen!==undefined?(i===l.correct?'correct':chosen===i?'incorrect':''):''}`,chosen!==undefined?'disabled':'')).join('')}</div>${chosen!==undefined?`<section class="feedback ${chosen===l.correct?'good':''}" role="status"><h3>${chosen===l.correct?'A useful approach.':'A useful moment to pause.'}</h3><p>${esc(l.rationales[chosen])}</p></section><details class="reasoning"><summary>Explore every option</summary>${l.answers.map((a,i)=>`<div><strong>${'ABC'[i]} · ${i===l.correct?'More helpful approach':'Alternative approach'}</strong><p>${esc(l.rationales[i])}</p></div>`).join('')}</details><div class="row">${btn('Try another prompt','next-prompt',[],'secondary')}${ui.review?btn('Next review →','review-next'):btn('Continue to reflection →','lesson-tab',['reflect'])}</div>`:''}`;}
 if(tab==='reflect'){const action=state.actions.find(a=>a.lesson===l.id&&a.status==='planned');body=`<h3>Turn one insight into a next step.</h3><p>${esc(l.reflect)}</p><label>My reflection (optional)<textarea id="reflection" data-field="reflection" data-draft="${l.id}" maxlength="3000" placeholder="One thing I will try differently…">${esc(state.reflections[l.id]||'')}</textarea></label><p class="field-hint">Saved as you type. Private notes stay on this device; keep confidential details out.</p><section class="outcomes"><h3>Make it useful beyond this page.</h3><label>My next action<textarea id="actionText" maxlength="700" data-field="action-draft" placeholder="${esc(P2_DATA.examples[l.id].action)}">${esc(state.toolDrafts['action-'+l.id]?.[0]??action?.text??'')}</textarea></label><label>Return to review it<input id="actionDue" data-field="action-draft" type="date" value="${state.toolDrafts['action-'+l.id]?.[1]||action?.due||laterDay(7)}"></label>${btn('Save my action & review date','save-action',[l.id],'secondary')}</section>${disclosure('Learning activity · not clinical competence or CPD/CME credit')}<div class="row">${btn(state.completed.includes(l.id)?'Save & finish ✓':'Mark as reviewed ✓','complete')}</div>`;}
 return `${header('Learn',l.tag)}<header class="lesson-header"><div><span class="eyebrow">${l.cat} · ${Math.max(1,Math.ceil(l.time*(3-index)/3))} min remaining, estimated</span><h2>${esc(l.title)}</h2></div><div class="lesson-controls">${btn(icon('save'),'save',[l.id],'icon-button',`aria-label="Save lesson" aria-pressed="${state.saved.includes(l.id)}"`)}${btn(icon('research'),'lesson-evidence',[l.id],'icon-button','aria-label="Evidence and sources"')}${btn('Infographics','infographics',[l.id],'secondary')}${btn('Focus','focus',[],'secondary','aria-label="Toggle focus view"')}</div><div class="lesson-tabs" role="tablist" aria-label="Lesson steps">${[['learn','Learn'],['practice','Check'],['reflect','Reflect']].map(([key,label],i)=>`<button role="tab" id="tab-${key}" data-action="lesson-tab" data-arg0="${key}" aria-controls="lessonPanel" aria-selected="${tab===key}" tabindex="${tab===key?0:-1}"><span>${i+1}</span>${label}</button>`).join('')}</div>${progress((index+1)/3*100,'Lesson steps')}</header><div class="lesson-layout"><article class="reading" id="lessonPanel" role="tabpanel" aria-labelledby="tab-${tab}" tabindex="-1">${speech?`<div class="read-aloud">${btn(icon('play')+' Read aloud','speak',[],'ghost')}${btn('Pause / resume','speech-pause',[],'ghost')}<label>Speed<select data-field="speech-speed">${[.8,1,1.2,1.5].map(n=>option(String(n),n+'×',String(ui.readSpeed))).join('')}</select></label><span id="speechStatus" role="status"></span></div>`:''}${body}${ui.completion===l.id?renderCompletion(l):''}<div class="next-learning"><h3>Keep a useful thought moving.</h3><div class="card-grid two"><div><span class="eyebrow">NEXT LESSON</span>${btn(esc(nextLesson(l).title)+' →','lesson',[nextLesson(l).id],'secondary')}</div><div><span class="eyebrow">RELATED PRACTICE</span>${btn(esc(relatedActivity(l).title)+' →','activity',[relatedActivity(l).id],'secondary')}</div></div></div></article><aside class="notes-sidebar"><div class="section-title"><h3>Your notes</h3>${btn('+','note',[],'icon-button','aria-label="Add a lesson note"')}</div><p class="field-hint">Select reading text to highlight it or attach a note.</p>${notes.length?notes.map(renderNote).join(''):'<p class="muted">A thought worth keeping can start here.</p>'}${btn('Evidence & sources →','lesson-evidence',[l.id],'secondary')}</aside></div>`;}
function renderWorkedExample(l){const e=P2_DATA.examples[l.id],mode=exampleModes[l.id]||'poor';const copy=(kind,label)=>`<section class="example-copy ${kind}"><h4>${label}</h4><p>“${readingText(e[kind])}”</p></section>`;return `<section class="worked-example"><span class="eyebrow">FICTIONAL WORKED EXAMPLE</span><h3>Notice the difference.</h3><p>${esc(e.situation)}</p><div class="segmented">${[['poor','Needs improvement'],['good','Stronger approach'],['compare','Compare both']].map(([v,t])=>btn(t,'example',[v],mode===v?'selected':'ghost',`aria-pressed="${mode===v}"`)).join('')}</div><div class="${mode==='compare'?'comparison':''}">${mode==='compare'?copy('poor','Needs improvement')+copy('good','Stronger approach'):copy(mode,mode==='good'?'Stronger approach':'Needs improvement')}</div><details ${mode!=='poor'?'open':''}><summary>Why the approach matters</summary><ul>${e.why.map(t=>`<li>${esc(t)}</li>`).join('')}</ul></details>${btn('Try the related tool →','tool',[e.tool],'secondary')}</section>`;}
function nextLesson(l){return focusLessons().find(x=>x.id!==l.id&&!state.completed.includes(x.id))||lessons[(lessons.indexOf(l)+1)%lessons.length];}
function relatedActivity(l){return HCA_ACTIVITIES.find(a=>CC_STUDIOS.find(s=>s.id===a.id)?.lesson===l.id||CC_SIMS.find(s=>s.id===a.id)?.lesson===l.id)||HCA_ACTIVITIES.find(a=>a.id==='handover');}
function renderCompletion(l){return `<section class="completion" role="status"><span class="completion-check">✓</span><h2>One useful step, reviewed.</h2><p>You explored ${esc(l.tag.toLowerCase())}. Return when you are ready to recall it.</p>${disclosure('Record of learning activity · not a credential')}</section>`;}
function renderPractice(){const f=ui.practice,items=HCA_ACTIVITIES.filter(a=>(f.format==='all'||a.type===f.format)&&(f.duration==='all'||activityMinutes(a)<=+f.duration)&&(f.topic==='all'||(a.title+' '+a.desc).toLowerCase().includes(f.topic))&&(f.mode==='all'||(f.mode==='team'?a.type==='team':a.type!=='team')));return `${header('Practice','Watch, decide, try another approach. Fictional practice with room to pause.')}<div class="filter-bar">${filterSelect('format','Format',[['all','All formats'],['scenarios','Scenario'],['studios','Interactive studio'],['simulations','3D simulation'],['team','Team practice']],f.format,'practice-filter')}${filterSelect('duration','Duration',[['all','Any length'],['3','3 min or less'],['5','5 min or less']],f.duration,'practice-filter')}${filterSelect('topic','Topic',[['all','All topics'],['handover','Handover'],['risk','Risk'],['communication','Communication'],['team','Team'],['decision','Decisions']],f.topic,'practice-filter')}${filterSelect('mode','Work with',[['all','Solo or team'],['solo','Individual'],['team','Team']],f.mode,'practice-filter')}</div><div class="result-count">${items.length} activities · ${disclosure()}</div>${items.length?`<div class="card-grid">${items.map(activityCard).join('')}</div>`:empty('Try another combination.','Change a filter to find a different practice.','practice','Reset practice filters')}<p class="footnote">These original educational exercises are not clinical certification or patient-specific advice. Keep practice fictional, work within your role and follow local policies.</p>`;}
function renderActivity(){const a=HCA_ACTIVITIES.find(x=>x.id===ui.activity);return `${header(a?.title||'Interactive studio','Original fictional learning activity · At your pace.')}<div class="activity-toolbar">${btn('← All practice','navigate',['practice'],'secondary')}${btn('Present','present',[],'secondary')}${btn('Activity guide','guide',[a?.id||'hygiene'],'ghost')}</div><section class="studio-workbench" id="studioWorkbench">${studioWorkbench()}</section>${finishExtras()}${activityStepBar()}<div id="studioLog">${studioLogHtml()}</div>`;}
function renderToolkit(){return `${header('Toolkit','Practical prompts, editable templates and space to reset.')}<p class="footnote">Use fictional details. These learning aids do not replace local policies, required checks or clinical records.</p>${['Quick tools','Templates','Wellbeing'].map(group=>`<section><div class="section-title"><h2>${group}</h2></div><div class="card-grid">${TOOLS.filter(t=>t[2]===group).map(([id,title,_,description,art])=>`<article class="card tool-card"><span class="tool-symbol">${icon(art)}</span><h3>${title}</h3><p>${description}</p>${btn('Open '+(group==='Templates'?'template':'tool')+' →','tool',[id],'secondary')}</article>`).join('')}</div></section>`).join('')}`;}
function renderGrowth(){const trail=[...state.studioAttempts.map(r=>({...r,type:'Practice'})),...state.branchRecords.map(r=>({id:r.id,label:cases.find(c=>c.id===r.case)?.title||'Scenario',date:r.date,detail:r.path.map(p=>p.label+' — '+p.feedback).join('\n'),type:'Scenario'}))].sort((a,b)=>Date.parse(b.date)-Date.parse(a.date));const activityDates=[...state.checkRecords,...state.studioAttempts,...state.branchRecords].map(r=>r.date?.slice(0,10));return `${header('My Growth','A personal learning record. Space to notice, return and adapt.')}<div class="section-title"><div class="week-strip" aria-label="Learning activity in the last seven days">${Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-6+i);const n=activityDates.filter(x=>x===localDay(d)).length;return `<div class="${n?'has-activity':''}" title="${n} learning activities"><span>${d.toLocaleDateString('en-GB',{weekday:'short'})}</span><i>${n||'·'}</i></div>`;}).join('')}</div><div class="row">${btn('Your data','data',[],'secondary')}${btn('Print record','print',[],'ghost')}</div></div><section class="review-banner"><div><span class="eyebrow">SMART REVIEW</span><h2>${hcaDue().length} topics ready to revisit</h2><p>A learning aid, not an assessment. Review intervals: 1, 3, 7, 14 and 30 days.</p></div>${btn('Start review ('+hcaDue().length+')','review',[],'primary',hcaDue().length?'':'disabled')}</section><section><div class="section-title"><h2>Your topic coverage</h2><div class="row">${chip('Not started')}${chip('Reviewed','good')}${chip('Review due','warning')}</div></div><div class="coverage-map">${lessons.map(l=>`<button class="coverage ${status(l)==='Review due'?'due':state.completed.includes(l.id)?'reviewed':''}" data-action="lesson" data-arg0="${l.id}"><span>${icon(l.id)}</span><strong>${esc(l.tag)}</strong><small>${status(l)}</small></button>`).join('')}</div></section><section class="growth-grid"><div><div class="section-title"><h2>Practice trail</h2></div>${trail.length?trail.map(r=>`<details class="trail"><summary><span>${esc(r.label)}</span><small>${new Date(r.date).toLocaleDateString('en-GB')}</small></summary><p class="preserve-lines">${esc(r.detail)}</p>${disclosure('Self-reported learning activity')}</details>`).join(''):empty('Your practice trail starts with a try.','Explore a fictional decision and save its debrief.','practice','Find a practice →')}</div><div><div class="section-title"><h2>Actions to revisit</h2></div>${state.actions.length?state.actions.map(a=>`<article class="action-item"><h3>${esc(a.text)}</h3><p>${esc(lessons.find(l=>l.id===a.lesson)?.tag||'Learning')} · Review ${esc(a.due)}</p><label>Status<select data-field="action-status" data-key="${esc(a.id)}">${['planned','tried','revised'].map(v=>option(v,v[0].toUpperCase()+v.slice(1),a.status)).join('')}</select></label><label>What did you notice?<textarea data-field="action-review" data-key="${esc(a.id)}">${esc(a.review||'')}</textarea></label></article>`).join(''):empty('One insight can become an action.','Keep a next step in the Reflect section of a lesson.','library','Choose a lesson →')}</div></section><section><div class="section-title"><h2>Reflections & notes</h2></div>${Object.entries(state.reflections).filter(([,v])=>v.trim()).map(([id,v])=>`<article class="reflection-item"><h3>${esc(lessons.find(l=>l.id===id)?.title||'General reflection')}</h3><p>${esc(v)}</p>${btn('Delete reflection','delete-reflection',[id],'ghost')}</article>`).join('')}${state.notes.map(renderNote).join('')}${!Object.values(state.reflections).some(v=>v.trim())&&!state.notes.length?'<p class="muted">A useful thought does not have to be long. Your private reflections will appear here.</p>':''}</section>`;}
function renderNote(n){return `<article class="note" id="note-${esc(n.id)}">${n.quote?`<blockquote>${esc(n.quote)}</blockquote>`:''}<p>${esc(n.text||'Highlighted for later.')}</p><div class="row">${btn('Edit','edit-note',[n.id],'ghost')}${btn('Delete','delete-note',[n.id],'ghost')}</div></article>`;}
function renderSettings(){return `<form id="preferences"><div class="form-grid"><label>First name (optional)<input id="prefName" maxlength="35" value="${esc(state.name)}" autocomplete="given-name"></label><label>Your learning role<select id="prefRole">${roleOptions(state.role)}</select></label><label>Your focus<select id="prefFocus">${focusOptions(state.learningFocus)}</select></label><label>Setting<select id="prefSetting">${['Hospital','Community care','Primary care','Education & training','Other / exploring'].map(v=>option(v,v,state.setting)).join('')}</select></label><label>Reading text size<select id="prefText">${[[17,'Comfortable'],[19,'Larger'],[21,'Largest']].map(([v,t])=>option(String(v),t,String(state.textSize))).join('')}</select></label><label>Daily learning time<select id="prefMinutes">${[...new Set([2,5,10,+state.goal])].sort((a,b)=>a-b).map(n=>option(String(n),n+' minutes',String(state.goal))).join('')}</select></label><label class="check"><input id="prefMotion" type="checkbox" ${state.reduceMotion?'checked':''}>Reduce motion</label><label class="check"><input id="prefDyslexia" type="checkbox" ${state.dyslexia?'checked':''}>Dyslexia-friendly spacing</label></div><p class="field-hint">Private notes stay on this device. Nothing is sent to a server.</p>${btn('Save preferences','save-settings',[],'primary','type="button"')}</form>`;}
function roleOptions(current){return [...new Set(['Healthcare practitioner','Physician','Nurse or midwife','Pharmacist','Allied health professional','Student or trainee','Healthcare leader','Other care professional',current])].map(v=>option(v,v,current)).join('');}
function focusOptions(current){return [['communication','Communication & partnership'],['safety','Safety & clear thinking'],['leadership','Teams & improvement'],['digital','Digital & AI literacy'],['wellbeing','Sustainable, human practice']].map(([v,t])=>option(v,t,current)).join('');}

/* Today: a calm, personal starting point and a voluntary guided introduction. */
/* My Day: a bento home built on the shared HCA shell (apps/shared). The scenario is answerable in place. */
function ccHomeData(){
 const picked=focusLessons().slice(0,3),next=picked.find(l=>!state.completed.includes(l.id))||picked[0],sc=scenarioOfDay(),st=scenarioState(),today=st.days[localDay()];
 const chosen=today&&today.id===sc.id&&Number.isInteger(today.answer)?today.answer:null,answered=chosen!==null;
 const activity=HCA_ACTIVITIES.find(a=>a.id===(ui.minutes===2?'movement':state.learningFocus==='digital'?'ai-case':'handover'))||HCA_ACTIVITIES[0];
 const ls=state.lastSession,sessionToday=!!(ls&&ls.date&&new Date(ls.date).toDateString()===new Date().toDateString());
 return {picked,next,sc,st,chosen,answered,activity,ls,sessionToday,reviews:hcaDue().length,reviewed:state.completed.length,stats:scenarioStats()};
}
function ccPlanItems(D){
 const m=ui.minutes,items=[{title:D.sc.title,sub:'1 min · today’s scenario',done:D.answered,cta:{label:D.answered?'Revisit':'Start',attrs:{'data-action':'day-start'}}}];
 const act={title:D.activity.title,sub:activityMinutes(D.activity)+' min · practice',cta:{label:'Try it',attrs:{'data-action':'activity','data-arg0':D.activity.id}}};
 if(m===2)items.push({title:'A quiet minute',sub:'1 min · breathing reset',cta:{label:'Begin',attrs:{'data-action':'tool','data-arg0':'pause'}}});
 else if(m===5){items.push(act);items.push({title:'A quiet minute',sub:'1 min · breathing reset',cta:{label:'Begin',attrs:{'data-action':'tool','data-arg0':'pause'}}});}
 else{items.push({title:D.next.title,sub:D.next.time+' min · lesson',cta:{label:'Open',attrs:{'data-action':'lesson','data-arg0':D.next.id}}});if(1+D.next.time+activityMinutes(D.activity)<=10)items.push(act);}
 return items;
}
function ccFan(D){return `<div class="cc-fan" role="img" aria-label="Today’s scenario: ${esc(D.sc.title)}"><div class="cc-sc cc-sc3"></div><div class="cc-sc cc-sc2"></div><div class="cc-sc cc-sc1"><span class="cc-tag">${esc(D.sc.tag.toUpperCase())}</span><b>${esc(D.sc.title)}</b><i class="cc-line"></i><i class="cc-line cc-short"></i><span class="cc-opts"><u>A</u><u>B</u><u>C</u></span></div></div>`;}
function renderHome(){
 const S=window.HCAShell;if(!S)return renderHomeClassic();
 const D=ccHomeData(),wh=S.when(),first=(state.name||'').trim().split(/\s+/)[0],s=D.stats;
 const mode=D.answered?(D.ls&&!D.sessionToday?'resume':'done'):'start';
 const h1={start:'Your scenario <em>is ready.</em>',resume:'Pick up <em>where you left off.</em>',done:'That’s today <em>done.</em>'}[mode];
 const lead={start:`${first?first+', one':'One'} moment from a working day. Think first, then compare the reasoning.`,resume:`${first?first+', your':'Your'} place is kept: ${resumeTitle()}.`,done:`${first?'Lovely, '+first+'. ':'Lovely. '}Another scenario keeps the habit warm.`}[mode];
 const nextHook=HOOK_FIRST.filter(x=>x!==D.sc.id)[(new Date().getDate())%(HOOK_FIRST.length-1)]||HOOK_FIRST[0];
 const hero={eyebrow:wh.eyebrow,h1,lead,
  primary:mode==='start'?{label:'Start the scenario',icon:'play',attrs:{'data-action':'day-start'}}:mode==='resume'?{label:'Resume',icon:'play',attrs:{'data-action':'resume'}}:{label:'Done ✓',arrow:false,attrs:{'aria-disabled':'true','data-action':'day-start'}},
  secondary:mode==='done'?{label:'Another scenario',attrs:{'data-action':'scenario-open','data-arg0':nextHook},arrow:false}:{label:'Show me around',attrs:{'data-action':'app-guide'},arrow:false},
  meta:[{icon:'clock',text:'1 minute'},{icon:'layers',text:D.sc.tag},{icon:'check',text:'Fictional · practice only'}],art:ccFan(D)};
 const fresh=!s.answered&&!D.reviewed&&!D.ls,steps=(D.answered?1:0)+(D.sessionToday?1:0);
 const progress={eyebrow:'Today’s steps',streak:s.streak>0?s.streak:null,pct:fresh?0:steps/2,main:fresh?'1':steps,sub:fresh?'min to start':'of 2 steps',ringLabel:fresh?'One minute to start':`${steps} of 2 steps today`,
  title:fresh?'Your first step today starts your streak':steps>=2?'Both steps done. Lovely.':'Small steps. Lasting value.',empty:fresh?'One scenario is all it takes. Rest is part of learning.':null,text:`${s.answered} ${s.answered===1?'scenario':'scenarios'} explored · ${s.strongest} strongest ${s.strongest===1?'choice':'choices'}.`,
  week:S.week(new Set(Object.keys(D.st.days))),strip:[{v:String(D.reviewed),l:'of 30 reviewed'},{v:String(D.reviews),l:'to revisit'},{v:String(state.saved.length),l:'saved'}]};
 const scenarioHtml=`<div id="dailyScenario" class="cc-daily">${scenarioBody(D.sc,'daily',D.chosen)}</div>${D.chosen!==null?scenarioFooter(D.sc,'daily'):''}`;
 const cont=D.ls?{icon:'book',eyebrow:'Continue where you left off',title:esc(resumeTitle()),body:D.ls.kind==='activity'?'Pick up from your saved practice checkpoint.':'Return to the lesson step you last explored.',sub:D.ls.kind==='activity'?'Practice checkpoint':'Lesson · step '+(['learn','practice','reflect'].indexOf(D.ls.tab)+1||1)+' of 3',cta:{label:'Continue',attrs:{'data-action':'resume'}}}
  :{icon:'book',eyebrow:'Start a lesson',title:esc(D.next.title),body:esc(D.next.description||D.next.tag),sub:D.next.tag+' · '+D.next.time+' min',cta:{label:'Open the lesson',attrs:{'data-action':'lesson','data-arg0':D.next.id}}};
 const prac={icon:'practice',eyebrow:'Try something today',title:esc(D.activity.title),body:esc(D.activity.desc),sub:activityMinutes(D.activity)+' min · Fictional learning',cta:{label:'Explore this practice',attrs:{'data-action':'activity','data-arg0':D.activity.id}}};
 const chips=`<div class="hs-seg" role="group" aria-label="Time you have">${[2,5,10].map(n=>`<button type="button" data-action="minutes" data-arg0="${n}" aria-pressed="${ui.minutes===n}">${n} min</button>`).join('')}</div>`;
 const poster=(typeof INFO_PNG!=='undefined'&&INFO_PNG[D.next.id]||[])[0];
 const atlas=`<button type="button" class="hs-card hs-atlas hs-c4 is-link" data-action="infographics" data-arg0="${esc(D.next.id)}"><div class="hs-atlas-img" aria-hidden="true">${poster?`<img src="${poster}" alt="" width="640" height="360" loading="lazy" decoding="async">`:''}</div><div class="hs-atlas-body"><p class="hs-eyebrow">Visual Atlas</p><h3>See the idea in one page.</h3><p>A three-page visual guide for every lesson: understand, apply, remember.</p><span class="hs-link"><span>Open the Atlas</span>${icon('arrow')}</span></div></button>`;
 const gs=!state.onboarded?`<aside class="hs-card hs-gs hs-c4 is-static" aria-label="Getting started"><button type="button" class="hs-x" data-action="gs-skip" aria-label="Skip getting started"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" aria-hidden="true"><path d="M6 6l12 12M18 6L6 18"/></svg></button>${renderOnboarding()}</aside>`:'';
 const items=[{kind:'act',icon:'spark',eyebrow:'Today’s scenario',html:scenarioHtml,cls:'hs-star'},Object.assign({kind:'act'},cont),Object.assign({kind:'act'},prac),
  {kind:'path',eyebrow:'Your plan',title:ui.minutes+'-minute plan',head:chips,items:ccPlanItems(D),foot:`<span class="hs-quote-mark" aria-hidden="true">“</span><blockquote id="quoteText">${esc(quotes[quoteIndex])}</blockquote>${btn('Next quote →','quote-next',[],'ghost')}`}];
 if(gs){items.push({kind:'raw',html:gs,el:S.h('div',{class:'hs-c4 hs-gs-wrap'},gs)});items.push({kind:'raw',cls:'hs-c12',el:S.h('div',{class:'hs-c12'},atlas.replace('hs-c4','hs-c12'))});}else items.push({kind:'raw',cls:'hs-c4',el:S.h('div',{class:'hs-c4'},atlas)});
 const day=S.day({hero,progress,items});
 return day.outerHTML;
}
function ccAfterRender(){
 const S=window.HCAShell,host=document.querySelector('[data-hs-day]');if(!S||!host||host.dataset.live)return;host.dataset.live='1';
 S.animate(host);const hero=host.querySelector('.hs-hero');if(hero)S.tilt(hero,10);
}
function ccShellInit(){
 const S=window.HCAShell;if(!S)return;
 S.init({app:'carecraft',observe:'body',mcrest:()=>ccIsDark()?HCA_CREST_DARK:HCA_CREST,name:'Carecraft',dayName:'My Day',home:'#/dashboard',help:()=>openAppGuide(0),
  sel:{side:'#sidebar',brand:'.brand',navs:['nav'],top:'.topbar',crumbs:'.breadcrumb',search:'.search-launch',theme:'[data-action=appearance]',moveRight:['[data-action=appearance]','.profile-menu'],tabs:'.bottom-nav',content:'.workspace'},
  groups:[{first:'My Day',label:'Start'},{first:'Learn',label:'Build skills'},{first:'My Growth',label:'Reflect'}],
  motionOff:'.reduce-motion,[data-motion=reduce],.reduced-motion',drawer:on=>toggleMenu(on),
  streak:()=>{try{const n=scenarioStreak();return{text:n,label:n?n+'-day scenario streak':'Answer a scenario to start a streak'};}catch{return null;}}});
}
function renderHomeClassic(){

 const picked=focusLessons().slice(0,3),next=picked.find(l=>!state.completed.includes(l.id))||picked[0];
 const activity=HCA_ACTIVITIES.find(a=>a.id===(ui.minutes===2?'movement':state.learningFocus==='digital'?'ai-case':'handover'));
 const reviews=hcaDue().length,reviewed=state.completed.length;
 const date=new Date().toLocaleDateString('en-GB',{weekday:'long',day:'numeric',month:'long'});
 const welcome=state.name?'Welcome'+(state.onboarded?' back':'')+', '+esc(state.name)+'.':state.onboarded?'Welcome back.':'Welcome to your learning space.';
 return `<div class="today-masthead"><div><span class="eyebrow">CARECRAFT · HEALTHCARE CROWN ACADEMY</span><h1>Today</h1></div><span class="today-date">${icon('clock')}${date}</span></div>
 <section class="hero welcome-hero"><div class="welcome-copy"><span class="welcome-greeting"><i aria-hidden="true"></i>${welcome}</span><h2>A little learning.<br><em>A better next step.</em></h2><p>Space to build your knowledge, practise a skill and bring more intention to everyday care.</p><div class="welcome-time"><span>Make a little room</span><div class="segmented" aria-label="Available learning time">${[2,5,10].map(n=>btn(n+' min','minutes',[n],ui.minutes===n?'selected':'ghost',`aria-pressed="${ui.minutes===n}"`)).join('')}</div></div><div class="welcome-actions">${ui.minutes===2?btn('Take a quiet minute →','tool',['pause']):btn('Explore today’s lesson →','lesson',[next.id])}${btn('Show me around','app-guide',[],'ghost')}</div><small>${ui.minutes===2?'One optional quiet minute, then choose your next step.':esc(next.tag)+' · '+next.time+' min · At your own pace'}</small></div><div class="welcome-visual"><img src="${ASSETS['today-welcome']}" alt="An open book with sculpted symbols of conversation, human care and connected ideas." fetchpriority="high"><span class="welcome-visual-label">Knowledge. Practice. Human care.</span><div class="welcome-orbit orbit-one" aria-hidden="true">${icon('book')}</div><div class="welcome-orbit orbit-two" aria-hidden="true">${icon('practice')}</div></div></section>
 ${!state.onboarded?renderOnboarding():state.lastSession?`<section class="continue-card today-continue"><span class="continue-mark">${icon('clock')}</span><div><span class="eyebrow">YOUR PLACE IS KEPT</span><h3>${esc(resumeTitle())}</h3><p>${state.lastSession.kind==='activity'?'Pick up from your saved practice checkpoint.':'Return to the lesson step you last explored.'}</p></div>${btn('Continue →','resume',[],'secondary')}</section>`:''}
 ${renderDailyScenario()}
 <section class="today-plan"><div class="section-title"><div><span class="eyebrow">ONE USEFUL STEP</span><h2>Where would you like to begin?</h2></div><span class="today-gentle-note">Curiosity is a good starting point.</span></div><div class="today-entry-grid"><button class="today-entry entry-learn" data-action="navigate" data-arg0="library"><span class="entry-icon">${icon('book')}</span><span class="entry-label">01 · LEARN</span><h3>Find an idea worth keeping.</h3><p>30 short lessons, clear explanations and illustrated guides.</p><span class="entry-link">Explore the library <b aria-hidden="true">↗</b></span></button><button class="today-entry entry-practice" data-action="navigate" data-arg0="practice"><span class="entry-icon">${icon('practice')}</span><span class="entry-label">02 · PRACTISE</span><h3>Turn an idea into a try.</h3><p>Fictional scenarios, interactive studios and 3D simulations.</p><span class="entry-link">Choose a practice <b aria-hidden="true">↗</b></span></button><button class="today-entry entry-tools" data-action="navigate" data-arg0="tools"><span class="entry-icon">${icon('tools')}</span><span class="entry-label">03 · TAKE IT WITH YOU</span><h3>Make the next action easier.</h3><p>Editable conversation guides, reflection tools and quiet resets.</p><span class="entry-link">Open your toolkit <b aria-hidden="true">↗</b></span></button></div></section>
 <section class="today-workbench"><div class="today-practice-panel plan-practice"><div class="section-title"><span class="eyebrow">TRY SOMETHING TODAY</span><span class="today-small-icon">${icon('practice')}</span></div><h2>${esc(activity.title)}</h2><p>${esc(activity.desc)}</p><div class="row">${btn('Explore this practice →','activity',[activity.id],'secondary')}<span class="field-hint">${activityMinutes(activity)} min · Fictional learning</span></div></div><div class="today-growth-panel"><span class="eyebrow">YOUR SPACE TO GROW</span><h2>Progress, at your pace.</h2><div class="today-growth-values"><div><strong>${reviewed}<small> / 30</small></strong><span>lessons reviewed</span></div><div><strong>${reviews}</strong><span>topics to revisit</span></div><div><strong>${state.saved.length}</strong><span>saved for later</span></div></div>${btn(reviews?'Start a short review →':'Explore My Growth →',reviews?'review':'navigate',reviews?[]:['progress'],'ghost')}<p class="field-hint">Your learning record stays in this browser.</p></div></section>
 <section class="today-picked"><div class="section-title"><div><span class="eyebrow">CONNECTED TO YOUR FOCUS</span><h2>A useful next chapter.</h2></div>${btn('All learning →','navigate',['library'],'ghost')}</div><div class="card-grid">${picked.map(lessonCard).join('')}</div></section>
 <section class="quote-panel today-quote"><span class="quote-mark" aria-hidden="true">“</span><div><span class="eyebrow">A THOUGHT TO CARRY WITH YOU</span><blockquote id="quoteText">${esc(quotes[quoteIndex])}</blockquote><div class="quote-footer"><span>Original Carecraft reflection</span><div class="quote-dots">${quotes.map((_,i)=>btn('<span aria-hidden="true"></span>','quote',[i],'dot',`aria-label="Reflection ${i+1}" aria-pressed="${i===quoteIndex}"`)).join('')}</div></div><div class="row">${btn(ui.quoteTimer?'Pause quotes':'Play quotes','quote-play',[],'ghost',studioReducedMotion()?'disabled':'')}${btn('Next quote →','quote-next',[],'ghost')}</div></div></section>
 <button type="button" class="app-guide-fab" data-action="app-guide" aria-haspopup="dialog" aria-label="How to use Carecraft. Open the interactive guide."><span class="guide-fab-icon">${icon('spark')}</span><span><small>A LITTLE GUIDANCE</small>How to use Carecraft</span><b aria-hidden="true">↗</b></button>`;
}

