function guideVisual(index){return `<div class="guide-preview" aria-hidden="true"><div class="guide-preview-brand"><img src="${HCA_CREST}" alt=""><span>Carecraft <small>YOUR LEARNING SPACE</small></span><i></i><i></i><i></i></div><div class="guide-preview-content"><span class="guide-preview-tag">${APP_GUIDE[index].label.toUpperCase()}</span><div class="guide-preview-icon">${icon(APP_GUIDE[index].icon)}</div><div class="guide-preview-lines"><i></i><i></i></div><div class="guide-preview-cards">${(index===0?['Learn','Try','Reflect']:index===1?['Learn','Check','Reflect']:index===2?['Choose','Decide','Review']:index===3?['Open','Edit','Keep']:['Notice','Return','Grow']).map((s,i)=>`<span><b>0${i+1}</b>${s}</span>`).join('')}</div><div class="guide-preview-bottom"><span></span><i>✓</i></div></div></div>`;}
