function changeAppGuide(index){if(!$('#modal').classList.contains('app-guide-modal'))return;index=Math.max(0,Math.min(4,Number(index)||0));ui.guideStep=index;const g=APP_GUIDE[index];$('#appGuidePanel').innerHTML=`<div class="app-guide-chapter">${guideVisual(index)}<div class="app-guide-copy"><span class="eyebrow">CHAPTER 0${index+1} OF 05 · ${g.label.toUpperCase()}</span><h3>${g.title}</h3><p class="guide-lead">${g.lead}</p><ol class="guide-instructions">${g.steps.map(([title,text],i)=>`<li><span>${i+1}</span><div><h4>${title}</h4><p>${text}</p></div></li>`).join('')}</ol><p class="guide-tip">${icon('spark')}<span>${g.tip}</span></p>${btn(g.cta,'guide-go',[g.route])}</div></div>`;$('#guideStatus').textContent=(index+1)+' of 5 · '+g.label;for(const [id,n]of [['guidePrev',index-1],['guideNext',index+1]]){const b=$('#'+id);b.dataset.arg0=n;b.disabled=n<0||n>4;}document.querySelectorAll('.app-guide-tabs button').forEach((b,i)=>b.setAttribute('aria-pressed',String(i===index)));}
