function ccGuideFor(key){const sim=CC_SIMS.find(s=>s.id===key),s=sim||CC_STUDIOS.find(s=>s.id===key),l=lessons.find(l=>l.id===key);if(s)return {title:s.title,what:s.description,why:s.why,when:s.when,how:s.how,who:'Individual learners, peer pairs and facilitators. Fictional learning practice.',evidence:s.evidence};if(l)return {title:l.title,what:l.description,why:l.takeaway,when:CC_USE[l.id]?.[1]||'Before practice or when reflecting on this topic.',how:l.steps.map((s,i)=>(i+1)+'. '+s[0]).join('. '),who:CC_USE[l.id]?.[0]||'Healthcare learners and practitioners.',evidence:l.evidence};const map={hygiene:'infection','sbar-studio':'sbar',movement:'wellbeing',room:'infection',cus:'speakup',huddle:'accountability',flow:'human-factors',teach:'teachback-skill',reflect:'debrief',evidence:'risk-evidence',qi:'improvement',desc:'conflict',fishbone:'human-factors',handover:'sbar',teachback:'teachback-skill','ai-case':'ai','med-case':'med-transitions',pause:'wellbeing'};if(map[key])return ccGuideFor(map[key]);const a=CC_SECTIONS[key]||CC_SECTIONS.practice;return Object.fromEntries(['title','what','why','when','how','who','evidence'].map((k,i)=>[k,a[i]]));}
