function hcaChooseBackup(){const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.addEventListener('change',async()=>{const file=input.files[0];if(!file)return;try{if(file.size>8*1024*1024)throw Error('Choose a backup smaller than 8 MB.');const backup=JSON.parse(await file.text());store.validate(backup);ui.pendingBackup=backup;showModal('Restore this learning workspace?','Current data will be replaced. You can undo immediately after restoring.',`<p>Backup from ${esc(new Date(backup.exportedAt).toLocaleString())}. Download a backup of your current workspace if you want to keep both.</p><div class="row">${btn('Back up current data','backup',[],'secondary')}${btn('Restore this backup','restore-confirm')}</div>`);}catch(e){toast(e.message||'That backup could not be read. Current data is unchanged.');}});input.click();}
