function exportProgress(print=false){captureDraft();const lines=['CARECRAFT / HEALTHCARE CROWN ACADEMY','RECORD OF LEARNING ACTIVITY, NOT A CREDENTIAL','Educational activity, not clinical certification or accredited CPD/CME.','Exported: '+new Date().toLocaleString(),'Name: '+(state.name||'Not provided'),'Role: '+state.role,'','REVIEWED LESSONS',...state.completed.map(id=>lessons.find(l=>l.id===id)?.title||id),'','REFLECTIONS',...Object.entries(state.reflections).map(([id,v])=>(lessons.find(l=>l.id===id)?.title||id)+'\n'+v),'','NOTES & HIGHLIGHTS',...state.notes.map(n=>(lessons.find(l=>l.id===n.lesson)?.title||n.lesson)+'\n'+(n.quote||'')+'\n'+(n.text||'')),'','ACTION PLANS',...state.actions.map(a=>a.text+'\nStatus: '+a.status+' | Review: '+a.due+'\n'+(a.review||'')),'','LESSON CHECKS',...state.checkRecords.map(r=>(lessons.find(l=>l.id===r.lesson)?.title||r.lesson)+' | '+r.date+' | '+(r.correct?'More helpful response':'Alternative explored')),'','PRACTICE TRAIL',...state.studioAttempts.map(a=>a.label+'\n'+a.detail),'','SCENARIOS',...state.branchRecords.map(r=>(cases.find(c=>c.id===r.case)?.title||r.case)+'\n'+r.path.map(p=>p.label+' — '+p.feedback).join('\n'))];if(print){$('#learningRecord').innerHTML=`<h1>Carecraft learning record</h1><p>Record of learning activity, not a credential.</p><pre>${esc(lines.join('\n'))}</pre>`;window.print();}else downloadFile(lines.join('\n'),'carecraft-learning-record.txt');}
function ccPortableHTML(){const code=$('#carecraft-app-code')?.textContent,styles=$('#carecraft-app-styles')?.textContent;if(!code?.includes('function renderHome')||!styles?.includes('--surface'))throw Error('Complete app source unavailable.');return '<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="carecraft-version" content="4.0.1"><title>Carecraft v4.0.1 — Healthcare Crown Academy</title><style id="carecraft-app-styles">'+styles+'</style></head><body><div id="app"></div><script id="carecraft-app-code">'+code.replace(/<\/script/gi,'<\\/script')+'</scr'+'ipt></body></html>';}
