function startCase(id){ui.activity=id;ccCurrentGuide=id;branchSession={case:id,stage:0,path:[],firstHelpful:false,selected:null};renderCase();}
function branchQuestion(){const b=branchData[branchSession.case],c=cases.find(c=>c.id===branchSession.case),stage=branchSession.stage;let raw=stage===2?HCA_FINALES[branchSession.case]:stage===0?{event:c.body,question:c.question,answers:b.choices,correct:b.correct,rationales:b.rationales}:{event:branchSession.firstHelpful?b.success:b.recovery,question:branchSession.firstHelpful?b.successQ:b.recoveryQ,answers:[b.alternatives[0],b.good,b.alternatives[1]],correct:1,rationales:['This leaves an important uncertainty or responsibility unresolved.',b.debrief,'This postpones or transfers the unresolved issue rather than establishing a clear plan.']};branchSession.orders=branchSession.orders||{};const order=branchSession.orders[stage]||(branchSession.orders[stage]=hcaShuffle(raw.answers.length));return {...raw,answers:order.map(i=>raw.answers[i]),rationales:order.map(i=>raw.rationales[i]),correct:order.indexOf(raw.correct)};}
function finishBranch(){let record=state.branchRecords.find(r=>r.id===branchSession.savedId);if(!record){record={id:'branch-'+Date.now(),case:branchSession.case,path:branchSession.path,date:new Date().toISOString()};state.branchRecords.push(record);branchSession.savedId=record.id;if(!state.cases.includes(record.case))state.cases.push(record.case);persist();}showBranchDebrief(record,branchData[branchSession.case]);}
function selectStudio(tab){studioDispose();studioTab=tab;currentPage='studio';ui.activity=tab==='sbar'?'sbar-studio':tab;render();recordRoute();}
function hcaLaunchStudio(tab){selectStudio(tab);}
function launchActivity(id){if(!HCA_ACTIVITIES.some(a=>a.id===id)){toast('Choose an available activity from Practice.');return;}captureDraft();captureActivity();exitPresent();studioDispose();advStop();clearSelection();ui.review=null;if($('#modal').open)closeModal(true);ui.tool=null;ui.activity=id;ui.activitySaved=false;ui.history=[];ui.dirty=false;ccCurrentGuide=id;const a=HCA_ACTIVITIES.find(a=>a.id===id);if(!a)return;if(id==='room')hcaOpenRoom();else if(['hygiene','sbar-studio','movement'].includes(id)){selectStudio(id==='sbar-studio'?'sbar':id);}else if(cases.some(c=>c.id===id))startCase(id);else if(CC_STUDIOS.some(s=>s.id===id))ccOpenStudio(id);else if(CC_SIMS.some(s=>s.id===id))ccOpenSimulation(id);else openAdv(id);captureActivity();}
function activityFinished(){if(!ui.activity)return false;if(ui.activitySaved)return true;if(ccStudio?.id===ui.activity)return ccStudio.saved||ccStudio.checked||ccStudio.history?.length===3;if(ccSim?.id===ui.activity)return ccSim.finished;if(branchSession?.case===ui.activity)return branchSession.stage>=3;if(ui.activity==='room')return hcaRoom.index>=6;if(ui.activity==='hygiene')return hygieneIndex>=6;if(ui.activity==='sbar-studio')return sbarChecked&&sbarAcknowledged;return false;}
function finishExtras(){if(!ui.activity||!activityFinished())return '';const a=HCA_ACTIVITIES.find(a=>a.id===ui.activity),next=HCA_ACTIVITIES[(HCA_ACTIVITIES.indexOf(a)+1)%HCA_ACTIVITIES.length];return `<section class="finish-screen"><span class="eyebrow">WHAT YOU PRACTISED</span><h3>${esc(a?.title||'A useful decision')}</h3><p>${esc(a?.desc||'Review your reasoning and choose a next action.')}</p><h4>One thing to try</h4><p>${esc(ccGuideFor(ui.activity).why)}</p><p class="footnote">Use the activity’s Save control to keep its full trail in My Growth. Records describe learning activity, not clinical competence.</p>${btn('Next activity →','activity',[next.id],'secondary')}${btn('View My Growth','navigate',['progress'],'ghost')}</section>`;}
function captureActivity(){if(!ui.activity)return;let snapshot;if(CC_STUDIOS.some(s=>s.id===ui.activity))snapshot={ccStudio};else if(CC_SIMS.some(s=>s.id===ui.activity))snapshot={ccSim};else if(cases.some(c=>c.id===ui.activity))snapshot={branchSession};else if(ui.activity==='room')snapshot={hcaRoom};else snapshot={studioTab,hygieneIndex,hygieneAnswers,hygieneSelected,hotspotSelected,sbarSlots,sbarSelected,sbarChecked,sbarGuided,sbarAcknowledged,movementId,movementSafety,movementCycles,advMode,cusStep,cusSelected,cusHistory,huddleStep,huddleHistory,simStep,simServed,simQueue,simRework,simHistory,simCapacity};state.lastSession={kind:'activity',id:ui.activity,snapshot:JSON.parse(JSON.stringify({...snapshot,activitySaved:!!ui.activitySaved})),date:new Date().toISOString()};store.save();}
function resumeTitle(){const s=state.lastSession;return s?.kind==='activity'?HCA_ACTIVITIES.find(a=>a.id===s.id)?.title||'Your practice':lessons.find(l=>l.id===s?.lesson)?.title||'Your next lesson';}
function restoreCheckpoint(saved){const x=saved.snapshot||{};ui.activity=saved.id;ui.activitySaved=!!x.activitySaved;if(x.ccStudio){ccStudio=x.ccStudio;ccRenderStudio();}else if(x.ccSim){ccSim=x.ccSim;ccSim.playing=false;ccRenderSimulation();}else if(x.branchSession){branchSession=x.branchSession;renderCase();}else if(x.hcaRoom){hcaRoom=x.hcaRoom;hcaRenderRoom();}else{({studioTab,hygieneIndex,hygieneAnswers,hygieneSelected,hotspotSelected,sbarSlots,sbarSelected,sbarChecked,sbarGuided,sbarAcknowledged,movementId,movementSafety,movementCycles,advMode,cusStep,cusSelected,cusHistory,huddleStep,huddleHistory,simStep,simServed,simQueue,simRework,simHistory,simCapacity}=x);if(['cus','huddle','flow'].includes(saved.id))({cus:renderCus,huddle:renderHuddle,flow:renderFlow})[saved.id]();else{currentPage='studio';render();recordRoute();}}captureActivity();}
function resume(){const saved=structuredClone(state.lastSession);if(!saved)return;if(saved.kind!=='activity'){openLesson(saved.lesson,saved.tab||'learn');hcaConfigureQuestion(saved.lesson,saved.question||0);render();return;}launchActivity(saved.id);ui.dirty=true;restoreCheckpoint(saved);}
function activityStepBar(){return `<nav class="activity-stepbar" aria-label="Activity steps">${btn('← Back','activity-back',[],'secondary',ui.history?.length&&!activityFinished()?'':'disabled')}${btn('Next →','activity-next',[],'primary')}</nav>`;}
function activityBack(){if(!ui.history?.length||activityFinished())return;const previous=ui.history.pop();restoreCheckpoint(previous);ui.dirty=true;}

function exitPresent(){ui.present=false;ui.ticking=false;clearInterval(ui.timer);ui.timer=null;document.body.classList.remove('present-mode','hide-feedback');$('#presentControls')?.remove();if(document.fullscreenElement)document.exitFullscreen?.().catch(()=>{});}
