function applyPresent(){document.body.classList.add('present-mode');const host=$('#modal').open?$('#modalBody'):$('#main');$('#presentControls')?.remove();host.insertAdjacentHTML('afterbegin',`<div class="present-controls" id="presentControls"><strong>Facilitator mode</strong><span id="presentTimer">${Math.floor(ui.seconds/60)}:${String(ui.seconds%60).padStart(2,'0')}</span>${btn(ui.ticking?'Pause timer':'Start timer','present-timer',[],'secondary')}${btn('Reveal / hide feedback','present-reveal',[],'secondary')}${btn('← Back','present-back',[],'secondary')}${btn('Next →','present-next',[],'secondary')}${btn('Exit','present',[],'secondary')}</div>`);}

function logStudio(id,label,detail){if(ui.activitySaved&&ui.lastSavedAttempt?.id===id&&ui.lastSavedAttempt?.detail===detail){toast('This attempt is already saved in My Growth.');return;}ui.lastSavedAttempt={id,detail};const record={id:'attempt-'+Date.now()+'-'+Math.random().toString(36).slice(2,7),activity:id,label,detail,date:new Date().toISOString()};state.studioAttempts.push(record);state.studioAttempts=state.studioAttempts.slice(-250);state.studioRecords=[...studioRecords().filter(r=>r.id!==id),{id,label,detail,date:record.date}];if(ui.activity)ui.activitySaved=true;persist();toast('Practice attempt saved. Earlier attempts are kept in My Growth.');updateStudioLog();}
function saveFlowLearning(){if(simStep===0){toast('Run at least one step before recording an explored simulation.');return;}logStudio('adv-flow','PDSA flow simulation',`Explored a fictional model: capacity ${simCapacity}; ${simStep} steps; ${simServed} completed; ${simQueue} waiting. Synthetic model, not a real-world outcome.`);renderFlow();}

