function noteEditor(id){const n=state.notes.find(n=>n.id===id),lesson=n?.lesson||activeLesson?.id||ui.noteLesson;if(!id&&!ui.selectedQuote)ui.noteLesson=lesson;if(!lesson){toast('Open a lesson before adding a note.');return;}ui.noteEdit=id||null;ui.noteLesson=lesson;showModal(n?'Edit your note.':'Keep one useful thought.','Private notes stay on this device.',`${ui.selectedQuote||n?.quote?`<blockquote class="selected-quote">${esc(n?.quote||ui.selectedQuote)}</blockquote>`:''}<label>Your note<textarea id="noteText" maxlength="3000" placeholder="What will you keep or try?">${esc(n?.text||'')}</textarea></label>${btn('Save note','save-note')}`);}
function saveNote(highlight=false){const lesson=ui.noteLesson||activeLesson?.id;if(!lesson)return;const old=state.notes.find(n=>n.id===ui.noteEdit),note={id:old?.id||'note-'+Date.now()+'-'+Math.random().toString(36).slice(2,7),lesson,quote:old?.quote||ui.selectedQuote||'',text:highlight?'':$('#noteText')?.value.trim()||'',highlight:true,created:old?.created||new Date().toISOString()};if(old)Object.assign(old,note);else state.notes.push(note);persist();if($('#modal').open)closeModal(true);ui.selectedQuote='';ui.noteEdit=null;$('#selectionTools').hidden=true;render();toast(highlight?'Highlighted for later.':'A useful thought, kept.');}
function selectionChanged(){if(currentPage!=='lesson'||lessonTab!=='learn')return;const selection=window.getSelection(),text=selection?.toString().trim();if(text&&text.length>3&&text.length<2000&&selection.anchorNode?.parentElement?.closest('#lessonPanel')){ui.selectedQuote=text;ui.noteLesson=activeLesson.id;const toolbar=$('#selectionTools');toolbar.hidden=false;}else if(!text)$('#selectionTools').hidden=true;}
function deleteNote(id){const index=state.notes.findIndex(n=>n.id===id);if(index<0)return;const n=state.notes.splice(index,1)[0];persist();render();toast('Note removed.',()=>{state.notes.splice(index,0,n);persist();render();});}
function deleteReflection(id){const text=state.reflections[id];delete state.reflections[id];persist();render();toast('Reflection removed.',()=>{state.reflections[id]=text;persist();render();});}
function stopSpeech(){window.speechSynthesis?.cancel();}
function speak(){if(!window.speechSynthesis||!activeLesson)return;stopSpeech();const voices=speechSynthesis.getVoices().filter(v=>v.localService&&/^en\b/i.test(v.lang));if(!voices.length){const s=$('#speechStatus');if(s)s.textContent='An offline English voice is not available on this device.';return;}const text=$('#lessonPanel').cloneNode(true);text.querySelectorAll('button,.read-aloud,input,select,textarea').forEach(e=>e.remove());const utterance=new SpeechSynthesisUtterance(text.textContent);utterance.voice=voices.find(v=>/^en-GB/i.test(v.lang))||voices[0];utterance.rate=ui.readSpeed;utterance.onend=()=>{const s=$('#speechStatus');if(s)s.textContent='Reading finished.';};speechSynthesis.speak(utterance);$('#speechStatus').textContent='Reading with an on-device voice.';}
function normalized(t){return String(t).toLocaleLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9 ]/g,' ');}
function editDistance(a,b){if(Math.abs(a.length-b.length)>2)return 3;let row=Array.from({length:b.length+1},(_,i)=>i);for(let i=1;i<=a.length;i++){const next=[i];for(let j=1;j<=b.length;j++)next[j]=Math.min(next[j-1]+1,row[j]+1,row[j-1]+(a[i-1]!==b[j-1]));row=next;}return row[b.length];}
function searchRank(text,q){const words=normalized(text).split(/\s+/),terms=normalized(q).trim().split(/\s+/);if(!q.trim())return 0;let score=0;for(const term of terms){if(normalized(text).includes(term))score+=10;else if(term.length>3&&words.some(w=>editDistance(w,term)<=1))score+=4;else return -1;}return score;}
function searchItems(q){const all=[...lessons.map(l=>({group:'Learn',title:l.title,detail:l.tag+' · '+l.time+' min',text:l.title+' '+l.tag+' '+l.description,action:'lesson',id:l.id})),...HCA_ACTIVITIES.map(a=>({group:'Practice',title:a.title,detail:a.meta,text:a.title+' '+a.desc,action:'activity',id:a.id})),...TOOLS.map(t=>({group:'Toolkit',title:t[1],detail:t[3],text:t[1]+' '+t[3],action:'tool',id:t[0]})),...glossary.map(g=>({group:'Key terms',title:g[0],detail:g[1],text:g.join(' '),action:'term',id:g[0]})),...state.notes.map(n=>({group:'Your notes',title:lessons.find(l=>l.id===n.lesson)?.title||'Your note',detail:n.text||n.quote,text:(n.quote||'')+' '+n.text,action:'lesson',id:n.lesson})),...Object.entries(state.reflections).filter(([,v])=>v.trim()).map(([id,text])=>({group:'Your notes',title:'Reflection: '+(lessons.find(l=>l.id===id)?.tag||'General'),detail:text,text,action:'lesson',id:lessons.some(l=>l.id===id)?id:'communication'})),...[
 ['Start a one-minute reset','Optional quiet pause','tool','pause'],['Export my learning record','Download a private text record','export',''],['Switch appearance','System, Light or Dark','appearance',''],['Go to My Growth','Review your learning activity','navigate','progress'],['Open Toolkit','Practical prompts and editable templates','navigate','tools'],['Your saved lessons','Return to a useful topic','navigate','saved']].map(([title,detail,action,id])=>({group:'Actions',title,detail,text:title+' '+detail,action,id}))];if(!q.trim())return all.filter(x=>x.group==='Actions').map(x=>({...x,rank:0}));return all.map(x=>({...x,rank:searchRank(x.text,q)})).filter(x=>x.rank>=0).sort((a,b)=>b.rank-a.rank).slice(0,q.trim()?50:12);}
function searchResults(q){const groups=['Learn','Practice','Toolkit','Key terms','Your notes','Actions'],raw=searchItems(q),items=groups.flatMap(g=>raw.filter(x=>x.group===g));ui.searchResults=items;if(!q.trim())return `<p class="muted">Search a topic, a tool, or a thought you kept.</p>${state.recentSearches.length?`<div class="recent"><h3>Recent searches</h3>${state.recentSearches.map(s=>btn(esc(s),'recent-search',[s],'secondary')).join('')}</div>`:''}<section><h3>Useful actions</h3>${items.filter(x=>x.group==='Actions').map(x=>searchResult(x,items.indexOf(x))).join('')}</section>`;if(!items.length)return '<div class="empty"><h3>No matches yet.</h3><p>Try a shorter word or another topic. Your notes are searched only on this device.</p></div>';return ['Learn','Practice','Toolkit','Key terms','Your notes','Actions'].map(group=>{const rows=items.filter(x=>x.group===group);return rows.length?`<section class="search-group"><h3>${group} <small>${rows.length}</small></h3>${rows.map(x=>searchResult(x,items.indexOf(x))).join('')}</section>`:'';}).join('');}
function searchResult(x,index){return `<button class="search-result ${index===ui.searchIndex?'active':''}" data-action="search-result" data-arg0="${index}" id="result-${index}" aria-selected="${index===ui.searchIndex}"><strong>${esc(x.title)}</strong><span>${esc(x.detail)}</span>${icon('arrow')}</button>`;}
