function openPalette(){if($('#modal').open&&$('#modal').classList.contains('command-palette')){$('#paletteSearch')?.focus();return;}clearTimeout(searchTimer);captureDraft();captureActivity();const d=$('#modal');ui.paletteReturn=d.open?{nodes:Array.from(d.childNodes),classes:d.className,activity:ui.activity,tool:ui.tool,focus:document.activeElement}:null;ui.paletteInlineActivity=!d.open?ui.activity:null;ui.activity=null;ui.tool=null;ui.searchIndex=0;ui.query='';showModal('Find your next useful step.','Search stays on this device. ↑ ↓ to move · Enter to open · Esc to close',`<label class="search-field">${icon('search')}<input id="paletteSearch" data-field="palette-search" type="search" placeholder="Search lessons, activities, tools and notes…" autocomplete="off" aria-controls="paletteResults" aria-autocomplete="list"></label><div id="paletteResults">${searchResults('')}</div>`);$('#modal').classList.add('command-palette');requestAnimationFrame(()=>$('#paletteSearch')?.focus());}
function chooseSearch(index){clearTimeout(searchTimer);searchResults(ui.query);const result=ui.searchResults?.[index];if(!result)return;if(ui.query.trim()){state.recentSearches=[ui.query.trim(),...state.recentSearches.filter(x=>x!==ui.query.trim())].slice(0,8);persist();}if($('#modal').open)closeModal(true);if(result.action==='term'){const g=glossary.find(g=>g[0]===result.id);showModal(g[0],'Key term',`<p>${esc(g[1])}</p>`);}else actions[result.action]?.([result.id]);}
function openShortcuts(){showModal('A few useful shortcuts.','Available when you are not typing in a field.',`<dl class="shortcut-list">${[['/ or Ctrl / ⌘ K','Open search'],['g h / g l / g p / g t / g g','Home / Learn / Practice / Toolkit / My Growth'],['j / k','Move through visible cards'],['s','Save the current lesson or focused card'],['← / →','Move between lesson steps or presenter decisions'],['?','Show these shortcuts'],['Escape','Close a dialog or navigation']].map(([key,meaning])=>`<dt><kbd>${key}</kbd></dt><dd>${meaning}</dd>`).join('')}</dl>`);}

