 {label:'Understand',title:l.title,lead:l.description,blocks:l.steps.map(([title,text],i)=>({title:(i+1)+'. '+title,text})),footer:l.takeaway},
 {label:'Apply',title:'From idea to action',lead:'A fictional learning example · '+l.tag,blocks:[{title:'The situation',text:ex.situation},{title:'A stronger response',text:ex.good},{title:'Why it helps',text:ex.why.join(' ')}],footer:ex.action},
 {label:'Remember',title:'Carry it into practice',lead:l.takeaway,blocks:[{title:'Who this helps',text:context[0]},{title:'When to use it',text:context[1]},{title:'One action',text:ex.action},{title:'Pause and reflect',text:l.reflect}],footer:'Rehearse within your role and local policy. Return to the lesson to check your understanding.'}
