function openInfographics(id){const l=lessons.find(l=>l.id===id);if(!l)return;ui.infographic={id,index:0,zoom:1};showModal('Visual learning guide',esc(l.title),`<div class="infographic-shell"><div class="infographic-controls"><nav class="infographic-thumbs" aria-label="Choose infographic page">${infographicPages(l).map((p,i)=>`<button data-action="info-page" data-arg0="${i}" aria-label="Page ${i+1}: ${p.label}"><img src="${infoURI(l,i)}" alt="" loading="lazy"><span>${i+1}. ${p.label}</span></button>`).join('')}</nav><div class="infographic-top"><span class="eyebrow">3 PNG INFOGRAPHICS · ${esc(l.cat.toUpperCase())}</span><div class="row">${btn('Zoom 100%','info-zoom',[],'secondary','id="infoZoom" aria-label="Change image zoom"')}${btn('Save image ↓','info-save',[],'secondary')}</div></div></div><div class="infographic-stage" id="infoStage" tabindex="0" aria-label="Infographic image. Use left and right arrow keys to change pages."><img id="infoImage" draggable="false" alt=""></div><div class="infographic-nav"><button class="secondary" data-action="info-page" id="infoPrev" aria-label="Previous infographic">← Previous</button><span id="infoStatus" role="status" aria-live="polite"></span><button class="secondary" data-action="info-page" id="infoNext" aria-label="Next infographic">Next →</button></div><details class="infographic-transcript"><summary>Read the accessible text</summary><div id="infoTranscript"></div></details><p class="field-hint">Swipe on the image or use ← →. These guides summarise the lesson; evidence and sources remain available in the lesson.</p></div>`);$('#modal').classList.add('infographic-modal');flipInfographic(0);let start=null;const stage=$('#infoStage');stage.addEventListener('pointerdown',e=>{if(e.pointerType==='touch'&&ui.infographic.zoom===1)start={x:e.clientX,y:e.clientY};});stage.addEventListener('pointerup',e=>{if(!start)return;const dx=e.clientX-start.x,dy=e.clientY-start.y;start=null;if(Math.abs(dx)>60&&Math.abs(dx)>Math.abs(dy)*1.5)flipInfographic(ui.infographic.index+(dx<0?1:-1));});stage.addEventListener('pointercancel',()=>start=null);}
function flipInfographic(index){if(!$('#modal').classList.contains('infographic-modal'))return;const s=ui.infographic,l=lessons.find(l=>l.id===s.id);s.index=Math.max(0,Math.min(2,index));const p=infographicPages(l)[s.index],img=$('#infoImage');img.src=infoURI(l,s.index);img.alt=l.title+' — '+p.label+'. Full text is available below.';img.classList.remove('is-turning');void img.offsetWidth;img.classList.add('is-turning');$('#infoStage').scrollTop=0;$('#infoStage').scrollLeft=0;$('#infoStatus').textContent=(s.index+1)+' / 3 · '+p.label;for(const [id,n]of [['infoPrev',s.index-1],['infoNext',s.index+1]]){const b=$('#'+id);b.dataset.arg0=n;b.disabled=n<0||n>2;}document.querySelectorAll('.infographic-thumbs button').forEach((b,i)=>b.setAttribute('aria-current',i===s.index?'page':'false'));$('#infoTranscript').innerHTML=`<h3>${esc(p.title)}</h3><p>${esc(p.lead)}</p>${p.blocks.map(b=>`<h4>${esc(b.title)}</h4><p>${esc(b.text)}</p>`).join('')}<p><strong>${esc(p.footer)}</strong></p>`;}
