function infographicKey(event){if(!$('#modal')?.open||!$('#modal').classList.contains('infographic-modal')||event.target.matches('input,textarea,select'))return false;if(!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return false;event.preventDefault();flipInfographic(event.key==='Home'?0:event.key==='End'?2:ui.infographic.index+(event.key==='ArrowRight'?1:-1));return true;}

/* Learning Studio for Carecraft: each lesson becomes a slide journey (hca-studio.js) with an annotation toolkit.
   It reads the same lesson, worked-example, question-bank and infographic data as the lesson page and writes answers,
   reflections and actions back through the same stores, so Smart Review and My Growth stay in step. */
const CC_STUDIO_APP='carecraft',CC_STUDIO_SLIDES=14;
function ccStudioReady(){return typeof HCAStudio!=='undefined'&&typeof CC_REGIONS!=='undefined';}
function ccStudioGated(id){try{const H=window.HCA||{};if(H.locked&&H.locked('carecraft')&&window.CC_FREE&&!CC_FREE.lessons.includes(id)){setTimeout(()=>H.paywall('carecraft','this lesson'));return true;}}catch{}return false;}
function ccSentences(text){return (String(text).match(/[^.!?]+[.!?]+["”’)]*\s*|[^.!?]+$/g)||[String(text)]).map(s=>s.trim()).filter(Boolean);}
/* One idea per slide: the line worth quoting becomes the pull card, the rest is the explanation. */
function ccIdeaSlide(l,i){
 const [title,text]=l.steps[i],sent=ccSentences(text);let pull='',rest=sent;
 if(sent.length>1){const q=sent.findIndex(s=>/[“"]/.test(s)),k=q>=0?q:sent.length-1;pull=sent[k];rest=sent.filter((_,n)=>n!==k);}
 return {id:'idea'+(i+1),type:'idea',eyebrow:`Idea ${i+1} of ${l.steps.length}`,n:i+1,rail:l.steps.map(x=>x[0]),title,body:rest[0]||text,more:rest.slice(1).join(' '),pull,
  cards:i===l.steps.length-1&&P2_DATA.examples[l.id]?[{icon:'target',label:'One action to practise',text:P2_DATA.examples[l.id].action}]:[]};
}
function ccVisualSlide(l,n){
 const p=infographicPages(l)[n-1],R=CC_REGIONS[l.id]&&CC_REGIONS[l.id][String(n)];
 const intro=[l.description,'A fictional example from '+l.tag.toLowerCase()+'. Notice what changes between a weaker and a stronger response.',l.takeaway][n-1];
  const regions=R?[{label:'The whole guide',text:'Every page is one guide. Use the steps to move through it, or enlarge it to read it at full size.',rect:[0,0,1,1]},{label:['The big picture','A fictional example','Carry it forward'][n-1],text:intro,rect:R?[0,Math.max(0,R.hero[1]-.008),1,R.hero[3]+.016]:[0,0,1,1]},...R.blocks.map((b,i)=>({label:(p.blocks[i]||{}).title||'Section '+(i+1),text:(p.blocks[i]||{}).text||'',rect:b})),{label:'In short',text:p.footer,rect:R.footer}]:[{label:p.title,text:intro,rect:[0,0,1,1]}];
 return {id:'vis'+n,type:'visual',nav:`${p.label}: ${n===1?'the whole picture':p.title}`,eyebrow:`Visual guide ${n} of 3 · ${p.label}`,title:p.title,img:infoURI(l,n-1),alt:`${l.title}: ${p.label}. The full text of this poster is available below the tour.`,aspect:R?R.size[0]/R.size[1]:.55,regions,
  blocks:[{title:p.title,text:p.lead},...p.blocks,{title:'In short',text:p.footer}],download:`carecraft-${l.id}-${n}`};
}
function ccCheckSlide(l,k){
 const q=HCA_BANK[l.id][k],map=hcaAnswerMaps[q.id]||(hcaAnswerMaps[q.id]=hcaShuffle(q.answers.length));
 return {id:'chk'+(k+1),type:'check',eyebrow:`Check ${k+1} of 3`,question:q.question,hint:k===0?'Pick the response you would most want to give. There is no penalty, and every option teaches something.':'',options:map.map(i=>q.answers[i]),correct:map.indexOf(q.correct),rationales:map.map(i=>q.rationales[i]),takeaway:q.rationales[q.correct],qid:q.id,map};
}
function ccNextLesson(id){const i=lessons.findIndex(l=>l.id===id);return lessons[(i+1)%lessons.length];}
function ccStudioDeck(id){
 const l=lessons.find(x=>x.id===id);if(!l||!ccStudioReady()||!HCA_BANK[id])return null;
 const ex=P2_DATA.examples[id],notes=LESSON_NOTES[id]||[],cat=l.cat[0].toUpperCase()+l.cat.slice(1),nxt=ccNextLesson(id),plan=state.actions.find(a=>a.lesson===id&&a.status==='planned');
 const slides=[
  {id:'cover',type:'cover',kicker:`${cat} · ${l.tag}`,title:l.title,subtitle:l.description,meta:[{icon:'clock',text:l.time+' min'},{icon:'layers',text:CC_STUDIO_SLIDES+' slides'},{icon:'target',text:'3 checks'},{icon:'image',text:'3 visual guides'}],
   outcomes:[l.outcome||'Explain '+l.tag.toLowerCase()+' using a clear principle and a worked example.','Recognise a less helpful response and explain a stronger alternative.','Choose one action to rehearse within your role and local policy.'],art:{src:infoURI(l,0),alt:`Preview of the ${l.title} visual guide`}},
  ccIdeaSlide(l,0),ccIdeaSlide(l,1),ccIdeaSlide(l,2),
  ccVisualSlide(l,1),ccCheckSlide(l,0),
  {id:'notes',type:'notes',eyebrow:'Deeper reading',title:'What to notice and carry forward',lead:'Two short notes to read slowly, with a pen if you like.',items:notes.map((t,i)=>({label:i===0?'Notice':'Use it',text:t})),chips:(CC_USE[id]||[]).map((t,i)=>({label:i===0?'Who it helps':'Use it when',text:t}))},
  {id:'cmp',type:'compare',eyebrow:'Fictional worked example',title:'Notice the difference.',situation:ex.situation,left:{label:'Needs improvement',text:ex.poor},right:{label:'Stronger approach',text:ex.good},why:ex.why},
  ccVisualSlide(l,2),ccCheckSlide(l,1),ccVisualSlide(l,3),ccCheckSlide(l,2),
  {id:'reflect',type:'reflect',eyebrow:'Make it yours',prompt:l.reflect,hint:'One honest sentence is enough. It stays on this device.',action:ex.action,saveLabel:'Save reflection and action',
   initial:{text:state.reflections[id]||'',action:plan?plan.text:ex.action,dueDays:3}},
  {id:'recap',type:'recap',takeaway:l.takeaway,points:l.steps.map(s=>s[0]),finishLabel:'Mark lesson as reviewed',full:'Open the full lesson page',onFull:()=>openLesson(id),next:{label:'Next: '+nxt.title,open:()=>openStudio(nxt.id,{start:0})}}
 ];
 return {app:CC_STUDIO_APP,id,title:l.title,kicker:`Learning Studio · ${cat} · ${l.tag}`,accent:'#0F8A86',accentDark:'#0A7C78',accentLight:'#6FD0C5',secPerSlide:Math.max(25,Math.round(l.time*60/CC_STUDIO_SLIDES)),slides,
  canFinish:s=>state.checkRecords.some(r=>r.lesson===id)||s.answered?null:'Answer at least one check to record this lesson as reviewed.',
  onCheck:(slide,choice,correct)=>{
   state.checkRecords.push({lesson:id,questionId:slide.qid,answerId:slide.qid+'-answer-'+slide.map[choice],choice,correct,date:new Date().toISOString()});
   const old=state.reviewQueue[id],streak=correct?Math.min(5,(old?.streak||0)+1):0;state.reviewQueue[id]={due:laterDay(correct?[1,3,7,14,30][Math.max(0,streak-1)]:1),streak};persist();
  },
  onReflect:(slide,rf)=>{
   state.reflections[id]=rf.text||'';const text=(rf.action||'').trim();
   if(text){const due=laterDay(rf.dueDays||3),ex2=state.actions.find(a=>a.lesson===id&&a.status==='planned');if(ex2){ex2.text=text;ex2.due=due;}else state.actions.push({id:'action-'+Date.now()+'-'+Math.random().toString(36).slice(2,7),lesson:id,text,due,status:'planned',created:new Date().toISOString(),review:''});delete state.toolDrafts['action-'+id];}
   persist();
  },
  onComplete:()=>{
   if(!state.completed.includes(id))state.completed.push(id);persist();
   if(currentPage==='lesson'&&activeLesson&&activeLesson.id===id)ui.completion=id;
   return 'Lesson reviewed. One useful step, done.';
  },
  onClose:()=>{try{if(['library','saved','dashboard','lesson'].includes(currentPage))render();const b=document.querySelector(`[data-action=studio][data-arg0="${id}"]`);b&&b.focus({preventScroll:true});}catch{}}};
}
function openStudio(id,opts){
 if(ccStudioGated(id))return;const deck=ccStudioDeck(id);if(!deck){toast('The studio is unavailable for this lesson. Open the lesson page instead.');return;}
 try{captureDraft();stopSpeech();if($('#modal')?.open)closeModal(true);toggleMenu(false);}catch{}
 return HCAStudio.open(deck,opts||{});
}
function studioProgress(id){try{return ccStudioReady()?HCAStudio.progress(CC_STUDIO_APP,id):{started:false,last:0,done:false,total:0,visited:0,pct:0};}catch{return{started:false,last:0,done:false,total:0,visited:0,pct:0};}}
/* "Slides" control on a lesson card: label and meter say where you are */
function studioCardButton(l){
 const p=studioProgress(l.id),label=p.done?'Replay as slides':p.started&&p.last>0?`Resume slides · ${Math.min(p.last+1,CC_STUDIO_SLIDES)}/${CC_STUDIO_SLIDES}`:'Learn as slides';
 return `<button type="button" class="cs-card-btn${p.done?' is-done':''}" data-action="studio" data-arg0="${l.id}" data-arg1="${p.started&&!p.done?p.last:0}" aria-label="${esc(label)}: ${esc(l.title)}"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${p.done?'M5 12.5l4.5 4.5L19 7':'M7 4l13 8-13 8z'}"/></svg><span>${esc(label)}</span><i class="cs-meter" aria-hidden="true"><b style="width:${p.done?100:p.pct}%"></b></i></button>`;
}
/* Learn page intro: invites the learner into the studio and resumes where they left off */
function studioIntroActions(){
 if(!ccStudioReady())return '';
 const rows=lessons.map(l=>({l,p:studioProgress(l.id)})),live=rows.filter(r=>r.p.started&&!r.p.done&&r.p.last>0).sort((a,b)=>b.p.at-a.p.at)[0],fresh=rows.find(r=>!r.p.started&&!state.completed.includes(r.l.id))||rows.find(r=>!r.p.done)||rows[0];
 const main=live?{l:live.l,start:live.p.last,label:`Resume · ${live.l.title}`,sub:`Slide ${Math.min(live.p.last+1,CC_STUDIO_SLIDES)} of ${CC_STUDIO_SLIDES}`}:{l:fresh.l,start:0,label:`Start with ${fresh.l.title}`,sub:`${fresh.l.time} min · ${CC_STUDIO_SLIDES} slides`};
 return `<div class="cs-intro-cta"><button type="button" class="cs-cta" data-action="studio" data-arg0="${main.l.id}" data-arg1="${main.start}"><svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="M7 4l13 8-13 8z"/></svg><span><b>${esc(main.label)}</b><small>${esc(main.sub)}</small></span></button><ul class="cs-tools" aria-label="Studio tools"><li>Pen</li><li>Highlighter</li><li>Marker</li><li>Shapes</li><li>Text</li><li>Laser</li><li>Undo</li><li>Clear all</li></ul></div>`;
}
function studioIntroStats(){const done=lessons.filter(l=>studioProgress(l.id).done).length;return `<strong>30 <small>slide journeys</small></strong><strong>90 <small>visual pages to tour</small></strong><strong>${done} <small>journeys completed</small></strong>`;}
/* Lesson page: a launch card above the reading */
function studioLessonCard(l){
 const p=studioProgress(l.id),verb=p.done?'Replay as slides':p.started&&p.last>0?'Resume the slides':'Learn it as slides';
 return `<section class="cs-launch" aria-label="Learning Studio"><div class="cs-launch-copy"><span class="eyebrow">LEARNING STUDIO</span><h3>${esc(p.done?'Revisit this lesson as a slide journey.':'Prefer a guided slideshow?')}</h3><p>${CC_STUDIO_SLIDES} slides: three ideas, a spotlight tour of the infographics, a worked example and three checks. Annotate with a pen, highlighter or shapes. ${p.started&&!p.done?`You are on slide ${Math.min(p.last+1,CC_STUDIO_SLIDES)}.`:''}</p></div><button type="button" class="cs-cta" data-action="studio" data-arg0="${l.id}" data-arg1="${p.started&&!p.done?p.last:0}"><svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="M7 4l13 8-13 8z"/></svg><span><b>${verb}</b><small>${l.time} min · ${CC_STUDIO_SLIDES} slides</small></span></button></section>`;
}

/* Carecraft Learn: depth content for all 30 lessons (original educational synthesis, fictional scenarios, non-prescriptive).
   Keys per lesson: lv level · why [paragraphs] · fw {n name, i intro, p [[tag,name,text]]} framework tiles · viz {k kind, t title, c caption, s steps} diagram
   · terms [[term, definition]] flip cards · sc branching scenario {s setup, a/b decision points with options [text, tone 0-2, feedback], end [weak, mixed, strong]}
   · spot {t intro, l [[line, isProblem, why]]} · myths [[myth, reality]] · lad {t, h, s [[label, example, note]]} slider · chk quick-reference checklist
   · good "what good looks like" · rel related lesson ids · pr reflective prompts. Frameworks are named only where they are standard, widely taught tools;
   the in-app evidence panel remains the only place numbers from studies appear. */
const LX_LEVELS={Foundation:'Everyday practice. No prior framework needed; applies in almost any conversation or task.',Core:'Structured tools used in teams and handovers. Builds on the foundation lessons.',Advanced:'Judgement under uncertainty, evidence or systems thinking. Best after a few Core lessons.'};
const LX_DATA={
communication:{lv:'Foundation',
 why:['Most care depends on conversations that end with a person knowing what will happen next and what to do if things change. Nodding, saying “yes” or staying silent are weak signals of understanding, particularly when someone is anxious, tired, unwell or hearing a new vocabulary.','A structure helps because the first thirty seconds set the tone and the last thirty decide whether the plan survives contact with real life. The three ideas in this lesson, opening with the person, sharing responsibility for understanding and closing the loop, work in a bedside chat, a phone call or a team huddle.'],
 fw:{n:'Open, explain, check, close',i:'A simple frame for any explanation. Select a part to see what it sounds like.',p:[['1','Open','Introduce yourself and your role, say the purpose of the conversation and ask what matters most to the person today. “I’d like to go through what happens next. Is there anything you most want to ask first?”'],['2','Explain in chunks','Give one or two ideas, then pause. Use everyday words and put the most important action first. Avoid stacking a list of instructions in one breath.'],['3','Check','Ask the person to say the plan in their own words, framed as a check on you: “I’ve said a lot, so I’d like to check I explained it clearly.” Listen for what is missing, not for what is wrong with them.'],['4','Close the loop','Agree the next step, who owns it and when it happens. Say what to watch for and who to contact if things change, using local safety-net advice. Offer an interpreter or accessible format if needed.']]},
 viz:{k:'flow',t:'A conversation that closes the loop',c:'The check sits in the middle of the conversation, not at the end, so there is still time to repair a gap.',s:[['Open','Name your role and the purpose. Ask what matters most.'],['Explain','One or two ideas in plain language. Pause.'],['Check','“How would you describe the plan?” Listen for gaps.'],['Repair','Re-explain differently. Check again.'],['Close','Next step, owner, timing, who to contact.']]},
 terms:[['Teach-back','Asking a person to explain the plan in their own words so that the practitioner can check how clearly it was explained. It is a check on the explanation, not a test of the person.'],['Chunk and check','Giving a small amount of information, then checking understanding before offering the next piece.'],['Safety-net advice','Telling a person what to look out for, what to do and who to contact if things change or do not go as expected, following local guidance.'],['Open question','A question that cannot be answered with yes or no and invites the person to describe their own view, such as “What worries you most about going home?”']],
 sc:{s:'A fictional patient, Mr Alvarez, is being discharged after a short stay. He will get a follow-up phone call from the clinic and needs to book a routine test. You have a few minutes. He nods throughout, then says: “So I just wait for a letter, then?”',
  a:{q:'What do you do next?',o:[['Say “Yes, everything is in the leaflet,” and hand it over.',0,'The leaflet may help later, but his question shows the plan has not landed. A confident answer without a check leaves the gap in place.'],['Say “I’ve given you a lot to take in. To check I explained it clearly, how would you describe what happens next?”',2,'This makes clarity your responsibility, invites his own words and shows you exactly which part to repair.'],['Repeat the whole explanation again, more slowly.',1,'Slower repetition is kind but may repeat the same wording that did not work, and it does not reveal what he understood.']]},
  b:{q:'What is your next move?',up:'He says: “The clinic rings me, then I book a blood test.” That is close, but he has not mentioned what to do if he feels worse before the call.',dn:'He looks unsure. The transport has arrived and you have about two minutes left.',o:[['Explain the missing part in different words, ask him to say it back once more, then agree who to contact if things change.',2,'You repaired the specific gap, rechecked and finished with a safety net and a named contact.'],['Add the missing information, circle the phone number on the leaflet and say goodbye.',1,'Better than nothing, but without a second check you cannot know whether the new information was understood.'],['Ask “Does that make sense?” and, if he says yes, finish.',0,'A yes/no question invites a polite yes. It cannot reveal confusion.']]},
  end:['The conversation ended with the same uncertainty it began with. The intent was good, but the plan relied on the leaflet and a polite nod.','A reasonable outcome. Next time, build the check into the middle of the conversation and keep the repair specific.','A strong outcome: a check framed on you, a targeted repair, a second check and a safety net with a named contact.']},
 spot:{t:'Read this fictional end-of-conversation script. Mark each line you think weakens understanding, then check your answers.',l:[['“Hello, I’m Sam, one of the nurses. I’d like to go through what happens after you leave.”',0,'A clear role and purpose. This is a good opening.'],['“So you understand everything now, don’t you?”',1,'A closed, leading question. It invites “yes” whether or not the person understands.'],['“The clinic will call within a few days, and then you can book the blood test.”',0,'One action in plain language with a sequence the person can follow.'],['“It’s all in the leaflet, so you can read it at home if you’re unsure.”',1,'Hands the responsibility for understanding to the person, at the moment they are most likely to leave without asking.'],['“I’ve covered a lot. How would you explain the plan to your daughter?”',0,'A teach-back framed around explaining to someone else. Open, non-judgmental and revealing.']]},
 myths:[['If the person nods, they have understood.','Nodding often signals politeness, deference or wanting the conversation to end. Check understanding with an open request.'],['Teach-back tests whether the patient was listening.','It tests how clearly you explained. Framing it that way protects dignity and gets more honest answers.'],['A leaflet is enough if time is short.','Written information supports a conversation but cannot reveal confusion at the moment it matters.'],['More detail means a better explanation.','Too much at once is a common cause of lost information. One to three key actions, repeated and checked, usually work better.']],
 lad:{t:'How well does a check reveal understanding?',h:'Move the slider from a weak check to a strong one.',s:[['Assume','“Right, you’re all set.”','No check at all. Any confusion stays hidden.'],['Yes/no','“Do you understand?”','Invites a polite yes. Very little information.'],['Repeat','“Any questions?”','Puts the work on the person to find the gap and speak up.'],['Teach-back','“To check I explained it clearly, how would you describe the next step?”','Open, framed on your explanation, shows exactly where to repair.'],['Teach-back and plan','Teach-back, repair, second check, agreed owner, timing and safety net.','The full loop: understanding is confirmed and the next step is owned.']]},
 chk:['I said who I am and the purpose of the conversation.','I asked what matters most to the person before explaining my agenda.','I limited the explanation to one to three key actions.','I used plain words and explained any term I could not avoid.','I asked for the plan in the person’s own words, framed as a check on me.','I repaired the gap in a different way and checked again.','We agreed the next step, who owns it and when.','I offered safety-net advice and an interpreter or accessible format where needed.'],
 good:['The person can say, in their own words, what happens next and who to contact.','You can tell which part of your explanation needed repair, and you changed it.','The next step has a named owner and a time.'],
 rel:['teachback-skill','health-literacy','empathy'],pr:['Which phrase do you rely on that a person outside healthcare might not understand?','Think of a conversation that ended with a nod. What could you have asked instead?','What is one safety-net sentence you could add to a routine conversation?']},

safety:{lv:'Foundation',
 why:['Many safety problems are not dramatic errors but small mismatches that pass unnoticed: the right action for the wrong person, a medicine list that is out of date, an unclear order that someone assumes they understand. Safe practice depends on habits that catch mismatches before they reach the person.','Two habits do most of the work: a deliberate pause before acting, and treating uncertainty as information to resolve rather than something to push through. Transitions between teams, wards and settings are where information is most likely to be lost, so they deserve extra care.'],
 fw:{n:'Pause, reconcile, clarify, report',i:'Four safety habits for everyday work. Select a habit.',p:[['P','Pause','Before acting, confirm the right person, the right record and the intended action using the identifiers required locally. Familiarity is not identification.'],['R','Reconcile','At transitions compare the best available medication history with the current plan, and involve the person or carer. Differences are questions, not answers.'],['C','Clarify','If an order, dose, route or product is unclear, stop and clarify through your local process with the responsible prescriber or pharmacist. Never guess.'],['R','Report','Record near misses through the organisational system. A near miss is free learning, but only if the system can see it.']]},
 viz:{k:'layers',t:'Defences in layers',c:'Each layer has holes. Harm reaches a person only when holes line up, so strengthening any one layer, including your pause, helps. This is often called the Swiss cheese model.',s:[['Prescribing and ordering','Clear, complete orders; decision support.'],['Preparation and checks','Independent checks; clear labels.'],['Your pause','Right person, record and action. Questions asked.'],['Handover and records','Verified plan reaches the next team.']]},
 terms:[['Near miss','An event that could have caused harm but did not, either by chance or because it was caught. A source of learning for the system.'],['Medication reconciliation','Comparing the best available list of what a person takes with what is ordered at a transition, resolving any unexplained difference with the responsible clinician.'],['Discrepancy','A difference between two accounts or records that needs explaining. It may be intentional and documented, or unintentional.'],['Transition of care','Any point where responsibility or information moves: admission, transfer between wards, discharge, a change of team or shift.']],
 sc:{s:'A fictional patient arrives on your ward from another unit. The transfer paperwork lists a medicine that the patient says they stopped last month. Both could be incomplete, and the next scheduled round is soon.',
  a:{q:'What is the safest first move?',o:[['Follow the paperwork. It is the most recent document, and add the patient’s comment as a note.',0,'Recency does not establish correctness. A note does not resolve the discrepancy, and the next person may act on the list alone.'],['Pause, record both accounts as they stand and ask the responsible prescriber or pharmacist to clarify through the approved process.',2,'You name the uncertainty and route it to someone with authority, without guessing in either direction.'],['Ask the patient to decide which version to follow.',1,'The patient’s account is valuable information, but deciding is not their responsibility and they may be unwell or unsure.']]},
  b:{q:'How do you make sure the answer reaches everyone?',up:'The pharmacist confirms the medicine was stopped and updates the plan.',dn:'The question is still open and the colleague on the next shift does not know.',o:[['Confirm the corrected plan is in the authorised record, tell the receiving team and the patient, and name who owns anything still unresolved.',2,'Verified information reaches the record, the team and the person, with ownership for open items.'],['Update the record and assume the next shift will see it.',1,'Recording is necessary but not sufficient. A short, direct handover closes the loop.'],['Tell the patient and consider it done.',0,'The patient is informed but the record and the team are not. The same discrepancy can reappear at the next transition.']]},
  end:['The discrepancy was handled informally, so the next team may meet the same uncertainty without knowing it exists.','A partly safe path. You paused and routed the question well, but the last steps left some risk of the answer not reaching everyone.','A strong path: you paused, routed the question to the responsible person and made sure the verified plan reached the record, the team and the person.']},
 spot:{t:'Read this fictional transfer note and mark each line that creates a safety risk.',l:[['“Patient identity checked against the wristband and the record before the handover.”',0,'Identity is confirmed using documented identifiers rather than recognition.'],['“Medicines: as per the old list, patient may have stopped one.”',1,'“May have” is unresolved uncertainty with no owner or action. It must be clarified, not passed on.'],['“Pharmacist asked to review the list. Outcome to be recorded by the day team.”',0,'A named route, a named owner and a place for the answer.'],['“It looks right to me. I’ve done this many times.”',1,'Experience and familiarity are not checks. They are exactly when mismatches are missed.'],['“Near miss logged so the team can look at how the lists diverged.”',0,'Reporting turns a close call into learning for the system.']]},
 myths:[['A pause slows care.','A short deliberate pause prevents rework and harm. It is a safety action, not a delay to apologise for.'],['If a record exists, it must be right.','Records can be incomplete, out of date or copied forward. The best available history combines sources, including the person.'],['A near miss does not need reporting because nothing happened.','Near misses show where defences are weak. Reporting is how the system learns without waiting for harm.'],['Asking for clarification shows I am not competent.','Clarifying an unclear order is competent, expected practice. Silent guessing is the risk.']],
 lad:{t:'How visible is the uncertainty?',h:'Slide from hiding uncertainty to resolving it.',s:[['Hidden','Carry on and hope it is fine.','Nobody knows there is a problem, including you next time.'],['Noted','A vague line in the notes: “may have stopped”.','Visible but ownerless. The next person inherits the doubt.'],['Raised','“This list and the patient disagree.” Said aloud.','Better. Someone now knows, but nobody has to act.'],['Routed','Raised with the responsible prescriber or pharmacist through the approved process.','The question has an owner with authority.'],['Resolved','Answer recorded, shared with the team and the person, and any open item owned.','The mismatch is gone and the next team starts from a verified plan.']]},
 chk:['I used the identifiers required locally and checked the record, not memory or recognition.','I checked allergy information against the intended task.','At transitions I compared at least two sources, including the person’s account.','I named every unexplained difference and who can resolve it.','I did not start, stop or change anything by inference.','I recorded the resolution in the authorised place and told the receiving team.','I reported any near miss through the organisational system.'],
 good:['Every discrepancy has a name, an owner and a recorded resolution.','The person and the receiving team hear the same verified plan.','Near misses are reported without fear of blame.'],
 rel:['med-transitions','human-factors','just-culture'],pr:['Where in your workflow would a deliberate pause prevent the most common near miss?','Which record do you trust most that might be copied forward without checking?','What would make it easier for you to report a near miss?']},

empathy:{lv:'Foundation',
 why:['Empathy in care is not a feeling you must have, but a skill you can show: noticing, naming what you hear and responding to it. Used well it helps people share what is really making a plan difficult, which is often practical, not clinical.','It has limits. Empathy does not mean agreeing with every request, guessing what someone feels or promising outcomes beyond your role. The most useful empathic responses are specific, brief and followed by action or a clear next step.'],
 fw:{n:'NURSE statements',i:'A widely taught set of five responses to emotion, often remembered as NURSE. Select a response.',p:[['N','Name','Say what you notice or hear. “It sounds like this has been very stressful.”'],['U','Understand','Show you are trying to understand, without claiming you know exactly how it feels. “I can see why that would be hard to manage.”'],['R','Respect','Acknowledge effort or strength. “You’ve clearly put a lot of thought into this.”'],['S','Support','Say what you can do within your role. “I can’t change the timetable, but I can ask who can help with transport.”'],['E','Explore','Ask a curious, open question. “What part is hardest?”']]},
 viz:{k:'compare',t:'Assumption or curiosity',c:'The same moment, handled two ways.',h:['Assuming','Curious'],s:[['“You need to prioritise your health.”','“What would make this plan difficult to follow?”'],['“Everyone finds this hard at first.”','“That sounds like a lot. Tell me more about what’s hardest.”'],['“I’ll just simplify the whole plan.”','“If we could change one thing, which would help most?”']]},
 terms:[['Empathy (in practice)','Recognising and responding to what another person is experiencing, shown through attentive listening and specific acknowledgement.'],['Validation','Acknowledging that a person’s experience makes sense to them. It does not mean agreeing with every request.'],['Empathic opportunity','A moment when a person signals feeling or concern, often indirectly, such as “I don’t know how I’ll manage”.'],['Compassion','Empathy joined with a motivation to help. It includes realistic action within your role.']],
 sc:{s:'A fictional patient says: “I don’t know how I’m supposed to do all of this at home.” The plan includes frequent appointments and daily tasks.',
  a:{q:'How do you respond first?',o:[['“It’s really important for your recovery that you follow the plan.”',0,'True but it skips the concern. It can feel like a reprimand and closes the conversation.'],['“It sounds like a lot to manage. What part feels hardest?”',2,'You named the feeling, invited detail and left space for the answer.'],['“Let me simplify it and give you a shorter version.”',1,'Helpful intent, but you chose the fix before knowing the barrier.']]},
  b:{q:'What do you do with what you hear?',up:'They explain that getting to appointments is the main barrier: they rely on someone else for transport.',dn:'They say “Everything, really,” and look tired.',o:[['Acknowledge the barrier, say what you can do within your role, and agree who will look at options and when you will come back.',2,'You turned empathy into a specific, honest next step with ownership.'],['Reassure them that “it’ll all work out”.',0,'A promise outside your control. It can feel dismissive and may not be true.'],['Offer to change the appointment times yourself without checking policy.',1,'Well meant but beyond your role if the schedule is another team’s decision.']]},
  end:['The plan was restated, but the barrier was never named, so it is likely to resurface.','Good intent and partly effective. Keep the next step specific and within your role.','A strong path: curiosity, acknowledgement and a realistic, owned next step.']},
 spot:{t:'Read this fictional exchange and mark the lines that replace curiosity with assumption.',l:[['“You seem a bit older, so I expect you’ll find the app confusing.”',1,'A judgement from age. Ask what support would help instead.'],['“What would make this easier to follow at home?”',0,'Open, specific and invites practical detail.'],['“I know exactly how you feel.”',1,'You cannot know. It can sound dismissive. Describe what you notice instead.'],['“That sounds like a lot to take in. Take your time.”',0,'Names the experience and leaves space.'],['“I can’t change the clinic times, but I can ask who can.”',0,'Honest about limits and offers an action within role.']]},
 myths:[['Empathy means telling people how they feel.','Guessing can be wrong and alienating. Describe what you notice and ask.'],['Being empathic means agreeing to every request.','You can acknowledge a request without granting it. Explain what you can do within your role.'],['Empathy takes too long.','A specific sentence and a pause often take seconds and save time later by surfacing barriers early.'],['If I am empathic I must fix the problem.','Sometimes listening is the intervention. Where action is needed, agree who will act.']],
 lad:{t:'From advice to partnership',h:'Slide from giving advice to exploring together.',s:[['Instruct','“You need to make this work.”','Directive. Ignores barriers and can feel judgemental.'],['Reassure','“Don’t worry, it’ll be fine.”','Soothes but closes the conversation and may overpromise.'],['Acknowledge','“That sounds like a lot.”','Names the experience. A good start but no information yet.'],['Explore','“What part is hardest?”','Invites detail that you can act on.'],['Partner','Acknowledge, explore, agree a next step and who owns it.','Shared problem-solving within your role.']]},
 chk:['I noticed words, tone and hesitation before responding.','I described what I noticed instead of assuming a feeling.','I asked one open question and waited.','I avoided promises outside my control.','I said what I can do within my role and what needs another service.','We agreed a next step, who owns it and when we will return to it.'],
 good:['The person can name the real barrier.','The next step is realistic, owned and within role.','The person feels heard, not managed.'],
 rel:['communication','dignity','compassion-boundaries'],pr:['When did an assumption about someone turn out to be wrong?','Which empathic phrase feels most natural for you, and which feels forced?','What do you do when the problem is beyond your role?']},

sbar:{lv:'Core',
 why:['Handovers and escalations fail less often because information is missing than because the listener does not know what is being asked, by when and who owns it. SBAR gives the speaker a predictable order and gives the listener somewhere to land.','A structure does not replace judgement. In an emergency, use your local emergency or escalation route first. SBAR is a way to be clear, not a queue to wait in. A structured handover programme has been associated with fewer errors in published work, but that programme had several parts beyond a mnemonic, so treat SBAR as one useful part of a safer handover.'],
 fw:{n:'SBAR',i:'Situation, Background, Assessment, Recommendation. Select each part.',p:[['S','Situation','Who you are, who the patient is (approved identifiers) and the immediate concern, with urgency. “I’m calling about a patient whose breathing has changed in the last hour. I am worried.”'],['B','Background','Only what the listener needs: reason for admission, recent changes, relevant context. Concise.'],['A','Assessment','What you have observed and what you think within your scope. Separate observed facts from interpretation. “Their observations have changed from this morning.”'],['R','Recommendation','Exactly what you need and by when. “Can you review them within the next 15 minutes, or tell me who will?” Then confirm who will act and the contingency.']]},
 viz:{k:'timeline',t:'A closed loop',c:'The message is not complete until the loop closes.',s:[['Send','Structured message with a clear request.'],['Acknowledge','The listener confirms they have received it.'],['Read back','The listener repeats the request and the plan.'],['Act','The owner does what was agreed, in the agreed time.'],['Report back','Outcome or delay is communicated. Escalate if it is not.']]},
 terms:[['SBAR','Situation, Background, Assessment, Recommendation: a structure for communicating a concern or handing over.'],['Closed-loop communication','A message is acknowledged, repeated back and confirmed, and the outcome is reported back to the sender.'],['Escalation','Taking a concern to someone with greater authority or expertise when the response so far is not enough, following local policy.'],['Contingency','What will happen, and who will act, if the agreed plan does not work or is not carried out.']],
 sc:{s:'In a fictional handover, you are worried about a patient whose condition has changed. The receiving colleague is busy and says: “Fine, I’ll see them when I can.”',
  a:{q:'What do you say?',o:[['“OK, thanks.” You leave, having mentioned it.',0,'The concern was mentioned but nobody owns the review or timing. Nothing has changed.'],['“I’m worried about this patient. The change is new since this morning. Can you review them within 15 minutes, or tell me who will?”',2,'Concern, evidence, a specific request and a time, with a route if they cannot.'],['Give a longer, detailed description of the whole admission.',1,'More background does not clarify the request. The listener still has no action to take.']]},
  b:{q:'Fifteen minutes pass with no review. What now?',up:'The colleague says “Sorry, I got pulled away.”',dn:'Nobody has come, and you are still worried.',o:[['Use the agreed contingency and escalate through the local route, stating the concern and what you need.',2,'You prearranged the contingency and use it. Persistence is part of the loop.'],['Wait a bit longer in case they are on their way.',0,'Silent waiting is how concerns get lost. If urgent, escalate immediately.'],['Mention it to a colleague on a different team.',1,'Informal sharing may help, but without the proper route nobody is accountable.']]},
  end:['The concern slipped through because the request and the owner were never explicit.','Partly effective. The structure helped, but the follow-through left a gap.','A strong path: a clear, structured request, a contingency and persistent escalation.']},
 spot:{t:'Mark the lines in this fictional SBAR message that make the next step unclear.',l:[['“Hi, I’m calling from ward 4 about Mrs Khan (fictional). Name and date of birth checked.”',0,'Clear identity using approved identifiers.'],['“She’s a bit off, nothing specific.”',1,'Vague. Describe what you observed and how it differs from her baseline.'],['“Her observations have changed since this morning and I’m worried.”',0,'States the change and the concern honestly.'],['“Someone should probably take a look at some point.”',1,'No owner, no timing, no request.'],['“Can you review her within 15 minutes? If not, who should I call next?”',0,'A specific request with a time and a contingency.']]},
 myths:[['SBAR guarantees a good handover.','It is a structure. Clarity, honesty and follow-through still depend on the speaker and listener.'],['I must complete SBAR before raising an emergency.','Activate the local emergency or escalation route immediately. Use SBAR when it does not delay help.'],['Long handovers are safer.','Concise, relevant information with a clear request is easier to act on than a long narrative.'],['Mentioning a concern is the same as escalating it.','Escalation means a specific request to a person with authority, a time and a follow-up.']],
 lad:{t:'How explicit is the recommendation?',h:'Slide to see how a vague hint becomes a clear request.',s:[['Hint','“It might be worth looking at.”','Easy to miss and easy to ignore.'],['Opinion','“I think they may be getting worse.”','Gives a view but no action.'],['Request','“Can you review them?”','An action, but no time and no owner.'],['Specific request','“Can you review them in 15 minutes?”','Clear action and timing.'],['Closed loop','Specific request, owner confirmed, contingency agreed, read back.','The action and its owner are unmistakable.']]},
 chk:['I identified myself, my role and the patient using approved identifiers.','I stated the concern and the urgency in the first sentence.','Background included only what the listener needs.','I separated what I observed from what I think.','I made a specific recommendation or request with a time.','The listener acknowledged and read back the plan.','We agreed who owns the action and the contingency.','I used the local emergency route for urgent concern.'],
 good:['The listener can say what you want, by when and who owns it.','A contingency exists if the plan fails.','Urgent concerns are never delayed by the format.'],
 rel:['deterioration','accountability','documentation'],pr:['Which part of your usual handover is least explicit: urgency, assessment, ownership or next step?','When did a concern you raised fail to land? What was missing?','What contingency phrase will you add?']},

infection:{lv:'Foundation',
 why:['Infection prevention works best as a routine that applies to everyone, because a person can carry or be exposed to infection without anyone knowing. Treating precautions as a starting point for every patient, then adding more when exposure or local guidance requires, protects patients and staff.','Most failures are not ignorance but sequence: a clean workflow that changes mid-task, such as touching a shared surface or moving between tasks without resetting. The lesson focuses on matching protection to the task and exposure and on safe reuse of shared equipment.'],
 fw:{n:'WHO five moments for hand hygiene',i:'A widely used framework for when to clean your hands. Select a moment.',p:[['1','Before touching a patient','To protect the patient from germs on your hands.'],['2','Before a clean or aseptic procedure','To protect the patient from germs, including their own, entering their body.'],['3','After body-fluid exposure risk','To protect yourself and the next patient or surface from germs.'],['4','After touching a patient','To protect yourself and the environment from the patient’s germs.'],['5','After touching patient surroundings','To protect yourself and the next patient from germs in the care environment.']]},
 viz:{k:'flow',t:'Protection around a task',c:'Think of prevention as a sequence around each task, not a single ritual.',s:[['Assess','What contact with blood, fluids, mucosa or non-intact skin do I expect?'],['Clean hands','At the required moment, before gloves.'],['Protect','Choose PPE for the task and exposure.'],['Do the task','Avoid touching shared surfaces unnecessarily.'],['Remove safely','Take off PPE in the right order and clean hands.'],['Reset equipment','Clean or reprocess shared items before reuse.']]},
 terms:[['Standard precautions','A baseline set of infection-prevention practices for all patients, matched to the task and anticipated exposure.'],['Transmission-based precautions','Additional measures, such as contact or droplet precautions, used when local policy and organism-specific guidance indicate.'],['PPE','Personal protective equipment chosen for the anticipated exposure and put on and removed in a safe sequence.'],['Reprocessing','The approved process that makes reusable equipment safe for its next use, such as cleaning, disinfection or sterilisation.']],
 sc:{s:'A fictional shared piece of equipment has just been used on one patient and is needed for the next, who has no known infection. It looks clean, and you are short of time.',
  a:{q:'What decides whether it can be reused?',o:[['It looks clean and the last patient had no known infection, so reuse it.',0,'Appearance and known diagnosis do not establish that equipment is ready. Infection can be present without a known diagnosis.'],['Follow the approved cleaning or reprocessing process for that item, then perform hand hygiene.',2,'The approved process, not appearance or assumption, makes equipment ready for reuse.'],['Wipe it with whatever is nearby.',1,'Some cleaning is better than none, but an unapproved product or method may not make it safe.']]},
  b:{q:'The task needs close contact with body fluids. What next?',up:'Equipment is ready and you have assessed the task.',dn:'You realise you did not assess the task first.',o:[['Assess the exposure, clean hands, choose PPE for the task, and remove it safely afterwards.',2,'Protection is matched to the exposure and sequenced safely.'],['Wear gloves and skip hand hygiene since gloves protect you.',0,'Gloves do not replace hand hygiene and can be contaminated or have defects.'],['Use the most protective PPE for everything, to be safe.',1,'Over-protecting wastes resources and can introduce its own risks. Match PPE to the task.']]},
  end:['Reuse relied on appearance and assumption, which leaves patients exposed.','Partly effective. Review the sequence so protection is matched to the task.','A strong path: approved reprocessing and a task-matched protection sequence.']},
 spot:{t:'Mark the lines in this fictional ward conversation that undermine safe practice.',l:[['“Neither patient has an infection, so we can skip the clean.”',1,'Standard precautions apply to everyone. Not knowing is not the same as not infected.'],['“I’ll follow the approved process for this equipment before the next use.”',0,'Right: the process, not appearance, decides.'],['“I wore gloves so I didn’t bother cleaning my hands.”',1,'Gloves do not replace hand hygiene.'],['“I’ll take PPE off in the right order and clean my hands after.”',0,'A safe removal sequence protects you and others.'],['“It looks clean so it’s fine.”',1,'Visible cleanliness does not show that equipment is ready.']]},
 myths:[['Standard precautions are for patients with known infections.','They apply to every patient, every time, matched to the task.'],['Gloves replace hand hygiene.','Hand hygiene is still needed at the required moments, before and after gloves.'],['More PPE is always safer.','Choose PPE for the exposure. Excess can cause errors and waste.'],['If it looks clean it is clean.','Equipment readiness depends on the approved cleaning or reprocessing process.']],
 lad:{t:'Matching protection to exposure',h:'Slide to see how precautions scale with exposure to blood or body fluids.',s:[['No patient contact','Clean hands at the right moments.','Baseline hygiene still applies.'],['Intact skin contact','Hand hygiene before and after.','Gloves not usually required for contact with intact skin, per local policy.'],['Possible splash','Hand hygiene plus eye and face protection and an apron or gown as per policy.','Choose for the anticipated exposure.'],['Blood or body fluids likely','Gloves, fluid-resistant protection and safe disposal and cleaning.','Match PPE to the exposure and remove safely.'],['Transmission-based precautions','Follow organism-specific local guidance.','Added to standard precautions, not instead of them.']]},
 chk:['I treated every patient with standard precautions.','I assessed the exposure for this task before choosing PPE.','I cleaned my hands at each required moment.','I did not rely on gloves in place of hand hygiene.','I removed PPE safely and cleaned my hands after.','I used the approved process to clean or reprocess shared equipment.','I knew who prepares equipment for the next patient.'],
 good:['Protection is matched to the task and exposure.','Shared equipment has a clear owner for readiness.','Hand hygiene happens at the moments that matter.'],
 rel:['safety','human-factors','improvement'],pr:['Which shared item in your area needs a clearer cleaning handoff?','At what point in a task do your routines most often break down?','Who can you ask when you are unsure which precaution applies?']},

reasoning:{lv:'Advanced',
 why:['Clinical reasoning blends fast pattern recognition with slower analytical checking. Fast thinking is efficient but vulnerable to predictable traps: anchoring on an early explanation, closing too soon on a diagnosis, and discounting information that does not fit.','The practical antidote is not to distrust expertise but to build in brief checks: separate observation from interpretation, ask what else it could be and what must not be missed, and make a plan for uncertainty. These habits are also useful for students and support staff, who often notice what does not fit.'],
 fw:{n:'The diagnostic pause',i:'Four questions to ask when something does not fit. Select a question.',p:[['1','What do I know?','Separate observations from interpretation, and note how reliable each is.'],['2','What else could it be?','List at least one other plausible explanation and the worst plausible one you should not miss.'],['3','What does not fit?','Name the finding that your working explanation cannot account for.'],['4','What will change my mind?','Say what finding or result would make you revise, and who will act on pending results.']]},
 viz:{k:'cycle',t:'Reasoning as a cycle',c:'The working explanation stays open to revision as new information arrives.',s:[['Observe','What is actually known and how reliable is it?'],['Interpret','Form a working explanation.'],['Pause','What else? What does not fit?'],['Test','Gather information that could change the view.'],['Reassess','Update and communicate the plan.']]},
 terms:[['Anchoring','Holding on to an early impression and giving too little weight to later information that points elsewhere.'],['Premature closure','Accepting an explanation before it has been adequately verified, which stops the search for alternatives.'],['Confirmation bias','Favouring information that supports the current view and discounting information that does not.'],['Safety-netting','Telling the person and team what to watch for, what to do and who will act if the situation changes, within local pathways.']],
 sc:{s:'In a fictional case, the team’s first explanation for a patient’s symptoms seemed likely. A new finding arrives that the explanation does not account for.',
  a:{q:'What do you do?',o:[['Note it, but stay with the first explanation until there is stronger evidence.',0,'This is anchoring. A finding that does not fit deserves attention now, not later.'],['Name the mismatch, ask what else could explain everything, and discuss it with the responsible team.',2,'You separate the new observation from the old interpretation and bring in other views.'],['Quietly gather more observations before saying anything.',1,'More information may help, but delaying the conversation can allow a wrong explanation to drive decisions.']]},
  b:{q:'How do you handle uncertainty in the plan?',up:'The team agrees to widen the possibilities and review.',dn:'The team continues with the original plan.',o:[['Agree what finding would change the view, who will act on pending results and what to do if things worsen.',2,'A plan for uncertainty makes the next decision safer.'],['Wait for the next routine review.',0,'Uncertainty without a trigger or owner can leave problems unnoticed.'],['Ask a senior colleague to confirm the original view.',1,'Seeking senior input is good, but asking only for confirmation invites confirmation bias.']]},
  end:['The mismatch was noticed but not acted on, so the first view stayed in charge.','Partly effective. You raised the issue but the plan for uncertainty was thin.','A strong path: you named the mismatch, widened the options and built a plan for uncertainty.']},
 spot:{t:'Mark the lines in this fictional case discussion that show reasoning traps.',l:[['“It’s definitely the first thing we thought of. Let’s not overcomplicate.”',1,'Certainty at an early stage closes the search. Name what you know and what you do not.'],['“This new result doesn’t fit. What else could explain it?”',0,'Names the mismatch and widens the search.'],['“The second opinion agrees with me, so we’re done.”',1,'If the second opinion only confirmed, it may not have been independent. Ask what would change the view.'],['“Let’s agree what finding would make us rethink and who will act.”',0,'Builds a plan for uncertainty.'],['“Let’s discuss what not to miss.”',0,'Considers the worst plausible alternative.']]},
 myths:[['Experts do not need to check themselves.','Experience speeds pattern recognition but also makes traps less visible. Brief checks help everyone.'],['A second opinion is always independent.','Asking someone to confirm your view invites agreement. Ask what else it could be.'],['Uncertainty means I am not competent.','Naming uncertainty clearly and planning for it is a sign of safe practice.'],['A reassuring label settles the question.','Labels should be revisited as information changes.']],
 lad:{t:'How open is the working view?',h:'Slide to move from a fixed conclusion to a revisable plan.',s:[['Fixed','“It’s X. Case closed.”','No room for new information.'],['Confident','“It’s probably X.”','Open in theory but nothing prompts review.'],['Open','“It’s probably X, but what else could it be?”','Considers alternatives.'],['Testable','“If Y happens we will rethink.”','Names what would change the view.'],['Safety-netted','Testable plus an owner for pending results and a plan if things change.','Uncertainty is managed, not ignored.']]},
 chk:['I separated what I observed from what I interpret.','I noted how reliable each observation is.','I listed another plausible explanation and one I must not miss.','I named what does not fit.','I said what would change my mind.','I assigned an owner to pending results.','I discussed uncertainty and the plan with the team and the person.','I sought senior help when concern exceeded my role.'],
 good:['The team can say what is known, unknown and what would change the plan.','Mismatches are raised early and welcomed.','Pending results have owners.'],
 rel:['humility','deterioration','risk-evidence'],pr:['What question could you add to your next case discussion to challenge an early assumption?','When did a first impression turn out to be wrong?','Who around you is good at asking “what else?”']},

speakup:{lv:'Core',
 why:['Teams make safer decisions when people can say what they see, including the newest member and the most senior. Silence is rarely agreement. It can reflect uncertainty about role, fear of embarrassment or past experience of being dismissed.','Psychological safety, the shared belief that a team is safe for interpersonal risk, describes the environment in which speaking up is likely. It is shaped most by how concerns are received. This lesson covers both halves: raising a concern clearly and persistently, and receiving one well.'],
 fw:{n:'CUS',i:'A TeamSTEPPS phrase that signals escalating concern. Select a word.',p:[['C','I am Concerned','States the observation or worry. “I’m concerned that the dose on the chart doesn’t match what we discussed.”'],['U','I am Uncomfortable','Signals the concern has not been resolved. “I’m uncomfortable going ahead until we check.”'],['S','This is a Safety issue','The strongest signal: stop and check. “This is a safety issue. I need us to pause.”']]},
 viz:{k:'timeline',t:'Raising a concern',c:'Each step is a little firmer. In an emergency, go straight to the local emergency response.',s:[['Notice','Name what you observed.'],['Ask','A question or concern in plain words.'],['State','CUS: concerned, uncomfortable, safety issue.'],['Persist','Repeat clearly and escalate by local policy.'],['Debrief','Review the system, not the person.']]},
 terms:[['Psychological safety','A shared belief that the team is safe for interpersonal risk, such as asking, admitting a mistake or disagreeing.'],['CUS','A TeamSTEPPS escalating phrase: I am Concerned, I am Uncomfortable, this is a Safety issue.'],['Two-challenge rule','A team agreement that a concern is stated at least twice, if not acknowledged, before it is escalated or acted on.'],['Chain of command','The route to someone with greater authority when a concern is not resolved, as defined by local policy.']],
 sc:{s:'In a fictional team huddle, a junior colleague says quietly: “I’m not sure that dose matches what we agreed.” The team is busy.',
  a:{q:'You are the person receiving the concern. What do you say?',o:[['“We’ve already discussed it. Let’s keep going.”',0,'This ends the conversation and teaches the person not to speak next time.'],['“Thank you for saying so. What did you notice? Let’s check now.”',2,'Thanks, curiosity and immediate checking make speaking up easier and safer.'],['“Can you write it down for the next team meeting?”',1,'Deferring a possible safety concern risks delay and discourages the person.']]},
  b:{q:'Now you are the junior colleague. The concern was brushed off. What next?',up:'The check confirmed a mismatch.',dn:'You were told it was fine, but you remain unsure.',o:[['Restate clearly: “I’m concerned and uncomfortable. This is a safety issue,” and escalate by local policy if needed.',2,'You persist with a clear phrase and use the route if it is still unresolved.'],['Say nothing more. You do not want to look foolish.',0,'Silence leaves the risk unaddressed. Most teams prefer a check to an incident.'],['Mention it later to a friend on the team.',1,'Venting may feel better but does not address the concern or reach someone who can act.']]},
  end:['The concern was not acted on, and the next person is less likely to speak.','Partly effective. Sharing concern more clearly and formally would help.','A strong path: the concern was received well and persisted with clarity.']},
 spot:{t:'Mark the lines that make speaking up harder.',l:[['“Thanks for raising that. Tell me what you saw.”',0,'Thanks and curiosity.'],['“I’ve been doing this for years. It’s fine.”',1,'Seniority is not evidence. It discourages challenge.'],['“I’m not sure if I should say, but maybe it’s probably nothing.”',1,'Hedged language makes a real concern easy to dismiss. Use a clear phrase like CUS.'],['“I’m concerned. I’m uncomfortable. This is a safety issue.”',0,'Clear, escalating and impossible to misread.'],['“Let’s review what made it hard to say this afterwards.”',0,'Turns the event into learning about the system.']]},
 myths:[['If no one speaks up, everyone agrees.','Silence can mean fear, uncertainty or past experience of being dismissed.'],['Speaking up is disloyal.','It protects patients and the team. Most teams value a check over an incident.'],['Only seniors should challenge.','Anyone can notice a problem. Roles differ but concerns belong to everyone.'],['A perfect script is needed.','In an emergency, act first. In other situations a clear plain sentence is enough.']],
 lad:{t:'How strong is your signal?',h:'Slide from a hint to a clear stop.',s:[['Hint','“Hmm, I wonder…”','Easy to miss or dismiss.'],['Question','“Can we check the dose?”','Prompts a check but is easy to answer lightly.'],['Concern','“I’m concerned about this dose.”','Clear statement of worry.'],['CUS','“I’m concerned, uncomfortable. This is a safety issue.”','Unmistakable and escalating.'],['Stop and escalate','Pause the task and use the local route.','For unresolved or urgent risk.']]},
 chk:['I named what I observed, not a judgement about a person.','I stated the possible consequence and asked for a response.','If not heard, I repeated clearly, using CUS if useful.','I escalated by local policy when unresolved.','In an emergency I activated the local response immediately.','When receiving a concern, I thanked the person and checked it now.','I debriefed the system, not the person.'],
 good:['Concerns are raised early and checked without humiliation.','People who speak up are thanked.','Unresolved concerns reach someone who can act.'],
 rel:['just-culture','conflict','inclusive-leadership'],pr:['How will you respond the next time someone questions your plan?','When did you stay silent? What would have helped you speak?','What phrase will you use to signal escalating concern?']},

shared:{lv:'Core',
 why:['When more than one reasonable option exists, the best choice depends on what matters to the person as well as what the evidence says. Shared decision-making brings the two together so that the decision reflects both.','Done well it also improves understanding. A Cochrane review summarised in the evidence panel found that decision aids improved knowledge compared with usual care, while remaining a supplement to, not a replacement for, the clinical conversation. Genuine choice matters: do not present a decision as shared when there is only one reasonable option.'],
 fw:{n:'SHARE',i:'AHRQ’s five steps for shared decision-making. Select a step.',p:[['S','Seek participation','Invite the person to take part and explain that there is a choice.'],['H','Help explore and compare options','Describe benefits, harms and uncertainty in balanced, plain language. Use decision aids where available.'],['A','Assess values and preferences','Ask what matters most and what concerns them about each option.'],['R','Reach a decision','Agree a plan together, with the responsible clinician where needed.'],['E','Evaluate the decision','Arrange a time to review, and revisit if circumstances change.']]},
 viz:{k:'flow',t:'A shared decision conversation',c:'Choice, options, preferences, decision, review.',s:[['Make the choice visible','There is more than one reasonable option.'],['Explore options','Benefits, harms, uncertainty. Same denominators.'],['Explore preferences','What matters most to you?'],['Decide together','Agree and document.'],['Revisit','Plan a review.']]},
 terms:[['Shared decision-making','A process in which clinician and person work together, combining best evidence with the person’s values and preferences.'],['Decision aid','A tool that gives balanced information about options and helps a person think about what matters to them.'],['Preference-sensitive decision','A decision where reasonable options differ in benefits, harms or burdens, so the best choice depends on what the person values.'],['Equipoise','A state in which there is no clear evidence that one option is better than another.']],
 sc:{s:'A fictional patient has two reasonable options with different practical burdens. One needs more visits but is less invasive. You know most people in similar circumstances pick the first.',
  a:{q:'How do you open the conversation?',o:[['“Most people choose option A. It’s the easiest decision.”',0,'A common choice may not match this person’s priorities, and it closes down exploration.'],['“There are two reasonable options. I’d like to go through the benefits, harms and what each involves for you. What matters most to you?”',2,'You make the choice visible and invite their priorities.'],['“I’ll explain the options and you can tell me which you prefer.”',1,'Better than recommending, but without exploring values the person may not know what to weigh.']]},
  b:{q:'The person says: “I live far from the clinic.” How do you use this?',up:'They have shared what matters.',dn:'They are quiet and unsure.',o:[['Acknowledge it, compare the options again with the travel burden in view, check understanding and agree a plan with a review date.',2,'You connect their circumstances to the options and keep the decision revisable.'],['Say it is not a big concern clinically.',0,'You dismissed a priority that is central to whether the plan will work.'],['Choose the option with fewer visits on their behalf.',1,'It may suit them, but the decision should be theirs, with the clinician.']]},
  end:['The decision was driven by the usual choice rather than the person’s priorities.','A reasonable path with room to bring the person’s values more fully into the decision.','A strong path: a visible choice, balanced options, their priorities and a review.']},
 spot:{t:'Mark the lines that undermine shared decision-making.',l:[['“Most patients go for option A.”',1,'Social proof is not a substitute for the person’s priorities.'],['“Out of 100 people, about 4 will have the problem with option A and 2 with option B, over five years.”',0,'Uses the same denominator and time frame, which makes comparison fair.'],['“B reduces the risk by 50%.”',1,'A relative figure on its own can mislead. Give the absolute figures as well.'],['“What matters most to you about this?”',0,'Explores values and preferences.'],['“We can look again in a few weeks if things change.”',0,'Plans a review.']]},
 myths:[['Shared decision-making means leaving it to the patient.','The clinician contributes expertise and recommendations. The decision combines both.'],['It takes too long.','A short, structured conversation can fit in routine care and may prevent later reversals.'],['Everyone wants to decide alone.','People differ in how much involvement they want. Ask.'],['There is always a choice.','Genuine shared decisions need more than one reasonable option. Do not pretend otherwise.']],
 lad:{t:'How much shared?',h:'Slide from one-way advice to a shared decision.',s:[['Announce','“We’ll do A.”','No choice offered.'],['Persuade','“A is best for most people.”','Advice, but not tailored to the person.'],['Inform','Explains options and the person decides alone.','Informative but misses the clinician’s expertise and the person’s values.'],['Explore','Explains options and asks what matters.','Starts to combine evidence and values.'],['Share','Options, values, decision, documentation and a review date.','Full shared decision.']]},
 chk:['I made it clear there is a genuine choice.','I asked how involved the person wants to be.','I explained benefits, harms and uncertainty in plain language.','I used the same denominators and time frames.','I asked what matters most to them.','I checked their understanding in their own words.','We agreed a plan and I documented it.','We arranged a review point.'],
 good:['The decision reflects both the evidence and the person’s priorities.','The person can describe the options and why they chose one.','There is a plan to revisit.'],
 rel:['risk-dialogue','risk-evidence','dignity'],pr:['What could you ask to uncover a priority not visible in the clinical record?','When have you assumed what someone would choose?','How will you check that a choice is genuinely theirs?']},

ai:{lv:'Core',
 why:['Digital and generative AI tools can draft, summarise and suggest quickly, and they can also produce fluent but wrong or incomplete output, including references that do not exist. The evidence panel summarises a study in which a notable share of citations generated by early large language models were fabricated.','Responsibility stays with the people using the tool. Three habits matter: know what the tool is approved for, protect confidential information, and verify important claims against the real source before relying on them. Local policy sets what is permitted.'],
 fw:{n:'Know, protect, verify, own',i:'Four habits for using any digital tool. Select a habit.',p:[['K','Know the tool','Check intended use, organisational approval and whether it has been evaluated for your setting.'],['P','Protect information','Do not enter patient-identifiable or confidential information into unapproved tools. Follow privacy and security rules.'],['V','Verify','Find the real source and check it supports the claim. Do not ask the same tool to vouch for itself.'],['O','Own the decision','A person with the right authority remains accountable. Follow local disclosure and documentation rules.']]},
 viz:{k:'flow',t:'Before you rely on generated output',c:'Treat it as an unverified draft until a person has checked it.',s:[['Approved?','Is this tool approved for this purpose?'],['Safe to share?','Remove identifiable and confidential detail, or do not use.'],['Real source?','Locate the actual source.'],['Supports it?','Does the source say what the output claims?'],['Owned','A responsible person decides and documents.']]},
 terms:[['Generative AI','A tool that produces new text, images or other content from patterns in training data. It can sound confident when it is wrong.'],['Hallucination','Output that is fluent and plausible but unsupported or false, such as an invented reference.'],['Automation bias','The tendency to trust output from an automated system more than it deserves, especially under time pressure.'],['Data minimisation','Using only the information necessary for a defined purpose, and no more.']],
 sc:{s:'A fictional AI tool produces a summary for your team. It includes a confident recommendation citing a paper you do not recognise.',
  a:{q:'What do you do first?',o:[['Use it. The citation and the wording look professional.',0,'A citation can look real and be false. Fluent text is not evidence.'],['Locate the actual source, check what it supports and use the approved review process before relying on it.',2,'Verification against the real source is the strongest step.'],['Ask the tool to explain the citation more fully.',1,'Asking the same tool is not independent. It may produce more convincing but still unverified detail.']]},
  b:{q:'A colleague suggests pasting a patient note into a free public tool to speed things up.',up:'The source check shows the paper does not support the claim.',dn:'You are not sure the source checks out.',o:[['Say no, explain that identifiable information needs an approved route, and ask the information-governance contact how to proceed.',2,'You protect confidentiality and use the proper route.'],['Remove the name and paste it, since that makes it anonymous.',0,'Removing a name alone may not anonymise a note. Dates, locations and rare details can identify a person.'],['Paste only a short part.',1,'Less is better than more but still risks sharing identifiable information with an unapproved service.']]},
  end:['Unverified output and unapproved sharing put patients and trust at risk.','Partly effective. Strengthen both verification and information protection.','A strong path: you verified the source and protected information.']},
 spot:{t:'Mark the lines in this fictional message that show risky use of a digital tool.',l:[['“The summary includes a reference, so it must be reliable.”',1,'References can be wrong or fabricated. Find the source.'],['“I checked the source and it does support the claim.”',0,'Independent verification.'],['“I pasted the patient’s note, minus the name, into a free tool.”',1,'Removing a name alone does not guarantee anonymity, and the tool may be unapproved.'],['“I asked who in information governance can advise on approved tools.”',0,'Uses the proper route.'],['“The tool said it is accurate.”',1,'A tool vouching for itself is not independent verification.']]},
 myths:[['A confident answer is a correct one.','Generative tools can be fluent and wrong. Verify against real sources.'],['If I remove the name it is anonymous.','Combinations of details can identify someone. Use approved routes.'],['The tool is responsible for the result.','Accountability stays with the authorised human team.'],['Checking takes longer than writing it myself.','Verification focuses on the key claims and is usually faster than starting from scratch.']],
 lad:{t:'How much do you rely on the output?',h:'Slide from blind trust to verified use.',s:[['Blind trust','Use it as written.','Errors flow straight into practice.'],['Skim','Read it and it seems fine.','Plausible is not verified.'],['Cross-check','Ask the same tool again.','Not independent. Repeated errors can look consistent.'],['Verify','Find the real source and check the claim.','Independent and specific.'],['Verified and owned','Verified, approved route, responsible person decides.','Appropriate use.']]},
 chk:['The tool is approved for this purpose.','No patient-identifiable or confidential information went into an unapproved tool.','I found the real source of each important claim.','I checked the source supports the claim.','I did not ask the tool to verify itself.','A responsible person made and documented the decision.','I followed local rules on disclosure.','I know my information-governance contact.'],
 good:['Every important claim has a checked source.','Confidential information stays in approved systems.','The human decision-maker is named.'],
 rel:['data-stewardship','reasoning','risk-evidence'],pr:['What is one clear boundary you need before using a digital or AI tool?','When did you trust something because it looked professional?','Who can help you check a source quickly?']},

wellbeing:{lv:'Foundation',
 why:['Strain is a normal response to sustained demand and is not a personal failing. Persistent exhaustion, reduced concentration or a loss of connection can affect both wellbeing and safe practice. The evidence panel summarises an observational review that found burnout associated with higher odds of reported safety incidents. Association does not prove cause, but it supports taking workload seriously.','Personal habits help but cannot compensate for unsafe staffing or unrealistic workload. The World Health Organization describes burnout as an occupational phenomenon resulting from chronic workplace stress, not a medical condition. Sustainable care needs action at three levels: individual, team and organisation.'],
 fw:{n:'Three levels of action',i:'Wellbeing is shaped at several levels. Select a level.',p:[['1','You','Notice early signs, meet basic needs, take brief pauses and ask for support.'],['2','Your team','Share workload openly, cover for each other, check in, and raise concerns together.'],['3','Your organisation','Safe staffing, rest, fair rotas, accessible support and a culture where raising workload is safe.']]},
 viz:{k:'matrix',t:'What you can change, and what needs others',c:'A pause helps in the moment. It does not fix a workload that is unsafe.',s:[['Now','A pause, a drink, a quiet minute or a word with a colleague.','You'],['This week','Ask for help, adjust a task, speak to a supervisor.','Team'],['Over time','Staffing, rotas, workload review, support services.','Organisation']]},
 terms:[['Burnout (WHO)','An occupational phenomenon resulting from chronic workplace stress that has not been successfully managed. It is not classified as a medical condition.'],['Moral distress','Distress when you know what care is needed but constraints prevent you from providing it.'],['Occupational health','A service that supports employees’ health at work, including advice on adjustments and referral.'],['Peer support','Structured or informal support from colleagues who understand the work.']],
 sc:{s:'A fictional colleague says they are exhausted and finding it hard to concentrate. They have felt this way for weeks.',
  a:{q:'How do you respond?',o:[['“Try some deep breathing and push through the week.”',0,'A short exercise does not address persistent strain, and “push through” can raise risk.'],['Listen, ask what would help, and say you can help find the right support, including through their supervisor or occupational health.',2,'You offer immediate support and a route to action on the cause.'],['Share some self-care links and leave it there.',1,'Resources help but persistent strain also needs a conversation about workload.']]},
  b:{q:'They mention unsafe workload. What next?',up:'They agree to speak to a supervisor.',dn:'They say there is nothing anyone can do.',o:[['Encourage them to raise it with the supervisor, offer to support them or raise it as a team, and check in again.',2,'You treat workload as a team and organisational matter and stay connected.'],['Take on extra tasks yourself to help them indefinitely.',1,'Kind, but it hides the gap and is not sustainable.'],['Tell them to keep it to themselves.',0,'Hiding workload concerns removes the chance to fix them.']]},
  end:['Strain was treated as a personal weakness and stayed hidden.','Partly effective. Pair personal support with a route to address workload.','A strong path: practical support now and attention to the conditions causing the strain.']},
 spot:{t:'Mark the lines that treat a systemic problem as an individual one.',l:[['“If you were more organised you would cope.”',1,'Blames the individual and ignores workload.'],['“It sounds like you’ve been carrying a lot. What would help?”',0,'Listens and asks.'],['“Just take a break and you’ll be fine.”',1,'A break helps but does not fix persistent strain.'],['“Let’s raise the workload with the supervisor together.”',0,'Treats workload as a team and organisational matter.'],['“If it continues, please speak to occupational health or a qualified professional.”',0,'Points to qualified help for persistent strain.']]},
 myths:[['Burnout is a personal weakness.','It is a response to chronic workplace stress, not a character flaw.'],['A resilience course will fix it.','Individual skills help, but they cannot replace safe staffing and fair workloads.'],['Asking for help shows I cannot cope.','Asking early is a protective and professional step.'],['If I am still working, I am fine.','Concentration, sleep and mood changes can occur while still working and deserve attention.']],
 lad:{t:'How early is support used?',h:'Slide from pushing on to getting support early.',s:[['Push on','Ignore the signs.','Strain builds and can affect safety and health.'],['Notice','Recognise changes in concentration, mood or sleep.','Awareness is the first step.'],['Adjust','Take a pause, meet a basic need.','Helps in the moment.'],['Ask','Tell a colleague or supervisor.','Brings in help and shared problem-solving.'],['Use support','Occupational health, a qualified professional or your organisation’s service.','For persistent distress. For immediate danger use local emergency support.']]},
 chk:['I noticed changes in concentration, sleep, mood or connection.','I made one small adjustment where I could.','I asked a colleague or supervisor for support.','I raised workload or safety concerns through the appropriate route.','I know how to contact occupational health or support services.','For persistent distress I sought qualified help.','In immediate danger I use local emergency support.'],
 good:['People feel able to say when they are struggling.','Workload concerns lead to action.','Support is easy to find and use.'],
 rel:['compassion-boundaries','humility','accountability'],pr:['Who can you approach for practical support, and what specific request could you make?','What are your early signs of strain?','What would make it easier for your team to talk about workload?']},
equity:{lv:'Foundation',
 why:['A standard approach quietly assumes a standard person: someone who reads the language, hears the explanation, can travel to the appointment and trusts the service. People for whom that is not true can be left out without anyone intending it, and agreement in the room does not show that a plan will work at home.','Cultural humility describes a stance rather than a checklist: ongoing self-reflection, learning from the person, attention to power differences and a commitment to changing the systems that create barriers. The evidence panel cites US survey data showing that disability and access needs are common, which is a reminder to expect variety, never to guess about an individual.'],
 fw:{n:'Four habits of cultural humility',i:'A practical reading of cultural humility. Select a habit.',p:[['1','Reflect','Notice your own assumptions and how your role gives you power in the conversation.'],['2','Ask and listen','Ask about preferred name, language, communication needs and what would make care more accessible. Speak directly to the person.'],['3','Share power','Offer real choices about format, involvement and timing. Use a qualified interpreter and accessible formats through your service.'],['4','Change the system','Raise barriers that your process creates, such as forms, times or locations, so they are fixed rather than worked around.']]},
 viz:{k:'compare',t:'Same for everyone, or fitted to the person',c:'Equity means adjusting support so people can reach a similar outcome. It is different from treating everyone identically.',h:['Standard approach','Equitable approach'],s:[['One leaflet in one language','Asks which language and format works, then arranges it'],['A family member interprets','A qualified interpreter is offered, and the person decides who else is present'],['“Please book online”','Asks what booking method works for the person'],['Plan agreed in a single appointment','Checks that cost, transport and support make the plan workable']]},
 terms:[['Cultural humility','A lifelong practice of self-reflection, learning from the person, addressing power imbalances and holding services accountable for barriers.'],['Qualified interpreter','A trained professional who interprets accurately and impartially, arranged through your service. This is different from a family member or an ad hoc helper.'],['Accessible format','Information provided in a form the person can use, such as large print, easy read, audio or a translated version.'],['Structural barrier','A feature of how a service is organised, such as hours, location or forms, that makes it harder for some people to use.']],
 sc:{s:'A fictional patient agrees to a follow-up plan, but nobody has asked about language or access needs. A relative offers to translate and says the standard leaflet is fine.',
  a:{q:'How do you respond?',o:[['Accept the offer and give the standard leaflet. They seem happy.',0,'Agreement is not evidence of understanding, and relying on a relative can limit privacy and accuracy.'],['Ask the patient directly which language and format work best and offer a qualified interpreter through your service.',2,'You speak to the person, ask rather than assume and use the proper route.'],['Ask whether they are comfortable continuing in this language.',1,'It invites a response, but it is a yes/no question and does not explore options or support.']]},
  b:{q:'The patient says travel is a problem. What now?',up:'They choose a qualified interpreter and an easy-read format.',dn:'They hesitate and say “It’s fine.”',o:[['Explore cost, transport and support, then involve the right team to adapt the plan while keeping it safe.',2,'You test whether the plan can work in real life and use your service to change it.'],['Tell them to arrange transport themselves.',0,'This puts the barrier back on the patient.'],['Note it and move on, as the plan is already agreed.',1,'Noting is better than nothing, but the barrier remains unresolved.']]},
  end:['The standard approach stayed in place and the plan is likely to fail quietly.','Partly effective. You asked well but did not fully adapt the plan.','A strong path: you asked, used proper support and adapted the plan to the person.']},
 spot:{t:'Mark the lines that assume rather than ask.',l:[['“Their daughter can translate, no need for an interpreter.”',1,'Assumes the person is happy with this and that the relative can interpret accurately. Ask the person.'],['“Which language and format work best for you?”',0,'Asks rather than assumes.'],['“They said yes, so they understand.”',1,'Agreement does not show understanding.'],['“I can arrange a qualified interpreter through our service.”',0,'Uses the proper route.'],['“Let’s check the plan works with your travel and costs.”',0,'Tests real-world feasibility.']]},
 myths:[['If someone agrees, they understand.','Agreement can reflect politeness or difficulty speaking up. Check understanding.'],['A family member can always interpret.','Qualified interpreters support accuracy, privacy and the person’s choice. Offer one through your service.'],['Equity means treating everyone the same.','Equity means fitting support to need so that people can reach similar outcomes.'],['I can tell what someone needs from how they look.','Needs are often invisible. Ask.']],
 lad:{t:'How accessible is the explanation?',h:'Slide from a one-size approach to one fitted to the person.',s:[['One size','Standard leaflet for everyone.','Leaves out people the format does not suit.'],['Ask if they need help','“Do you need any help?”','Easy to decline out of politeness.'],['Ask what works','“Which language or format works best?”','Specific and invites a real answer.'],['Arrange support','Qualified interpreter or accessible format arranged.','Support actually in place.'],['Check the whole plan','Support in place and the plan tested against cost, transport and trust.','Equity reaches beyond the conversation.']]},
 chk:['I asked about preferred name, language and communication needs.','I spoke directly to the person.','I offered a qualified interpreter or accessible format through my service.','I did not infer understanding from agreement.','I asked about cost, transport and support.','I involved the relevant team to adapt the plan safely.','I reported barriers that my process creates.'],
 good:['The person can use the information in the way they prefer.','The plan fits the person’s real circumstances.','Barriers are reported and reduced.'],
 rel:['dignity','health-literacy','inclusive-leadership'],pr:['What is one barrier your standard appointment process may create, and who can help change it?','When have you assumed something about someone that turned out to be wrong?','What would make asking about access feel routine?']},

improvement:{lv:'Advanced',
 why:['Improvement begins with a process that is fragile, not a person to blame. Because changes can have unintended effects, the safest way to learn is a small, approved test with a clear aim and a measure, rather than a large rollout based on hope.','The Model for Improvement asks three questions: what are we trying to accomplish, how will we know that a change is an improvement, and what change can we make? Plan-Do-Study-Act (PDSA) cycles then test ideas on a small scale. The evidence panel notes that audit and feedback improves practice on average but with variable effects, which is why measuring and adapting matter.'],
 fw:{n:'Model for Improvement',i:'Three questions and a test cycle. Select a question.',p:[['1','What are we trying to accomplish?','A specific, time-bound, measurable aim that matters to the people affected.'],['2','How will we know a change is an improvement?','Choose an outcome measure, a process measure and a balancing measure to catch unintended effects.'],['3','What change can we make?','Choose a small change, agree it with the right people and approval, and test it on a small scale.'],['4','Plan-Do-Study-Act','Plan the test, try it, study what happened compared with your prediction, act: adopt, adapt or abandon.']]},
 viz:{k:'cycle',t:'A PDSA cycle',c:'Small cycles, repeated. Learn quickly and safely before scaling.',s:[['Plan','State the question, predict the result, plan who, what, when and the measure.'],['Do','Run the test on a small scale. Note problems and surprises.'],['Study','Compare results with the prediction. What did you learn?'],['Act','Adopt, adapt or abandon. Plan the next cycle.']]},
 terms:[['PDSA cycle','Plan, Do, Study, Act: a structured way to test a change on a small scale and learn from it before wider use.'],['Aim statement','A specific, measurable, time-bound description of what a team is trying to achieve.'],['Balancing measure','A measure that checks whether a change has caused a problem elsewhere, such as added time or workload.'],['Run chart','A simple time-ordered plot of a measure that helps a team see whether a change is followed by a real shift.']],
 sc:{s:'A fictional team notices that handovers often leave out who owns pending tasks. A manager proposes a new form across the whole service next week.',
  a:{q:'What do you suggest?',o:[['Remind everyone to be more careful and roll out the new form.',0,'A reminder rarely changes a fragile process, and a large rollout cannot be undone easily.'],['Test one small ownership prompt on one team with approval, and agree how to measure missed owners and added time.',2,'A small, approved test with a measure and a balancing measure makes learning safe.'],['Trial the new form service-wide and collect comments.',1,'Comments help but a service-wide change without a measure makes it hard to tell what worked.']]},
  b:{q:'After two weeks, owners are named more often but handovers take longer. What now?',up:'The team studies the data together.',dn:'People are using workarounds.',o:[['Study both results, adapt the prompt to cut the extra time, and run another small cycle.',2,'You used the balancing measure to adapt rather than declare success or failure.'],['Declare success because ownership improved.',0,'Ignoring the balancing measure misses a harm that could undermine the change.'],['Stop. Any extra time is unacceptable.',1,'It may be right to stop, but adapting may keep the benefit while reducing the burden.']]},
  end:['The change was not tested or measured, so the team cannot tell whether it helped.','Partly effective. A clearer measure or balancing check would strengthen learning.','A strong path: a small approved test with a measure and a balancing measure, and adaptation.']},
 spot:{t:'Mark the lines in this fictional improvement plan that weaken learning.',l:[['“We will make handovers better.”',1,'Too vague to measure. State what, how much and by when.'],['“Within eight weeks, 90% of handovers will name an owner for each pending task.”',0,'Specific, measurable and time-bound.'],['“We will roll it out everywhere and see what happens.”',1,'No small test and no way to judge the effect.'],['“We will also track time per handover so we notice any extra burden.”',0,'A balancing measure.'],['“If it does not work, we will adapt or stop.”',0,'Plans a decision after studying results.']]},
 myths:[['Improvement means a big new system.','Small tests reduce risk and speed learning.'],['If the main measure improves, the change worked.','Check balancing measures for unintended effects.'],['A reminder is an improvement.','Reminders rarely change fragile processes. Redesign the step.'],['Improvement needs no approval.','Changes affecting patients or process need approval per local governance.']],
 lad:{t:'How strong is the test?',h:'Slide from a vague intention to a well-designed test.',s:[['Intention','“We should improve this.”','No way to know if it worked.'],['Idea','“Let’s try a new form.”','A change but no aim or measure.'],['Aim','“Name an owner in 90% of handovers in eight weeks.”','Clear target.'],['Test','Aim, small trial, approved, one team.','Safe to learn from.'],['Measured test','Aim, small trial, outcome, process and balancing measures, review.','Learning you can trust and adapt.']]},
 chk:['I described the process, not a person to blame.','I involved the people who do the work and those affected.','I wrote a specific, measurable, time-bound aim.','I chose a small change and obtained approval.','I chose an outcome, a process and a balancing measure.','I predicted the result before the test.','I studied the result and decided: adopt, adapt or abandon.','I shared learning without identifiable patient details.'],
 good:['Each change has an aim, a measure and an owner.','Tests are small and reversible.','Unintended effects are noticed early.'],
 rel:['human-factors','just-culture','debrief'],pr:['What small workflow improvement could your team test, and how would you know it helped?','What balancing measure would reassure you?','Who needs to approve the test?']},

'health-literacy':{lv:'Foundation',
 why:['Health literacy is not a trait that some people have and others lack. It describes the fit between what a person can do and what a service demands. Stress, illness, a new setting or unfamiliar words can lower anyone’s capacity to understand, so clear information benefits everyone.','The AHRQ Health Literacy Universal Precautions Toolkit takes this approach: assume that anyone may find information hard to use and make it clear for all. The responsibility for making an explanation usable sits with the service, not the person.'],
 fw:{n:'Ask Me 3',i:'Three questions people can ask, and clinicians can answer. Select a question.',p:[['1','What is my main problem?','Name the main issue in everyday words, not a label or abbreviation.'],['2','What do I need to do?','Give one or two clear next actions, including when and who.'],['3','Why is it important for me to do this?','Link the action to what matters to the person.']]},
 viz:{k:'compare',t:'Jargon and plain language',c:'The same message, more usable.',h:['Hard to use','Easier to use'],s:[['“NBM from midnight. Review PRN.”','“Please do not eat or drink anything after midnight. We will check on you if you need us.”'],['“Follow up with your GP in 2/52.”','“Please see your doctor in two weeks. Book the appointment when you get home.”'],['“Take as directed.”','“Take one tablet each morning. The label says when to stop.”']]},
 terms:[['Health literacy','The degree to which a person can find, understand and use information and services to make health decisions. It depends on both the person and the demands of the service.'],['Plain language','Writing and speaking so people can understand, find and use information the first time.'],['Universal precautions (health literacy)','Assuming everyone may have difficulty understanding health information and making communication clear for all.'],['Chunking','Breaking information into small manageable pieces and checking understanding between pieces.']],
 sc:{s:'A fictional person follows a conversation until several abbreviations appear in the appointment instructions. They say “OK” but look unsure.',
  a:{q:'What do you do?',o:[['Repeat the abbreviations more slowly.',0,'Slower repetition of unfamiliar terms does not make them clearer.'],['Replace the abbreviations with everyday words, focus on one action, and ask them to explain the next step.',2,'Plain words, one action and a check make information usable.'],['Assume “OK” means understanding and move on.',1,'This hides the gap. A polite OK is not understanding.']]},
  b:{q:'They say the next step back, but miss the booking part.',up:'They have explained most of the plan correctly.',dn:'They struggle to explain it at all.',o:[['Say you will explain that part more clearly, re-explain differently, offer a short written summary and check again.',2,'You repaired the gap, supported it with a summary and rechecked.'],['Hand over the leaflet and tell them to read it later.',1,'Writing helps but does not fix the gap now.'],['Tell them to ask their family.',0,'It shifts the explanation to someone else without checking.']]},
  end:['The message did not land and the instruction stayed hard to use.','Partly effective. Keep checking and keep language plain.','A strong path: plain words, one action, teach-back and a short summary.']},
 spot:{t:'Mark the lines that make the information harder to use.',l:[['“The instructions are standard. Please read them again.”',1,'Puts the burden on the person and ignores why they were hard to follow.'],['“Let’s put this into everyday words together.”',0,'Shares responsibility.'],['“You’ll need to NBM and attend the OPD on Tuesday.”',1,'Abbreviations and jargon.'],['“The main thing is to come to the clinic on Tuesday. Can you tell me how you’ll get there?”',0,'One priority action and a practical check.'],['“Would it help to have this in a short written summary?”',0,'Offers an accessible format.']]},
 myths:[['Some people just have low literacy.','Understanding varies with stress, setting and demands. Make clarity universal.'],['Using plain language is dumbing down.','Clear language makes information accessible to everyone, including experts under pressure.'],['A leaflet solves it.','Leaflets help only when the person can use them. Check and support.'],['If they do not ask questions they understand.','Many people do not ask. Check with teach-back.']],
 lad:{t:'How usable is the instruction?',h:'Slide from jargon to a fully usable plan.',s:[['Jargon','“NBM, review PRN.”','Hard for anyone outside the specialty.'],['Simplified words','“Do not eat or drink.”','Better but not clear when or why.'],['One clear action','“Do not eat or drink after midnight.”','Actionable.'],['With a reason','“…so the procedure is safe.”','Linked to what matters.'],['Checked and supported','Plain, one action, reason, teach-back and a written summary.','Information the person can use.']]},
 chk:['I used everyday words and explained any term.','I put the most important action first.','I limited the amount of information.','I offered language, format and communication support.','I used teach-back to check my explanation.','I gave a short written summary where helpful.','I asked whether the plan works in the person’s life.'],
 good:['The person can say what to do next and why.','Instructions are short, clear and in the right format.','The service takes responsibility for clarity.'],
 rel:['teachback-skill','communication','equity'],pr:['Which instruction in your service needs a clearer next action?','Which abbreviation do you use without thinking?','How could you check usability with a real user?']},

'risk-evidence':{lv:'Advanced',calc:1,
 why:['Numbers feel objective, but the same finding can look large or small depending on how it is presented. A claim that something “halves” a risk says nothing about how big the risk was to start with, how many people are affected or over what time.','The core habit is to ask: compared with what, among whom and over how long. Convert relative changes into absolute differences, check that benefits and harms use the same scale and consider whether the study population resembles the person in front of you.'],
 fw:{n:'Four questions for any claim',i:'Ask these before accepting a number. Select a question.',p:[['1','Compared with what?','Against no treatment, usual care or another option? A reduction needs a baseline.'],['2','Among whom?','Does the study population resemble the person you are talking about?'],['3','Over how long?','A risk over one year is not the same as over ten.'],['4','How certain?','Look at study design, size and uncertainty. An association is not automatically a cause.']]},
 viz:{k:'timeline',t:'From headline to meaning',c:'In a fictional example an outcome falls from 4 in 100 to 2 in 100.',s:[['Headline','“Halves the risk.” That is a 50% relative reduction.'],['Baseline','4 in 100 to begin with.'],['Absolute change','2 fewer in 100: a 2 percentage-point reduction.'],['Number needed to treat','About 50 people treated for one to benefit (1 divided by 0.02).'],['Context','Time frame, harms, population and certainty.']]},
 terms:[['Absolute risk reduction','The difference between two risks, such as 4% and 2%: a reduction of 2 percentage points.'],['Relative risk reduction','The proportional change: from 4% to 2% is a 50% relative reduction. It does not show the starting size.'],['Number needed to treat','The number of people who would need to receive an intervention for one additional person to benefit, calculated as 1 divided by the absolute risk reduction.'],['Denominator','The total number of people or events a count is out of. A count without one is hard to interpret.']],
 sc:{s:'A fictional flyer says an intervention “halves the risk” of an outcome. Your team is deciding whether to promote it.',
  a:{q:'What do you ask first?',o:[['Nothing. Halving sounds big, so promote it.',0,'A relative claim without the baseline can be misleading. A halved tiny risk is still tiny.'],['Ask for the starting and ending risks, the population and the time period.',2,'You requested the absolute figures and context.'],['Check how many people the flyer says it helped.',1,'A count without a denominator and time frame is hard to interpret.']]},
  b:{q:'The absolute figures are 4 in 100 versus 2 in 100 over one year. How do you explain it?',up:'You have the figures.',dn:'The flyer gives no timeframe.',o:[['“About 2 fewer people in 100 over a year. Let’s also look at harms, who was studied and how certain this is.”',2,'Absolute difference, time frame and context together.'],['“It reduces risk by 50%, which is substantial.”',0,'Repeats the relative figure and hides the absolute size.'],['“About 2% less.”',1,'Closer, but 2 percentage points should be clear and framed per 100 people with a time frame.']]},
  end:['The relative figure drove the decision, which can exaggerate benefit.','Partly effective. Pair absolute figures with time frame and population.','A strong path: baseline, absolute difference, time frame and context.']},
 spot:{t:'Mark the lines that make a number misleading.',l:[['“Cuts the risk by 50%.”',1,'Relative only. Give the starting and ending risks.'],['“From 4 in 100 to 2 in 100 over one year.”',0,'Absolute figures with a time frame.'],['“Fifty percent means 50 fewer people in every 100.”',1,'A common mistake. A 50% relative reduction of 4 in 100 is 2 fewer in 100.'],['“The study was in a different population, so we should be cautious.”',0,'Considers whether results transfer.'],['“It was associated with improvement, so it caused it.”',1,'Association is not proof of cause.']]},
 myths:[['A 50% reduction means 50 fewer in 100.','It means half of whatever the starting risk was. From 4 in 100 that is 2 fewer.'],['Percentages are always enough.','Without a denominator and a time frame a percentage is hard to interpret.'],['If a study found an effect, it applies to everyone.','Check whether the population and setting resemble yours.'],['Association means cause.','Studies can show association. Cause needs more careful design and judgement.']],
 lad:{t:'How complete is the claim?',h:'Slide from a headline to a claim you can use.',s:[['Headline','“Halves the risk.”','No baseline, time or population.'],['Percentage','“A 50% reduction.”','Still relative.'],['Absolute','“4 in 100 to 2 in 100.”','The real size of the change.'],['With time frame','“…over one year.”','Comparable and interpretable.'],['In context','Absolute, time frame, harms, population and certainty.','A claim you can use in a decision.']]},
 chk:['I asked: compared with what, among whom and over how long.','I converted relative figures to absolute figures.','I used the same denominator and time frame for benefits and harms.','I considered whether the population resembles the person.','I checked study design and uncertainty.','I did not treat association as cause.','I said clearly when evidence does not apply cleanly.'],
 good:['Every number comes with a baseline and a time frame.','Benefits and harms use the same scale.','Uncertainty is stated, not hidden.'],
 rel:['risk-dialogue','reasoning','shared'],pr:['Where could a percentage in your work benefit from a denominator?','Which headline have you repeated without checking the baseline?','How would you explain 4 in 100 to 2 in 100 to a friend?']},

'human-factors':{lv:'Advanced',
 why:['Human factors, or ergonomics, studies how people, tasks, tools and environments fit together. It starts from a simple observation: people are not reliable machines. Memory fails under interruption, attention is limited and workarounds appear when a process does not fit the work.','A direct observational study summarised in the evidence panel found more interruptions during medication administration were associated with more errors. Association does not show a universal rate, but it supports redesigning work so that critical steps are protected, rather than telling people to concentrate harder. In safety investigation methods, redesigning a step is usually considered stronger than reminders or retraining.'],
 fw:{n:'Work system elements',i:'A system view of work, drawn from the SEIPS approach. Select an element.',p:[['P','People','Skills, training, fatigue, workload and how roles interact.'],['T','Tasks','What must be done, in what order, with what interruptions and decision points.'],['O','Tools and technology','Equipment, software and checklists, and how well they fit the task.'],['E','Environment','Space, noise, lighting, layout and distractions.'],['G','Organisation','Staffing, policies, culture, supervision and incentives.']]},
 viz:{k:'matrix',t:'Strength of a response',c:'When an error recurs, stronger actions change the design of the work. Weaker ones rely on memory and effort.',s:[['Stronger','Redesign the task, remove a step, forcing function, standardise equipment.','Stronger'],['Intermediate','Checklist at the point of work, software prompt, workload reduction.','Intermediate'],['Weaker','Reminder, retraining, policy memo, “be more careful”.','Weaker']]},
 terms:[['Human factors','The study of how people interact with tasks, tools, environment and organisation to design safer, more effective work.'],['Workaround','A way staff adapt to get work done when a process does not fit reality. It signals a design problem.'],['Forcing function','A design feature that makes it hard or impossible to proceed unless a step is done correctly.'],['Cognitive load','The amount of mental effort demanded at a point in time. High load increases the chance of slips and omissions.']],
 sc:{s:'In a fictional team, a task is often missed after interruptions. Reminders at meetings have not helped.',
  a:{q:'What do you suggest?',o:[['Send a stronger reminder and ask everyone to concentrate.',0,'Reminders are a weak response to a recurring design problem.'],['Map the task with the people who do it and test a visible task cue with a named owner at the fragile step.',2,'You study the real work and test a support at the point of work.'],['Find the person who misses it most.',1,'Focusing on individuals misses the conditions that make misses likely.']]},
  b:{q:'The cue helps, but some staff skip it when busy. What now?',up:'The team agrees to look at why.',dn:'The cue creates extra work.',o:[['Ask staff why, test a simpler cue and check effects on errors, time and workarounds.',2,'You treat workarounds as information and test again.'],['Tell staff to follow the cue.',0,'It ignores the cause and may drive workarounds underground.'],['Remove the cue.',1,'Possibly right if it adds burden, but you lose a chance to improve it.']]},
  end:['The design problem was untouched, so the miss is likely to recur.','Partly effective. Keep studying how the work really happens.','A strong path: you observed the work, tested a support and checked for new burden.']},
 spot:{t:'Mark the lines that respond weakly to a recurring problem.',l:[['“Everyone needs to remember better.”',1,'Relies on memory. A weak response.'],['“Let’s watch how the task is really done.”',0,'Starts from real work.'],['“We’ll send a memo reminding staff.”',1,'A reminder, the weakest kind of action.'],['“A visible cue at the step, with a named owner.”',0,'A stronger action at the point of work.'],['“We’ll check whether the cue slows people or creates workarounds.”',0,'Looks for new burdens.']]},
 myths:[['Errors are caused by carelessness.','They arise from conditions such as interruptions, memory load and unclear cues.'],['More training fixes recurring errors.','Training helps but is a weaker response than redesign.'],['Workarounds are rule-breaking.','They often show where a process does not fit the work.'],['A checklist solves it.','A checklist helps if it fits the task, is used at the right moment and is tested for burden.']],
 lad:{t:'How strong is the fix?',h:'Slide from a weak response to a strong one.',s:[['Blame','Find who made the mistake.','Does not change the conditions.'],['Remind','Send a reminder.','Relies on memory, which is limited.'],['Train','Run a refresher.','Helpful but still relies on people to remember.'],['Support','A cue or checklist at the point of work.','Intermediate. Fits the moment of need.'],['Redesign','Change the task or tool so the right action is easy and the wrong one hard.','Strongest. Tested and monitored for new burden.']]},
 chk:['I observed the task as it happens.','I asked the people who do the work where it is difficult.','I looked at tools, environment, handoffs and interruptions.','I preferred redesign over reminders.','I tested a limited change with approval.','I checked effects on errors, time and workarounds.','I included people who might face new barriers.'],
 good:['Fixes change the work, not just the people.','Workarounds are treated as information.','New supports are tested for burden.'],
 rel:['improvement','just-culture','safety'],pr:['Which recurring interruption deserves a system change?','What workaround do you rely on, and what does it tell you?','What cue would help at your most fragile step?']},

'med-transitions':{lv:'Core',
 why:['Medicines move between settings and teams more often than most information. Each move risks an omission, a duplication or a change that is not explained. The evidence panel summarises a multicentre implementation in which discrepancies per patient fell, though a discrepancy is not the same as harm and no single tool effect is claimed.','The safest stance is to treat a difference between sources as a question to resolve with the responsible clinician or pharmacist, not an instruction to guess. This lesson is about communication and process, not about starting, stopping or changing any medicine.'],
 fw:{n:'Compare, clarify, communicate',i:'The reconciliation habit in three steps. Select a step.',p:[['1','Compare','Gather the best available medication history from more than one source, including the person, then compare it with the current plan.'],['2','Clarify','Record each unexplained difference and route it to the responsible prescriber or pharmacist. Do not decide by inference.'],['3','Communicate','Make sure the agreed resolution reaches the authorised record, the receiving team and the person, and say who owns anything unresolved.']]},
 viz:{k:'timeline',t:'A medicine’s journey',c:'Each handover is a chance for a difference to appear. Each deserves a check.',s:[['Home','The person’s account and what they actually take.'],['Admission','History taken and compared with the plan.'],['Transfer','List moves between teams or units.'],['Discharge','Plan explained to the person and sent to the next carer.'],['Community','Follow-up checks the list with the person.']]},
 terms:[['Best possible medication history','A history built from more than one source, including the person, that gives the most complete picture of what they take.'],['Unintentional discrepancy','A difference between lists that has no documented reason, which needs to be clarified.'],['Intentional discrepancy','A difference that was a deliberate, documented clinical decision.'],['Omission','A medicine that appears on one list but not another without explanation.']],
 sc:{s:'Two fictional medication lists disagree about whether one medicine is current. One is from yesterday and one is from last week. The patient is unsure.',
  a:{q:'What do you do?',o:[['Assume the newest list is right.',0,'Recency alone does not establish correctness.'],['Record both accounts, route the question to the responsible clinician or pharmacist through the approved process and involve the patient.',2,'You name the discrepancy, route it to the person with authority and use the patient as a source.'],['Stop the medicine until someone confirms.',1,'You must not decide to start, stop or change a medicine by inference. Clarify first.']]},
  b:{q:'The pharmacist confirms the plan. How do you communicate it?',up:'The answer is clear.',dn:'The answer is still pending when the shift ends.',o:[['Ensure the resolution is in the authorised record, tell the receiving team and the patient, and name an owner for anything unresolved.',2,'Verified information and ownership reach everyone.'],['Update the record and leave it there.',1,'The record is necessary but the team and patient also need to know.'],['Tell the patient and move on.',0,'The record and team remain out of step.']]},
  end:['The discrepancy was resolved by assumption or left open, which is unsafe.','Partly effective. Close the loop with the record, team and person.','A strong path: clarified through the right person and communicated to all.']},
 spot:{t:'Mark the lines that settle a discrepancy by guessing.',l:[['“The newest list must be right.”',1,'Recency is not proof.'],['“These accounts conflict. I’ll ask the responsible pharmacist to verify.”',0,'Routes to the right person.'],['“I’ll stop it just in case.”',1,'Starting or stopping by inference is not your decision.'],['“I’ve recorded the outcome and told the next team.”',0,'Closes the loop.'],['“The patient said they stopped it, so it’s not current.”',1,'The patient’s account is valuable but needs verification with the clinician.']]},
 myths:[['The latest list is the correct one.','Lists can be copied forward or incomplete. Verify.'],['The patient is the final authority.','The patient’s account is essential, but verification involves the responsible clinician.'],['A discrepancy is an error.','It may be intentional and documented. Clarify before concluding.'],['I can fix it by choosing the safest option.','Starting, stopping or changing a medicine is for the responsible prescriber.']],
 lad:{t:'How far has the discrepancy travelled?',h:'Slide from unnoticed to resolved.',s:[['Unnoticed','Nobody compares the lists.','The difference moves to the next team.'],['Noticed','You see it but say nothing.','Awareness without action.'],['Recorded','You write it down.','Visible but without an owner.'],['Routed','Asked of the responsible clinician or pharmacist.','An owner with authority.'],['Resolved','Verified answer in the record, shared with the team and the person.','The next team starts from a verified plan.']]},
 chk:['I compared at least two sources, including the person.','I identified omissions, duplications and unexplained changes.','I did not start, stop or change a medicine by inference.','I routed each question to the responsible clinician or pharmacist.','I recorded the uncertainty clearly.','I confirmed the resolution reached the record, team and person.','I named an owner for unresolved items.'],
 good:['Every discrepancy has an owner and a recorded resolution.','The person understands the plan.','The next team starts from a verified list.'],
 rel:['safety','sbar','documentation'],pr:['Who owns unresolved medication questions at your handover?','Which source do you trust most, and why?','How do you involve the person in checking their own list?']},

deterioration:{lv:'Core',
 why:['People rarely deteriorate without warning. Change from a person’s usual state, a trend across observations or a family member’s worry often appears before a single abnormal number does. The challenge is to communicate significant concern promptly, without waiting for certainty.','Early-warning scores and track-and-trigger tools support judgement and standardise escalation, but they do not replace it. A clinician’s concern is itself a reason to escalate under many local policies. SBAR can help you be clear, but must never delay urgent action.'],
 fw:{n:'Notice, describe, request, confirm',i:'A simple escalation sequence. Select a step.',p:[['1','Notice','Spot a change from baseline, a trend or an expressed concern. Do not let an earlier reassuring label override current observations.'],['2','Describe','State what you see, how it differs from before and your concern. Facts first.'],['3','Request','Ask for the response you need and by when, through the local route. For urgent concern, use the emergency or escalation pathway immediately.'],['4','Confirm','Confirm who has accepted responsibility, what will happen and what to do if help does not arrive. Re-escalate if concern remains.']]},
 viz:{k:'flow',t:'Concern to action',c:'The loop is not closed until a named person has taken responsibility.',s:[['Notice','Change from baseline, trend or worry.'],['Describe','Observations, change and concern.'],['Escalate','Local route. Immediately if urgent.'],['Confirm','Who, what, by when.'],['Re-escalate','If the concern remains unresolved.']]},
 terms:[['Track and trigger','A system of recording observations and using agreed triggers to prompt escalation and response.'],['Early-warning score','A score derived from routine observations that helps identify people at risk of worsening. It supports, but does not replace, clinical judgement.'],['Baseline','A person’s usual state, against which change is judged.'],['Re-escalation','Raising the concern again, or higher, through local policy when the response has not resolved it.']],
 sc:{s:'In a fictional ward, a note from earlier says a patient is stable. A new observation worries you and the patient says “I just don’t feel right.”',
  a:{q:'What do you do?',o:[['The earlier note was reassuring, so wait to see.',0,'A previous reassuring label should not override a current change or the person’s concern.'],['State the change and your concern clearly and activate the appropriate local response now.',2,'You act on current information and use the local route immediately.'],['Finish the rest of your tasks and mention it at the next handover.',1,'Delay risks deterioration progressing before anyone with authority knows.']]},
  b:{q:'You escalated, but nobody has acknowledged. What next?',up:'A colleague arrives.',dn:'There is no response after a few minutes.',o:[['Re-escalate through the local route, restating the concern and what you need, and confirm who is taking responsibility.',2,'Persistence through the proper route closes the loop.'],['Wait. They are probably busy.',0,'Silence can leave an unwell person without help.'],['Ask a friendly colleague informally.',1,'Informal help may be useful but does not replace the escalation route.']]},
  end:['The concern was delayed or lost, which can allow harm to progress.','Partly effective. Escalate through the formal route and keep going until someone owns the response.','A strong path: prompt, clear escalation with persistence and confirmation.']},
 spot:{t:'Mark the lines that delay escalation.',l:[['“The earlier note said stable, so I’ll wait.”',1,'An old label should not outweigh new information.'],['“There’s a new change and I’m concerned. I’m activating the local response.”',0,'Clear and immediate.'],['“I’ll mention it at the end of my shift.”',1,'A delay for something that may be urgent.'],['“Who is taking responsibility, and what happens if they can’t come?”',0,'Confirms ownership and contingency.'],['“I’m not sure enough to call anyone.”',1,'Significant concern should be communicated before certainty arrives.']]},
 myths:[['I must be sure before I escalate.','Communicate significant concern before certainty. Early escalation is appropriate.'],['A normal score means no concern.','Scores support judgement. A worry or a change from baseline can justify escalation.'],['SBAR must be perfect first.','Use the emergency route immediately when urgent. Structure helps but must not delay.'],['If I told someone, it is handled.','Confirm who has accepted responsibility.']],
 lad:{t:'How clearly is concern communicated?',h:'Slide from a vague worry to an escalation that gets action.',s:[['Unsaid','You are uneasy but say nothing.','Nobody else knows.'],['Mentioned','“She seems a bit off.”','Vague and easily dismissed.'],['Described','“Her breathing is different from this morning.”','Specific observation.'],['Escalated','Description plus concern and a request via the local route.','Action requested.'],['Confirmed','Escalated, accepted by a named person, with a plan if help does not arrive.','The loop is closed.']]},
 chk:['I described the change from baseline and the trend.','I gave weight to the person’s or family’s concern.','I used the local emergency or escalation route immediately for urgent concern.','I stated my concern and the response I need.','I confirmed who accepted responsibility.','I agreed a contingency if help did not arrive.','I re-escalated if concern remained.','I documented according to local policy.'],
 good:['Concern leads to action without waiting for certainty.','Every escalation ends with a named owner.','Teams welcome early calls.'],
 rel:['sbar','speakup','reasoning'],pr:['How do you confirm that a concern has an action owner?','What stops you escalating early?','Where can you find your local escalation pathway?']},

'data-stewardship':{lv:'Core',
 why:['Information is central to care and a risk if it goes to the wrong place. Convenience can quietly widen access: a screenshot in a group chat, a note pasted into a public tool, an email to the wrong address. Each seems small but can breach confidentiality and trust.','Stewardship means handling information with a defined purpose, an authorised audience and the minimum necessary detail. Local information-governance policy sets the detail. A useful principle is that removing a name does not make information anonymous: dates, locations, rare events and combinations can identify someone.'],
 fw:{n:'Purpose, authority, minimum, destination',i:'Four questions before sharing. Select a question.',p:[['1','Purpose','Why is this information needed, and is it for care or another approved purpose?'],['2','Authority','Am I allowed to access and share it, and is the recipient authorised?'],['3','Minimum','Have I shared only what is necessary? Could details in combination identify someone?'],['4','Destination','Is the system or channel approved, and have I checked the recipient?']]},
 viz:{k:'matrix',t:'Identifiers: obvious and hidden',c:'Removing a name is rarely enough.',s:[['Direct','Name, identification numbers, contact details, photographs.','Obvious'],['Indirect','Dates, locations, workplace, rare conditions or events, unusual circumstances.','Often missed'],['In combination','Several indirect details together can point to one person.','Jigsaw']]},
 terms:[['Personal data','Information that relates to an identified or identifiable person. It includes more than names.'],['Data minimisation','Collecting, using and sharing only what is necessary for a defined purpose.'],['Information governance','The rules and processes that protect how information is held, shared and used.'],['Data incident','Information sent or accessed in error or without authority, which should be reported promptly through local process.']],
 sc:{s:'A fictional colleague proposes pasting a note into a free public tool to tidy it. The note has no name but includes a rare event and a location.',
  a:{q:'What do you say?',o:[['“No name, so it’s anonymous. Go ahead.”',0,'A rare event and a location may identify someone. Removing a name is not enough.'],['“Details like these can identify someone. Let’s ask the information-governance contact for an approved route.”',2,'You recognise indirect identifiers and use the proper route.'],['“Share it, but only once.”',1,'Frequency is not the issue. Whether it can identify someone and the tool is approved are the issues.']]},
  b:{q:'Later you realise a message went to the wrong recipient. What now?',up:'You paused and took advice.',dn:'You are worried about the consequences.',o:[['Follow the local incident process promptly and preserve the facts.',2,'Prompt reporting lets the organisation respond and limit harm.'],['Delete it and say nothing.',0,'Hiding an incident prevents a response and learning.'],['Ask the recipient to delete it and consider it fixed.',1,'Useful but does not replace reporting through the proper process.']]},
  end:['The note or message went somewhere it should not, with a risk to confidentiality.','Partly effective. Combine good judgement with prompt reporting.','A strong path: you protected information and reported an incident promptly.']},
 spot:{t:'Mark the lines that put information at risk.',l:[['“I removed the name, so it’s fine.”',1,'Other details can identify a person.'],['“Let’s check the approved tool first.”',0,'Uses an approved channel.'],['“It’s easier to send it through my personal messaging app.”',1,'Convenience is not authority.'],['“I only included what the colleague needs.”',0,'Minimum necessary.'],['“I reported the misdirected email straight away.”',0,'Prompt reporting.']]},
 myths:[['No name means anonymous.','Combinations of details can identify someone.'],['If it is faster it is fine.','Convenience does not create authority.'],['A small breach does not matter.','Report it. Small incidents show where the system is weak.'],['I can use any tool if I am careful.','Only approved tools should handle confidential information.']],
 lad:{t:'How much is shared?',h:'Slide from everything to the minimum.',s:[['Everything','Paste the full record.','Maximum risk.'],['Remove the name','Name removed, rest left.','Still identifiable.'],['Remove obvious details','Also remove dates and locations.','Better but combinations can remain.'],['Minimum necessary','Only what the recipient needs.','Reduces risk.'],['Minimum and approved','Minimum detail, authorised recipient, approved channel.','Good stewardship.']]},
 chk:['I know the purpose and that it is approved.','I confirmed the recipient is authorised.','I shared the minimum necessary.','I considered indirect identifiers and combinations.','I used an approved channel.','I checked the recipient before sending.','I reported any error promptly.','I know my information-governance contact.'],
 good:['Information goes only where it should.','Incidents are reported quickly.','People know who to ask.'],
 rel:['ai','documentation','accountability'],pr:['What digital convenience needs a clearer boundary in your work?','What would you do if you sent something to the wrong person?','Who is your information-governance contact?']},

'teachback-skill':{lv:'Foundation',
 why:['Teach-back is a simple loop that reveals whether an explanation has landed. Its value depends on how it is framed: as a check on the explainer, not a test of the person. A systematic review in the evidence panel found that most included studies reported benefit on at least one outcome, though methods and outcomes varied widely and several studies were weak.','It works best when combined with plain language, small chunks and a willingness to try again in a different way. It is not a script to recite but a way of staying curious about what the other person understood.'],
 fw:{n:'The teach-back loop',i:'A common five-step description of the loop. Select a step.',p:[['1','Explain','Share one manageable idea in plain language, then pause.'],['2','Ask','Invite the person to explain it in their own words, framed as a check on you.'],['3','Listen','Notice what is missing or different. Resist correcting too quickly.'],['4','Repair','Thank the person, take responsibility and explain the gap differently.'],['5','Re-check','Ask again. Repeat until the next step is clear.']]},
 viz:{k:'cycle',t:'A loop, not a question',c:'Repeat until the person can describe what they will do.',s:[['Explain','One idea, plain words.'],['Ask','“How would you describe it?”'],['Listen','Notice gaps without judgement.'],['Repair','Try another way.'],['Re-check','Ask again.']]},
 terms:[['Teach-back','A method of confirming understanding by asking a person to explain information in their own words.'],['Repair','Re-explaining a missed part in a different way, such as new words, a picture or a demonstration.'],['Plain language','Everyday words and short sentences that the person can use straight away.'],['Show-me','A variant of teach-back in which the person demonstrates a task, such as using a device.']],
 sc:{s:'A fictional patient explains the follow-up plan differently from what you intended.',
  a:{q:'What do you say?',o:[['“You weren’t listening.”',0,'Blame shuts down honesty and does not repair the gap.'],['“Thank you. I need to explain that part more clearly. Let’s try it another way.”',2,'You took responsibility, repaired and invited another try.'],['“No, that’s wrong. Listen again.”',1,'Correcting without changing the explanation often repeats the same problem.']]},
  b:{q:'After a second explanation they get most of it right.',up:'They have explained it well.',dn:'They still miss a step.',o:[['Ask them to say it again, confirm the action, and tell them where to get help if circumstances change.',2,'Re-check and a safety net finish the loop.'],['Say “Great” and finish.',1,'Positive, but you have not confirmed the missed part.'],['Say “Never mind, I’ll tell your family.”',0,'It bypasses the person without checking.']]},
  end:['The gap remained or the person felt blamed.','Partly effective. Keep the check framed on you and repeat.','A strong path: responsible framing, a repair and a re-check.']},
 spot:{t:'Mark the lines that turn teach-back into a test.',l:[['“Do you understand? Yes or no?”',1,'Closed and easy to answer politely.'],['“To check I explained it clearly, how would you describe the next step?”',0,'Open and framed on the explainer.'],['“Why didn’t you listen?”',1,'Blames the person.'],['“Thank you. Let me explain that part differently.”',0,'Takes responsibility.'],['“Can you show me how you would use it?”',0,'A show-me check.']]},
 myths:[['Teach-back tests the patient.','It tests your explanation.'],['Asking “do you understand?” is enough.','Many people say yes. Ask for the plan in their own words.'],['It takes too long.','A short check often saves time later.'],['It is only for patients.','It also helps in team conversations and handovers.']],
 lad:{t:'How well framed is the check?',h:'Slide from blame to a well-framed check.',s:[['Blame','“Why did you forget?”','Shuts people down.'],['Closed','“Do you understand?”','Invites a polite yes.'],['Open','“What will you do next?”','Reveals understanding.'],['Framed on you','“To check I explained it clearly, what will you do next?”','Protects dignity.'],['Looped','Framed, repaired and re-checked.','Confirms understanding.']]},
 chk:['I shared one manageable idea.','I used plain language and checked language and format needs.','I asked in a way that checks my explanation.','I listened for gaps without correcting too fast.','I thanked the person and re-explained differently.','I re-checked until the next step was clear.','I confirmed the action and where to get help.'],
 good:['The person can describe the next step.','You can name what you changed in your explanation.','The person feels respected, not tested.'],
 rel:['communication','health-literacy','feedback'],pr:['Which phrase will you use when the first explanation does not land?','What do you do when someone says “I understand” but does not?','How could you teach this to a colleague?']},

conflict:{lv:'Core',
 why:['Disagreement is normal in teams that care about getting things right. It becomes costly when it turns into accusation, avoidance or a contest about status. The goal is to move from personal friction to an observable concern and a shared next step.','The DESC script from TeamSTEPPS offers a structure: Describe the specific situation, Express your concern, Suggest alternatives and state the Consequences. Separating what happened from your interpretation of motives keeps the conversation about the work. Conduct that is unacceptable or unsafe should go through your local route rather than being managed informally.'],
 fw:{n:'DESC',i:'A TeamSTEPPS script for raising a concern. Select a step.',p:[['D','Describe','Describe the specific event or behaviour, factually. “The task had no named owner at handover.”'],['E','Express','Say how it affects you or the work. “I’m concerned it could be missed.”'],['S','Suggest','Offer one or more alternatives and invite theirs. “Could we name an owner before we finish?”'],['C','Consequences','State the likely outcome and seek agreement. “That way the next shift knows who is acting.”']]},
 viz:{k:'compare',t:'Accusation or observation',c:'The same concern, framed to keep the conversation on the work.',h:['Accusation','Observation and request'],s:[['“You never take responsibility.”','“This task has no named owner. Can we agree who will act?”'],['“You always ignore me.”','“When I raised the concern, I didn’t hear a response. Can we check it together?”'],['“That’s just lazy.”','“The handover was not finished. What got in the way?”']]},
 terms:[['DESC script','A structured way to raise a concern: Describe, Express, Suggest, state Consequences.'],['Interests and positions','A position is what someone says they want. An interest is why they want it. Exploring interests often reveals shared goals.'],['Impact versus intent','The effect of an action on others versus what the person meant. Discussing impact avoids arguing about motives.'],['Escalation route','The local process for unresolved concerns or unacceptable conduct.']],
 sc:{s:'In a fictional handover, a task has no named owner. You and a colleague have disagreed about this before and tension is rising.',
  a:{q:'How do you open?',o:[['“You never take responsibility for anything.”',0,'A character label that invites defence and does not name the concern.'],['“This task has no named owner. Can we agree who will act and by when?”',2,'Observable, specific and forward-looking.'],['Say nothing and do it yourself.',1,'It may solve today’s problem but leaves the pattern in place and builds resentment.']]},
  b:{q:'They respond: “I thought you were doing it.”',up:'The conversation is opening up.',dn:'They become defensive.',o:[['Ask what each of you expected, name the shared aim and agree an owner and a follow-up.',2,'You explore constraints, restate the shared purpose and agree a specific action.'],['Argue about who said what earlier.',0,'It moves to blame and away from the task.'],['Let it go and hope it improves.',1,'Without agreement the same gap can recur.']]},
  end:['The tension remained and the owner gap is likely to recur.','Partly effective. Keep the focus on the shared aim and a specific request.','A strong path: observable concern, shared purpose and a clear agreement.']},
 spot:{t:'Mark the lines that make a disagreement harder to resolve.',l:[['“You always do this.”',1,'A generalisation that invites defence.'],['“The task had no owner. Can we agree one?”',0,'Specific and actionable.'],['“Everyone knows it’s your fault.”',1,'Blame and a claim about others.'],['“What got in the way for you?”',0,'Invites their view.'],['“Let’s agree who acts and when we’ll check.”',0,'Specific agreement and follow-up.']]},
 myths:[['Good teams do not disagree.','Healthy teams disagree about the work and resolve it respectfully.'],['It is kinder to avoid conflict.','Avoidance can leave risks in place and build resentment.'],['I need to know their motives.','Describe what happened and its effect. Motives are often unknowable.'],['Everything can be solved informally.','Unsafe or unacceptable conduct needs the local route.']],
 lad:{t:'How actionable is the disagreement?',h:'Slide from personal friction to an agreed action.',s:[['Accuse','“You never…”','Triggers defence.'],['Complain','Complaining to others.','Does not reach the person.'],['Describe','Names the specific event.','Shared facts.'],['Request','Describes and asks for a specific change.','Clear action.'],['Agree','Request, shared purpose, owner and follow-up.','Resolves and prevents recurrence.']]},
 chk:['I described a specific observable event.','I separated what happened from assumed motives.','I named a shared purpose.','I asked for their perspective.','I made a specific request.','We agreed an owner and a follow-up.','I used the local route for unresolved or unacceptable conduct.'],
 good:['Disagreements end with a clearer next action.','People feel heard and respected.','Serious issues reach the right route.'],
 rel:['speakup','feedback','accountability'],pr:['Which assumption about a colleague could you replace with a question?','When did a disagreement improve a decision?','What would make you raise a concern earlier?']},
documentation:{lv:'Foundation',
 why:['A record is a message to someone who was not there: the next colleague, a team on another shift or a person reviewing care later. Notes such as “team aware, follow up later” feel complete to the writer but leave the reader unable to act, because they omit what was done, who owns the next step and when.','Good notes separate observation from interpretation, record decisions and open questions and are accurate, timely and attributable under local policy. Correct errors through the approved amendment process and never rely on a note to replace urgent communication. This lesson uses a simple memory aid, Facts, Plan, Owner, Time, which is a teaching device rather than a formal standard.'],
 fw:{n:'Facts, Plan, Owner, Time',i:'A memory aid used in this lesson (not a formal standard). Select a part.',p:[['F','Facts','What you observed, what the person told you and what you did, kept separate from interpretation. Include the time or source where appropriate.'],['P','Plan','What was agreed, including any unresolved questions.'],['O','Owner','Who is responsible for each next action.'],['T','Time','When it will happen or be reviewed, and what to do if it does not.']]},
 viz:{k:'compare',t:'A note the next person can use',c:'Each pair describes the same fictional situation.',h:['Hard to act on','Easy to act on'],s:[['“Team aware, follow up later.”','“Dr A (fictional) informed at 14:10. Agreed review by 16:00. Ward nurse owns the call if not seen.”'],['“Patient seems better.”','“Patient reports less pain (their words). Pain score recorded at 14:00.”'],['“Family concerned.”','“Daughter says he is more confused than yesterday. Concern passed to nurse in charge at 15:20.”']]},
 terms:[['Contemporaneous record','A note made at the time of events, or as soon as practicable afterwards, which makes it more reliable.'],['Attributable','Clear who wrote or amended an entry and when.'],['Observation versus interpretation','An observation is what you saw or heard. An interpretation is what you think it means. Keep them distinct.'],['Amendment','A change to a record made through the approved process so the original remains visible.']],
 sc:{s:'A fictional note reads “Team aware, follow up later.” You are about to write something similar after a concerning conversation.',
  a:{q:'What do you record?',o:[['“Team aware.” That covers it.',0,'It does not say who, when or what was agreed.'],['The agreed action, who owns it, the timing, and any outstanding question, according to local requirements.',2,'The next person can act without having to ask.'],['A long paragraph describing everything that happened.',1,'More words are not more clarity. The next action may still be unclear.']]},
  b:{q:'You notice a mistake in your earlier entry. What do you do?',up:'Your note is clear.',dn:'Your note was vague and you realise it.',o:[['Correct it using the approved amendment process so the original is still visible.',2,'Records should be corrected transparently.'],['Delete the original and rewrite it.',0,'Erasing an entry undermines trust in the record.'],['Leave it, since nobody will notice.',1,'Leaving an error can mislead the next reader.']]},
  end:['The record did not help the next person act and may have misled.','Partly effective. Keep notes specific and correct errors transparently.','A strong path: a specific, actionable record and transparent correction.']},
 spot:{t:'Mark the lines that make a record harder to use.',l:[['“Team aware.”',1,'Who, when and what was agreed?'],['“Dr A informed at 14:10. Review agreed by 16:00. Nurse in charge owns the call if not seen.”',0,'Facts, owner, timing and a contingency.'],['“Patient seems fine.”',1,'Interpretation without observation.'],['“Patient reports less pain. Score 3 at 14:00.”',0,'Observation with source and time.'],['“Please follow up later.”',1,'No owner or timing.']]},
 myths:[['A short note is a good note.','A note must be short and specific: facts, plan, owner and time.'],['Documentation replaces telling someone.','Urgent concerns need direct communication. The record supports it.'],['I can tidy an old entry.','Use the approved amendment process so the original stays visible.'],['Reassuring words make a note kinder.','Vague reassurance can hide a concern that still needs review.']],
 lad:{t:'How actionable is the note?',h:'Slide from vague to actionable.',s:[['Vague','“Follow up later.”','Nobody knows what to do.'],['Told','“Team aware.”','Says someone knows but not what happens.'],['Specific','“Dr A informed at 14:10.”','Who and when.'],['Planned','Plus the agreed action.','Clear plan.'],['Owned','Plus the owner, timing and a contingency.','The next person can act.']]},
 chk:['I recorded observations separately from interpretation.','I noted the time or source where appropriate.','I recorded the agreed action.','I named who owns each action and when.','I recorded unresolved questions.','Another authorised colleague could tell what to do next.','I corrected errors through the approved process.','I did not rely on the note to replace urgent communication.'],
 good:['A colleague can act from the note without asking.','Corrections are transparent.','Urgent matters are communicated directly.'],
 rel:['sbar','accountability','data-stewardship'],pr:['What does your next colleague need from a note that you sometimes omit?','Which note have you read that you could not act on?','What is your local rule for amending an entry?']},

'risk-dialogue':{lv:'Advanced',calc:1,
 why:['Having the numbers is not the same as having a conversation. When a person is considering a choice, the same data can be framed in ways that push them towards one option. A fair conversation uses the same denominator, time horizon and outcome for benefits and harms, and invites the person to say what the numbers mean to them.','Visual displays such as icon arrays can support understanding but do not replace an accessible explanation. The evidence panel summarises a Cochrane review in which decision aids improved knowledge. The goal is balance, not persuasion: numbers support a decision, but they do not make it for the person.'],
 fw:{n:'Making a fair comparison',i:'Four checks for a balanced numbers conversation. Select a check.',p:[['1','Same scale','Use the same denominator, time period and outcome for benefits and harms, such as “out of 100 people over five years”.'],['2','Baseline first','Start with the starting risk, then the change, before any percentage.'],['3','Check meaning','Ask the person how they understand the numbers. Use a visual if it helps.'],['4','Connect to values','Explore preferences and practical burden. Involve the responsible clinician and arrange a way to revisit the decision.']]},
 viz:{k:'compare',t:'Fair or loaded',c:'A fictional option reduces an outcome from 10 in 100 to 8 in 100.',h:['Loaded','Balanced'],s:[['“It cuts the risk by 20%.”','“About 2 fewer people in 100 over the same period.”'],['Benefits shown per 100, harms as a percentage','Benefits and harms both shown as people out of 100'],['“Most people choose this.”','“Here are the trade-offs. What matters most to you?”']]},
 terms:[['Natural frequencies','Expressing risk as counts out of a number of people, such as “8 in 100”, which many people find easier to interpret than percentages.'],['Icon array','A grid of figures, with some highlighted, that shows how many people out of a group are affected.'],['Framing','The way information is presented, such as gains versus losses or relative versus absolute figures, which can influence choices.'],['Time horizon','The period over which a risk or benefit is described, such as one year or ten years.']],
 sc:{s:'A fictional option reduces an outcome from 10 in 100 to 8 in 100 over five years. The person asks: “Is it worth it?”',
  a:{q:'How do you explain it?',o:[['“It cuts the risk by 20%, so it’s clearly best.”',0,'A relative figure alone exaggerates benefit and tells the person what to choose.'],['“In this example that is 2 fewer people in 100 over five years. Let’s also look at the downsides and what matters to you.”',2,'Absolute difference, time frame, harms and values.'],['“It’s a small difference, so probably not worth it.”',1,'Your own judgement may differ from theirs. Let them weigh it.']]},
  b:{q:'They say the numbers do not feel real. What next?',up:'They want to know about downsides.',dn:'They look overwhelmed.',o:[['Offer an icon array, ask them to describe their understanding, then explore what matters to them.',2,'A visual plus a check supports a person’s own interpretation.'],['Give more statistics until they stop asking.',0,'More numbers may increase confusion.'],['Tell them to decide with their family.',1,'Family discussion may help, but it is not a substitute for a clear explanation.']]},
  end:['The numbers were used to steer rather than inform.','Partly effective. Keep the scale consistent and invite their meaning.','A strong path: fair numbers, a visual and the person’s priorities.']},
 spot:{t:'Mark the lines that make the numbers unfair.',l:[['“Reduces risk by 20%.”',1,'Relative only, and no baseline.'],['“From 10 in 100 to 8 in 100 over five years.”',0,'Absolute and comparable.'],['“The side effect affects 2% of people.”',1,'If benefits use “in 100”, harms should too, with the same time frame.'],['“What do these numbers mean to you?”',0,'Invites the person’s interpretation.'],['“We can revisit this if things change.”',0,'Keeps the decision open.']]},
 myths:[['If the numbers are accurate, the choice is clear.','Numbers inform. Values decide.'],['Percentages are the clearest way to show risk.','Many people find “out of 100” easier to interpret.'],['A graph replaces an explanation.','Visuals support but do not replace an accessible explanation.'],['I should recommend the best option.','You can offer a view, but check what matters to the person first.']],
 lad:{t:'How balanced is the presentation?',h:'Slide from a persuasive framing to a balanced one.',s:[['Persuade','“Cuts risk by 20%.”','One-sided.'],['Selective','Shows benefits, not harms.','Incomplete.'],['Absolute','“2 fewer in 100.”','Real size.'],['Comparable','Benefits and harms on the same scale.','Fair comparison.'],['Meaningful','Comparable plus the person’s meaning and priorities.','Supports the person’s decision.']]},
 chk:['I used the same denominator, time horizon and outcome for benefits and harms.','I gave the baseline and avoided a lone relative percentage.','I invited the person to describe what the numbers mean.','I offered a visual if it would help.','I explored preferences and practical burden.','I involved the responsible clinician.','I arranged a way to revisit the decision.'],
 good:['The person can explain the trade-offs in their own words.','Benefits and harms are on the same scale.','The decision reflects their priorities.'],
 rel:['risk-evidence','shared','health-literacy'],pr:['What matters to this person beyond the outcome percentage?','How do you check that a number has been understood?','When has framing changed your own choice?']},

feedback:{lv:'Core',
 why:['Feedback works when it gives a person something specific they can try. Labels such as “careless” or “bad at handovers” describe character, not behaviour, and are hard to act on. The evidence panel summarises a Cochrane review that found audit and feedback improved professional practice on average, with effects varying widely, which fits what most people see: the manner and the next step matter.','A useful pattern is Situation, Behaviour, Impact (SBI), followed by a question: how did you see it? Then agree a small next experiment and when to review it. Urgent safety concerns should be raised immediately, not saved for a feedback session.'],
 fw:{n:'Situation, Behaviour, Impact, Invite',i:'SBI with an invitation to respond. Select a part.',p:[['S','Situation','Name when and where. “In yesterday’s handover…”'],['B','Behaviour','Describe what you saw or heard, not a judgement. “…the owner for the pending task wasn’t named.”'],['I','Impact','Say the effect on the work or people. “…so the next shift didn’t know who was acting.”'],['?','Invite','Ask how they saw it, then agree a next step. “How did that moment look to you? Could we practise a closing request?”']]},
 viz:{k:'flow',t:'A feedback conversation',c:'Short, specific and two-way.',s:[['Choose the moment','Respectful, private, purposeful. Urgent safety issues now.'],['Describe','Situation, behaviour, impact.'],['Ask','How did you see it?'],['Agree','One small thing to try.'],['Review','When will you look again?']]},
 terms:[['SBI','Situation, Behaviour, Impact: a way to describe an observation without judging the person.'],['Ask-tell-ask','Ask for the learner’s view, share your observation, then ask what they will do with it.'],['Formative feedback','Feedback given to help someone improve, as distinct from an assessment of their performance.'],['Psychological safety','A shared belief that it is safe to take interpersonal risks, such as asking for or receiving feedback.']],
 sc:{s:'In a fictional rehearsal, a colleague omitted ownership of a pending task at handover. You have the chance to give feedback afterwards.',
  a:{q:'How do you begin?',o:[['“You’re bad at handovers.”',0,'A label about the person. It is hard to act on and invites defence.'],['“In that handover the task owner wasn’t named. How did that moment look to you?”',2,'A specific observation and an invitation to respond.'],['“Next time, try to be better.”',1,'Well meant but vague.']]},
  b:{q:'They say they were rushed. What do you do?',up:'They are open to talking.',dn:'They seem defensive.',o:[['Acknowledge the pressure, agree one small behaviour to try, the support needed and when to review.',2,'A manageable next step with support and a review.'],['Tell them everyone is busy.',0,'Dismisses a real constraint.'],['Drop the topic to keep things comfortable.',1,'Avoids conflict but misses a learning opportunity.']]},
  end:['The feedback did not give the person something to try.','Partly effective. Make it more specific and agree a next step.','A strong path: specific, two-way feedback with an agreed experiment.']},
 spot:{t:'Mark the lines that make feedback harder to use.',l:[['“You’re careless.”',1,'A label, not a behaviour.'],['“The owner wasn’t named in the handover.”',0,'Observable.'],['“Try to be better.”',1,'No specific action.'],['“How did you see that moment?”',0,'Invites their view.'],['“Let’s practise a closing request and review next week.”',0,'A next step and a review.']]},
 myths:[['Feedback is criticism.','Good feedback helps someone try something different.'],['Positive feedback is not useful.','Specific positive feedback tells someone what to keep doing.'],['I should save it for the formal review.','Timely feedback is more useful. Urgent safety concerns need immediate action.'],['A sandwich always works.','Padding can hide the message. Be kind and clear.']],
 lad:{t:'How useful is the feedback?',h:'Slide from a label to an experiment.',s:[['Label','“You’re careless.”','Hard to act on.'],['General','“Be more careful.”','Vague.'],['Specific','“The owner wasn’t named.”','Observable.'],['With impact','Plus the effect on the team.','Shows why it matters.'],['Experiment','Specific, with impact, their view and a next step to try.','Actionable and two-way.']]},
 chk:['I chose a respectful moment and purpose.','I raised urgent safety concerns immediately.','I described an observable behaviour and its effect.','I avoided labels about character.','I asked how they saw it.','We agreed a small next step and support.','We agreed when to review.'],
 good:['The person knows what to try next.','The conversation goes both ways.','There is a review point.'],
 rel:['debrief','conflict','teachback-skill'],pr:['How could your next feedback include an invitation to respond?','What is the best feedback you have received, and why?','What stops you giving feedback sooner?']},

debrief:{lv:'Core',
 why:['A debrief turns an event, a rehearsal or a difficult shift into learning that someone can act on. The evidence panel summarises a large review in which simulation-based training outperformed no intervention, which is part of why debriefing after practice has become routine. The review does not show that any particular debrief method is best.','A useful debrief is respectful, structured and ends with a follow-through. It compares what was expected with what happened, hears every role, separates facts from assumptions and agrees an owner and a review date. It is not a substitute for formal reporting or investigation where those are required, and confidential case details should not be shared in the app.'],
 fw:{n:'Reaction, analysis, summary',i:'A common three-phase debrief structure. Select a phase.',p:[['1','Reactions','Let people say how it felt and what stood out. This clears the air and shows support.'],['2','Analysis','Compare what was expected with what happened. Ask what helped and what made the task difficult. Invite each role and distinguish facts from assumptions.'],['3','Summary and action','Agree one learning point and one action, with an owner and a review date. Arrange support if needed.']]},
 viz:{k:'timeline',t:'A short, structured debrief',c:'Ten minutes with a clear purpose can be enough.',s:[['Set the purpose','We are here to learn, not to blame.'],['Reactions','How did that feel?'],['Compare','What did we expect? What happened?'],['Understand','What helped? What made it hard?'],['Commit','One action, one owner, one review date.']]},
 terms:[['Debrief','A structured conversation after an event, task or simulation to learn from it.'],['Plus/Delta','A simple tool: what went well (plus) and what we would change (delta).'],['Advocacy–inquiry','Sharing your view and the reasoning behind it, and then asking about the other person’s view with genuine curiosity.'],['Hot and cold debrief','A hot debrief takes place immediately after an event. A cold debrief takes place later, with more time for reflection.']],
 sc:{s:'A fictional team has just finished a challenging practice session. Someone says, “We finished, so there’s nothing to discuss.”',
  a:{q:'How do you respond?',o:[['Agree and move on.',0,'The learning opportunity is lost.'],['“What helped, what was difficult and which one change will we review next time?”',2,'Opens a short, structured and forward-looking conversation.'],['“Who made things difficult?”',1,'Starts from blame and will make people defensive.']]},
  b:{q:'Someone raises a difficult point. How do you close?',up:'People are sharing openly.',dn:'It gets heated.',o:[['Agree one improvement with an owner and review date, share it through approved channels and check how people are feeling.',2,'A follow-through with support closes the loop.'],['Thank everyone and leave it there.',1,'Good intent but no follow-through.'],['Note who was responsible for the problem.',0,'It turns learning into blame.']]},
  end:['The conversation did not lead to learning or action.','Partly effective. Keep the follow-through and psychological safety strong.','A strong path: a respectful structure, honest analysis and an owned action.']},
 spot:{t:'Mark the lines that weaken a debrief.',l:[['“We finished, so there is nothing to discuss.”',1,'Missed learning.'],['“What did we expect and what actually happened?”',0,'Compares plan and reality.'],['“Who made us look bad?”',1,'Blame.'],['“Let’s agree one action, an owner and a review date.”',0,'Follow-through.'],['“We’ll do this through the formal reporting route as well, where required.”',0,'Respects formal processes.']]},
 myths:[['A debrief is only for when things go wrong.','Routine and successful events also contain learning.'],['It needs an hour.','Even ten structured minutes can produce a useful action.'],['Debriefs replace incident reporting.','Use formal processes where required.'],['The leader should do all the talking.','Invite every role to speak.']],
 lad:{t:'How far does the learning travel?',h:'Slide from nothing to a closed loop.',s:[['Nothing','“We’re done.”','No learning.'],['Vent','Complaints without structure.','Relief but little change.'],['Discuss','What happened and why.','Understanding.'],['Decide','One agreed change.','Direction.'],['Close','Change with owner, review date and support.','Learning that sticks.']]},
 chk:['I set a respectful learning purpose.','I used the formal reporting process where required.','I did not share confidential case details inappropriately.','I asked what was expected and what happened.','I heard from each role and separated facts from assumptions.','We agreed one action with an owner and review date.','I shared learning through approved channels.','I checked whether anyone needed support.'],
 good:['People speak openly.','There is one clear action with an owner.','Support is offered when needed.'],
 rel:['feedback','just-culture','improvement'],pr:['Which action from a recent learning discussion still needs an owner?','What makes it safe or unsafe to be honest in your team’s debriefs?','What is one question you could always ask?']},

humility:{lv:'Foundation',
 why:['Confidence helps people act. Certainty that cannot be questioned does the opposite, because it stops the team noticing what does not fit. Intellectual humility is not indecision. It is holding a working explanation firmly enough to act and loosely enough to change.','Practical humility means naming what you do not know, inviting views that differ, and updating visibly when evidence changes. When corrected, credit the contribution and say what changes. It makes it safer for others to question you next time. It also links to diagnostic safety, since patients, carers and colleagues often notice what a current account is missing.'],
 fw:{n:'Four humble moves',i:'Habits that keep a working view open. Select a move.',p:[['1','Name the unknown','Separate a working explanation from a verified fact and say what is unclear.'],['2','Ask what does not fit','Invite the observation that does not match your view.'],['3','Invite another view','Ask who may see something you do not: a patient, carer or colleague.'],['4','Update and tell','Change the plan when evidence changes, and tell people what changed and why.']]},
 viz:{k:'flow',t:'Holding a view lightly',c:'Act on the best current view while staying open to correction.',s:[['Working view','State it clearly.'],['Name uncertainty','What is not yet known?'],['Invite challenge','What does not fit? Who sees it differently?'],['Update','Change the view if the evidence changes.'],['Tell','Share what changed and why.']]},
 terms:[['Intellectual humility','Recognising the limits of one’s knowledge and being open to other views and new evidence.'],['Working diagnosis','The best current explanation, held provisionally and revised as new information emerges.'],['Calibration','How well your confidence matches how often you are right.'],['Premortem','Imagining a plan has failed and asking why, in order to find weaknesses before acting.']],
 sc:{s:'New information challenges a fictional team’s first view. The team leader says, “We have already decided.”',
  a:{q:'What do you say?',o:[['Say nothing. They are senior.',0,'A concern that is not voiced cannot be considered.'],['“This doesn’t fit our earlier view. What should we reconsider, and who needs to review it?”',2,'Respectful, specific and focused on action.'],['“You’re wrong.”',1,'It may be true but is likely to provoke defence.']]},
  b:{q:'The leader changes the plan. How do they respond best?',up:'The leader agrees to review.',dn:'The leader is irritated.',o:[['Thank the person, credit the contribution and tell the team what has changed.',2,'Visible updating makes it safer for others to speak.'],['Change the plan quietly.',1,'The change is made but the team does not learn why or that challenge is welcome.'],['Defend the original plan.',0,'It closes down learning.']]},
  end:['The first view stayed in charge and challenge was discouraged.','Partly effective. Make the update visible and credit the contribution.','A strong path: a respectful challenge and a visible update.']},
 spot:{t:'Mark the lines that close down learning.',l:[['“We have already decided.”',1,'Shuts the door on new information.'],['“Here is my current view and what would change it.”',0,'States a view and its limits.'],['“I cannot be wrong about this.”',1,'Certainty can hide errors.'],['“Thank you for pointing that out. That changes the plan.”',0,'Credits and updates.'],['“Who might see this differently?”',0,'Invites another perspective.']]},
 myths:[['Changing your mind shows weakness.','It can be a sign of careful thinking.'],['Humility means indecision.','You can act on the best current view and stay open.'],['Experts do not need to ask.','Experts also benefit from other perspectives.'],['Seniority settles disagreements.','Evidence should.']],
 lad:{t:'How open is the view?',h:'Slide from fixed certainty to a view that can change.',s:[['Certain','“I’m sure.”','Closed to new information.'],['Confident','“I’m fairly sure.”','Open in theory.'],['Qualified','“Probably X, but not certain.”','Names uncertainty.'],['Testable','“Probably X. This would change my mind.”','Defines what would change the view.'],['Updating','Qualified, testable and changes visibly when evidence changes.','Learning in action.']]},
 chk:['I distinguished a working explanation from a fact.','I named what I do not know.','I asked what does not fit.','I asked who might see it differently.','I updated the plan when evidence changed.','I told relevant people what changed and why.','I credited the person who raised the challenge.'],
 good:['The team can say what would change its mind.','Challenges are welcomed and credited.','Plans update visibly.'],
 rel:['reasoning','speakup','just-culture'],pr:['What would make you reconsider your current explanation?','When did being corrected help you?','How do you respond when you feel challenged?']},

dignity:{lv:'Foundation',
 why:['Dignity is expressed in small things: using someone’s preferred name, asking before you begin, speaking to the person rather than over them, protecting privacy and offering choices. For many people these details shape whether care feels respectful more than any single clinical decision.','Respect includes adapting how you interact. A person may need an interpreter, an accessible format, extra time or a different arrangement for who is present. Do not assume preferences from appearance or disability. Ask, within the applicable consent process and local policy. Where urgency limits choice, explain why and restore as much control as you can.'],
 fw:{n:'Name, permission, privacy, participation',i:'Four habits of respect in routine care. Select a habit.',p:[['1','Name','Use the person’s preferred name and introduce yourself and your role.'],['2','Permission','Explain what you plan to do and ask before you begin, within the applicable consent process.'],['3','Privacy','Notice who can see or hear, and protect the person’s space and information.'],['4','Participation','Speak to the person. Ask what support would help and who they want involved.']]},
 viz:{k:'compare',t:'Talking to the person',c:'The same moment in two styles.',h:['Talking over','Including'],s:[['“What does he need?” (to the companion)','“I’d like to hear from you directly. What would help?”'],['Starts a task without explaining','“I’m going to check your blood pressure. Is that all right?”'],['Discusses in an open ward','Moves to a more private space or lowers voices and closes the curtain']]},
 terms:[['Dignity','Being treated as someone of worth, with respect for privacy, choice and individuality.'],['Consent (in everyday care)','The person’s ongoing agreement to what is happening, requested and respected within the law and local policy.'],['Autonomy','A person’s right to make decisions about their own care and life.'],['Reasonable adjustment','A change to how a service works so that a person with a disability or other need can participate fully.']],
 sc:{s:'In a fictional appointment, a companion answers every question on behalf of the patient, who is present and alert.',
  a:{q:'What do you do?',o:[['Continue talking to the companion, since they are answering.',0,'The person’s own voice is missing.'],['Turn to the person, say you would like to hear from them, and ask what involvement they want from their companion.',2,'You address the person directly and let them decide.'],['Ask the companion to leave.',1,'The person may want their companion. Ask them first.']]},
  b:{q:'The person prefers their companion to stay but wants to speak for themselves. What now?',up:'They speak for themselves.',dn:'They seem unsure.',o:[['Agree this with them, ask what support would help the conversation and check privacy for any sensitive topic.',2,'Respects their preference and adapts the interaction.'],['Return to speaking mostly to the companion.',0,'Reverts to excluding the person.'],['Skip sensitive topics to avoid awkwardness.',1,'May leave out information the person needs.']]},
  end:['The person was spoken about rather than to.','Partly effective. Keep including the person and checking privacy.','A strong path: respectful, adapted and led by the person’s preferences.']},
 spot:{t:'Mark the lines that take away voice or privacy.',l:[['“Tell us what they need.”',1,'Talks over the person.'],['“I’d like to hear from you directly.”',0,'Addresses the person.'],['“I’ll just start, it won’t take a moment.”',1,'No explanation or permission.'],['“I’m going to check your blood pressure. Is that all right?”',0,'Explains and asks.'],['“We can talk about this in the room if you prefer more privacy.”',0,'Protects privacy.']]},
 myths:[['A companion speaks for the person.','Ask the person who they want to speak and when.'],['Routine tasks do not need permission.','Explain and ask, even for routine care.'],['People with disabilities need me to decide for them.','Ask what support would help.'],['Privacy is a luxury.','It is part of dignity and often a legal duty.']],
 lad:{t:'How much voice does the person have?',h:'Slide from no voice to full participation.',s:[['Ignored','Spoken about, not to.','No voice.'],['Informed','Told what will happen.','Some respect, no choice.'],['Asked','“Is that all right?”','Permission.'],['Included','Asked what they prefer and who is present.','Voice and choice.'],['Led','Preferences shape the interaction, with privacy and support in place.','Full participation.']]},
 chk:['I used the person’s preferred name and introduced my role.','I spoke directly to the person.','I explained and asked before I began.','I protected privacy and who could hear or see.','I asked what support would help.','I arranged interpretation or an accessible format where needed.','I involved companions according to the person’s preference.'],
 good:['The person’s voice is heard.','Privacy is protected.','Support fits the person.'],
 rel:['equity','empathy','communication'],pr:['Which small routine could give a person more voice or privacy?','When have you talked over someone without noticing?','How do you explain what you are about to do?']},

'just-culture':{lv:'Advanced',
 why:['A just culture tries to balance two things: learning from events without defaulting to blame, and holding people fairly accountable for their choices. The first part recognises that most errors arise in systems with workload, interruptions, unclear roles and poor design. The second recognises that a systems view does not excuse deliberate unsafe behaviour.','A commonly used framework distinguishes three kinds of behaviour. Human error is an unintentional slip or lapse, where the usual response is to support the person and fix the system. At-risk behaviour is a choice where risk is not recognised or is believed to be justified, where the usual response is coaching and removing the incentive. Reckless behaviour is a conscious disregard of a substantial risk, which may warrant formal action under local policy. The evidence panel notes that preventable harm is reported across care settings.'],
 fw:{n:'Three kinds of behaviour',i:'A commonly used just-culture framework. Select a kind of behaviour.',p:[['1','Human error','An unintended slip, lapse or mistake. Usual response: console and support the person, look at the system and fix the conditions.'],['2','At-risk behaviour','A choice where the risk was not recognised or was thought justified, such as a shortcut that has become normal. Usual response: coach and look at why the shortcut made sense.'],['3','Reckless behaviour','Conscious disregard of a substantial and unjustifiable risk. Usual response: follow the organisation’s formal process, which may include sanction.']]},
 viz:{k:'matrix',t:'Choosing a fair response',c:'The same event can have different responses depending on the behaviour and the context. Use the organisation’s formal process to decide.',s:[['Human error','Console, support and fix the system.','Support'],['At-risk behaviour','Coach, remove incentives for the shortcut and understand why it made sense.','Coach'],['Reckless behaviour','Formal process under local policy.','Accountability']]},
 terms:[['Just culture','An approach that combines learning from events, fairness and clear accountability, rather than blaming individuals by default.'],['Substitution test','Asking whether other people with similar training and in the same situation might have done the same. If yes, look at the system.'],['Hindsight bias','Judging a decision as if its outcome had been obvious at the time.'],['Second victim','A term for clinicians who are personally affected after an adverse event. Support for those involved is part of a fair response.']],
 sc:{s:'A fictional team discovers a near miss. Someone says: “Let’s find out who did it and close the issue.”',
  a:{q:'What do you propose?',o:[['Agree. Find the person and close the issue.',0,'It treats the event as an individual failing and leaves conditions unchanged.'],['Establish the facts, follow the reporting process and look at conditions such as workload, interruptions and unclear roles.',2,'Combines fact-finding, fair process and system learning.'],['Say that individuals are never responsible.',1,'A systems view still holds people accountable for deliberate unsafe behaviour.']]},
  b:{q:'The review finds a common shortcut that many staff use. What now?',up:'Facts have been gathered.',dn:'Opinions differ.',o:[['Coach, ask why the shortcut made sense, fix what encourages it and share learning through approved channels.',2,'Responds to at-risk behaviour with coaching and system change.'],['Sanction the person who was caught.',0,'Others do the same, so the system keeps producing the behaviour.'],['Ignore it. Nothing went wrong.',1,'A normalised shortcut carries risk that has not yet materialised.']]},
  end:['The event was handled as individual blame, with little system learning.','Partly effective. Keep fair accountability and system learning together.','A strong path: facts, fair process and system change.']},
 spot:{t:'Mark the lines that mix up blame and accountability.',l:[['“Find the person responsible and close it.”',1,'Blame without understanding conditions.'],['“Let’s establish the facts and follow the reporting process.”',0,'Fair process.'],['“A systems approach means nobody is ever accountable.”',1,'It means understanding context and still holding people accountable for deliberate unsafe behaviour.'],['“Would other staff in the same situation have done the same?”',0,'The substitution test.'],['“We should also support the staff involved.”',0,'Support is part of fairness.']]},
 myths:[['Just culture means no accountability.','It means fair accountability with context.'],['Blame improves safety.','It discourages reporting and hides learning.'],['Most events are caused by one careless person.','Most arise from several conditions in the system.'],['Reporting is a confession.','Reporting is how the system learns.']],
 lad:{t:'How fair is the response?',h:'Slide from blame to a fair, learning response.',s:[['Blame','Find who did it.','Discourages reporting.'],['Excuse','Nobody is ever responsible.','Ignores deliberate unsafe behaviour.'],['Facts','Establish what happened.','Foundation for fairness.'],['Context','Understand workload, tools and roles.','Reveals system causes.'],['Fair response','Facts, context, a fair process, support and change.','Learning with accountability.']]},
 chk:['I started with the facts and immediate safety.','I used the appropriate reporting and support process.','I avoided speculating about motives.','I asked about workload, tools, interruptions and roles.','I applied the organisation’s fair process to conduct and context.','I coached rather than punished at-risk behaviour.','I agreed system changes and follow-up.','I supported the people involved.'],
 good:['People report events without fear.','Responses are fair and consistent.','Changes address the conditions.'],
 rel:['human-factors','accountability','debrief'],pr:['Which system question should come before a judgment about a person?','What shortcuts exist in your area, and why?','How is support offered after an event?']},

accountability:{lv:'Core',
 why:['Accountability means being answerable for what you have committed to do, and being honest when a commitment cannot be met. It is easy to assume that someone else will handle a task, and many handover failures arise when an action is mentioned but never owned.','Being accountable includes saying what is within your role and what needs another person’s authority or expertise. It means communicating a constraint early and agreeing an alternative owner or contingency, rather than leaving a silent gap. It is a professional strength to say when a task needs help.'],
 fw:{n:'Commit, communicate, close',i:'Three parts of accountable follow-through. Select a part.',p:[['1','Commit clearly','State what you can do within your role and what needs another person’s authority. Do not accept a task by implication.'],['2','Communicate limits early','If you cannot meet a commitment, say so through the appropriate route and agree an alternative owner or contingency.'],['3','Close the loop','Confirm completion through the approved process and make outstanding items visible at transitions.']]},
 viz:{k:'timeline',t:'From request to closure',c:'Every step has an owner. Gaps happen when one is missing.',s:[['Request','Who is asking for what and by when?'],['Accept or decline','Say what you can do within your role.'],['Do or escalate','Act, or tell someone early if you cannot.'],['Confirm','Say it is done through the approved route.'],['Hand over','Outstanding items named at transition.']]},
 terms:[['Accountability','Being answerable for your actions and decisions and for the commitments you have accepted.'],['Scope of practice','The tasks and decisions you are trained, competent and authorised to carry out.'],['Contingency','What happens if the plan does not work or someone cannot do their part.'],['Closing the loop','Confirming that an agreed action has been done and reported back.']],
 sc:{s:'In a fictional team, a colleague says: “Somebody will arrange a review.” Nobody has been named.',
  a:{q:'What do you say?',o:[['“OK.” You assume someone will.',0,'This is how actions are lost.'],['“Let’s confirm who owns it, by when and what happens if they cannot.”',2,'Names the owner, timing and contingency.'],['Do it yourself without telling anyone.',1,'Solves the immediate issue but is not visible to the team and may be beyond your role.']]},
  b:{q:'Later you realise you cannot complete a task you accepted.',up:'The owner is named.',dn:'You are overloaded.',o:[['Tell the right person early, explain the constraint and agree an alternative owner or plan.',2,'Early communication prevents a silent gap.'],['Hope to catch up and say nothing.',0,'A late surprise is harder to fix.'],['Quietly pass it to a colleague.',1,'The colleague may not know it is theirs, and the original requester is not told.']]},
  end:['The task remained unowned, so it is likely to be missed.','Partly effective. Make commitments and limits visible.','A strong path: clear ownership, early communication and closure.']},
 spot:{t:'Mark the lines that leave a task unowned.',l:[['“Somebody will handle it.”',1,'Nobody is named.'],['“I will do it by 15:00. If I can’t, I’ll tell you by 14:00.”',0,'Commitment and early warning.'],['“I’m too busy, but I’m sure it will happen.”',1,'Hope is not a plan.'],['“That’s beyond my role. Let’s ask the responsible person.”',0,'Clear about limits.'],['“Outstanding: review of bed 3, owner Sam, by 16:00.”',0,'Visible at handover.']]},
 myths:[['Saying no looks bad.','Saying what you cannot do and finding another route is accountable.'],['If I mentioned it, it is done.','Confirm who owns it.'],['Accountability is about blame.','It is about ownership and follow-through.'],['Helping always means taking it on.','Helping may mean connecting someone with the right person.']],
 lad:{t:'How clear is the ownership?',h:'Slide from assumed to closed.',s:[['Assumed','“Somebody will.”','Nobody knows.'],['Mentioned','“I raised it.”','Not owned.'],['Owned','A named person.','Someone is responsible.'],['Timed','Owner and time.','Can be checked.'],['Closed','Owner, time, contingency and confirmed completion.','Accountable.']]},
 chk:['I stated what is within my role.','I did not accept a task by implication.','I told the right person early if I could not meet a commitment.','I agreed an alternative owner or contingency.','I confirmed completion through the approved process.','Outstanding items are visible at handover.'],
 good:['Every action has a named owner and time.','Limits are communicated early.','Items are closed and confirmed.'],
 rel:['sbar','documentation','just-culture'],pr:['Which commitment needs an explicit owner, deadline or contingency?','When did a task get lost because of assumed ownership?','How comfortable are you saying “I need help”?']},

'compassion-boundaries':{lv:'Core',
 why:['Compassion in care is warm, practical and honest about limits. People who care often feel pressure to promise more than they can deliver or to absorb every need. This is not sustainable, and reliable support is more helpful than heroic but unpredictable support.','A bounded response acknowledges distress, says what you can offer, and connects the person with the right service. For colleagues, it also means noticing when persistent strain points to workload or staffing that needs organisational attention. A short personal reset helps but does not replace workload review.'],
 fw:{n:'Acknowledge, bound, connect, sustain',i:'A compassionate response that stays within role. Select a step.',p:[['1','Acknowledge','Ask what is difficult and listen without judgement. Avoid promising outcomes outside your control.'],['2','Bound','Say what you can help with and what needs a different service or professional.'],['3','Connect','Arrange the handover to the right support, ideally personally, with the person’s agreement.'],['4','Sustain','Notice what the situation costs you, use support yourself, and raise recurring gaps with the team.']]},
 viz:{k:'flow',t:'A bounded, kind response',c:'Clear limits can make support more dependable.',s:[['Listen','What is hardest right now?'],['Say what you can do','Within your role and time.'],['Say what you cannot','And who can help.'],['Connect','Help them reach that support.'],['Follow up','Check in as agreed.']]},
 terms:[['Boundary','A clear limit on what you can offer, which makes support more reliable.'],['Warm handover','Introducing the person to another service or colleague personally and explaining the situation, with consent.'],['Signposting','Telling someone where they can find appropriate support.'],['Compassion fatigue','A term used for the exhaustion that can follow sustained exposure to others’ distress. It is a signal to seek support and review workload.']],
 sc:{s:'A fictional colleague is struggling with continuing workload and says they cannot cope.',
  a:{q:'How do you respond?',o:[['“A quick breathing exercise will fix it.”',0,'A short exercise cannot fix a continuing workload problem.'],['“I can listen and help work out who can support you. We should also raise the workload through the right route.”',2,'Compassion, a boundary and attention to cause.'],['“I’ll take on all your work from now on.”',1,'Generous but unsustainable and hides the gap.']]},
  b:{q:'They ask you to promise to keep it secret.',up:'They are opening up.',dn:'They are distressed.',o:[['Explain what you can keep private and when you would need to involve others for safety, then agree the next step together.',2,'Honest about limits, still supportive.'],['Promise to tell no one, whatever happens.',0,'You may not be able to keep it if safety is at risk.'],['Tell their manager immediately without asking.',1,'May be necessary in some cases, but explain and involve them where you can.']]},
  end:['Support was either overpromised or too thin to help.','Partly effective. Pair kindness with clear limits and a route.','A strong path: warm, bounded and connected.']},
 spot:{t:'Mark the lines that overpromise or dismiss.',l:[['“I promise everything will be fine.”',1,'A promise you cannot keep.'],['“I can help with this step and connect you with the right support.”',0,'Bounded and connected.'],['“You just need to be stronger.”',1,'Dismissive.'],['“It sounds like a lot. What would help most?”',0,'Acknowledges and asks.'],['“Let’s raise the workload with the team.”',0,'Addresses cause.']]},
 myths:[['Good carers never say no.','Clear limits make support reliable.'],['Compassion means fixing everything.','Compassion also means connecting people with the right help.'],['If I keep going, I am being compassionate.','Persistent overload can reduce quality and wellbeing.'],['A personal reset is enough.','It helps, but workload needs a team or organisational response.']],
 lad:{t:'How sustainable is the support?',h:'Slide from unlimited to bounded and connected.',s:[['Unlimited','“I’ll do anything.”','Not sustainable.'],['Reassure','“It will be fine.”','Overpromises.'],['Listen','Acknowledge and listen.','Warm but incomplete.'],['Bounded','Say what you can and cannot do.','Reliable.'],['Connected','Bounded and linked to the right support, with a follow-up.','Sustainable and helpful.']]},
 chk:['I listened without judgement.','I avoided promises outside my control.','I said what I can help with and what needs another service.','I helped connect the person to support.','I was honest about confidentiality limits.','I raised persistent workload concerns.','I used support myself.'],
 good:['Support is warm, honest and dependable.','People know where else to turn.','Workload gaps are raised, not hidden.'],
 rel:['wellbeing','empathy','accountability'],pr:['Where would a clearer boundary make your support more dependable?','What do you find hardest to say no to?','Who supports you?']},

'inclusive-leadership':{lv:'Core',
 why:['Decisions are better when the people affected by them can contribute. In practice, meetings often hear the same voices because of seniority, speaking style, language, access needs or confidence. Silence is not agreement. It may mean someone cannot easily speak or does not expect to be heard.','Research on leader inclusiveness suggests that explicitly inviting input and appreciating it supports psychological safety. Offer more than one route for input, and show what changed because of what you heard, since an invitation without a response can leave people feeling unheard. The evidence panel’s accessibility data is a reminder that access needs are common.'],
 fw:{n:'Notice, invite, respond, show',i:'Four leadership habits. Select a habit.',p:[['1','Notice','Ask who is missing from the decision and who cannot attend, speak easily or access the materials.'],['2','Invite','Offer more than one way to contribute: before, during or after the meeting, spoken or written. Invite specific observations without putting someone on the spot.'],['3','Respond','Receive input with thanks and curiosity. Say how it affects the decision.'],['4','Show','Tell people what changed because of their input and assign follow-up.']]},
 viz:{k:'timeline',t:'Making participation possible',c:'Inclusion is a sequence, not a single invitation.',s:[['Before','Share materials early in accessible formats. Invite input in writing.'],['During','Invite quieter voices. Slow down. Check who has not spoken.'],['After','Offer another route for input.'],['Respond','Say what you heard.'],['Show change','Explain how it shaped the decision.']]},
 terms:[['Inclusive leadership','Leadership that invites and appreciates contributions from all team members and makes it possible for them to participate.'],['Power distance','How much less powerful people expect and accept that power is unequally distributed. A high power distance can discourage challenge.'],['Accessible meeting','A meeting where materials, format and environment allow people with different needs to take part fully.'],['Psychological safety','A shared belief that it is safe to speak up, ask and disagree.']],
 sc:{s:'A fictional meeting regularly hears only its most senior members. A junior colleague has been silent throughout.',
  a:{q:'What do you do as the chair?',o:[['Assume silence means agreement and move on.',0,'Silence may mean someone cannot easily contribute.'],['Say you would like to hear other perspectives, offer a written route for input after the meeting and invite specific observations.',2,'Offers more than one route without putting someone on display.'],['Call on the junior colleague by name to give their view.',1,'It can feel like being put on the spot. Offer options.']]},
  b:{q:'The colleague sends a suggestion afterwards. What do you do?',up:'You have their input.',dn:'Their suggestion challenges the plan.',o:[['Thank them, explain how it affects the decision and tell the group what changed.',2,'A visible response makes future input more likely.'],['Say thanks and file it.',1,'Gratitude without a response can feel hollow.'],['Ignore it because the plan is settled.',0,'Shows the invitation was not genuine.']]},
  end:['The usual voices dominated and others stopped offering input.','Partly effective. Keep inviting and show how input changed things.','A strong path: multiple routes, a respectful invitation and a visible response.']},
 spot:{t:'Mark the lines that make participation harder.',l:[['“Silence means everyone agrees.”',1,'It may mean people cannot easily speak.'],['“You can also send me comments after the meeting.”',0,'A second route.'],['“Let’s hear from the most senior first.”',1,'Seniors speaking first can shape what others say.'],['“I changed the plan because of your point. Thank you.”',0,'Shows input mattered.'],['“Which perspective have we not heard?”',0,'Notices who is missing.']]},
 myths:[['If people have something to say they will say it.','Many people hold back for reasons unrelated to ideas.'],['Inclusion means everyone has to speak.','It means making it possible, in more than one way.'],['Inviting once is enough.','Respond and show change or people stop offering input.'],['It slows decisions.','It can improve decisions and reduce rework.']],
 lad:{t:'How inclusive is the invitation?',h:'Slide from silence assumed to participation made possible.',s:[['Assume','Silence means agreement.','Misses unspoken views.'],['Ask once','“Any comments?”','Easy to stay silent.'],['Ask specifically','“What have you noticed?”','Invites real input.'],['Multiple routes','Spoken and written, before and after.','More people can contribute.'],['Respond and show','Routes, thanks and visible change.','Contribution is rewarded.']]},
 chk:['I asked who is missing from the decision.','I shared materials early and in accessible formats.','I offered more than one way to contribute.','I invited specific observations without putting anyone on display.','I thanked contributors and explained how input affected the decision.','I assigned follow-up.','I checked for barriers afterwards.'],
 good:['More voices shape decisions.','People can see what changed.','Access needs are met routinely.'],
 rel:['speakup','equity','debrief'],pr:['Whose perspective should shape your next improvement discussion?','When did you hold back in a meeting, and why?','What is one second route for input you could offer?']},
};

/* Carecraft Learn (library, lesson page, pathways, saved): new and reworked views live here so the redesign stays out of the long single-line source files. Loaded after studio.js, before events.js.
   Everything here reassigns functions declared earlier (renderLearn, renderLesson, lessonCard, renderPathways, previewLesson, lessonEvidence, filteredLessons, renderWorkedExample,
   infographicPages, ccStudioDeck) or registers actions through LX_ACTIONS (merged into `actions` in bootstrap, because `actions` is declared later in events.js).
   Lesson content lives in learn-data.js (LX_DATA). Components are data-driven: one renderer per kind, one spec per lesson, so all 30 lessons get the same quality. */
const LX_TABS=['overview','learn','scenario','practice','reflect'];
const LX_TAB_LABEL={overview:'Overview',learn:'Learn',scenario:'Scenario',practice:'Practise',reflect:'Reflect'};
const LX_TONE={2:['Strong choice','strong','✓'],1:['Partly helpful','mixed','~'],0:['Less helpful','weak','!']};
const LX={fw:{},fl:{},sc:{},sp:{},lad:{},calc:{base:4,rr:50}};
const LX_INNER={};
const lxD=l=>LX_DATA[l.id];
const lxLv=l=>(LX_DATA[l.id]||{}).lv||'Core';
const lxTitle=id=>(lessons.find(l=>l.id===id)||{}).title||id;
function lxHash(s){let h=0;for(const c of String(s))h=(h*31+c.charCodeAt(0))>>>0;return h;}
function lxRot(id,n,len=3){const r=(lxHash(id)+n)%len;return Array.from({length:len},(_,i)=>(i+r)%len);}
/* Persistent per-lesson progress. state.lx is an additive key; unknown keys survive migration and backups. lxR reads without creating, lxP creates. */
function lxR(id){const p=state.lx&&typeof state.lx==='object'&&!Array.isArray(state.lx)?state.lx[id]:null;return p&&typeof p==='object'?{v:Array.isArray(p.v)?p.v.filter(t=>LX_TABS.includes(t)):[],tk:Array.isArray(p.tk)?p.tk.filter(Number.isInteger):[],sc:Number.isInteger(p.sc)?p.sc:-1,sp:Number.isInteger(p.sp)?p.sp:-1,last:LX_TABS.includes(p.last)?p.last:''}:{v:[],tk:[],sc:-1,sp:-1,last:''};}
function lxP(id){if(!state.lx||typeof state.lx!=='object'||Array.isArray(state.lx))state.lx={};const c=lxR(id);if(!state.lx[id]||typeof state.lx[id]!=='object')state.lx[id]={};Object.assign(state.lx[id],c);return state.lx[id];}
function lxMark(id,tab){const p=lxR(id);if(!p.v.includes(tab)||p.last!==tab){const q=lxP(id);if(!q.v.includes(tab))q.v.push(tab);q.last=tab;persist();}}
function lxStages(l){const p=lxR(l.id);return {overview:p.v.includes('overview'),learn:p.v.includes('learn'),scenario:p.sc>=0,practice:state.checkRecords.some(r=>r.lesson===l.id),reflect:state.completed.includes(l.id)||!!(state.reflections[l.id]||'').trim()};}
function lxPct(l){return Math.round(Object.values(lxStages(l)).filter(Boolean).length/LX_TABS.length*100);}
function lxStatusWord(l){const s=status(l),p=lxPct(l);return s==='Not started'&&p>0?'In progress':s;}
/* Wrapper and refresh: components re-render in place so scroll position and focus survive */
function lxWrap(kind,l,cls=''){return `<section class="lx-c lx-k-${kind} ${cls}" data-lxc="${kind}" data-lxid="${l.id}">${LX_INNER[kind](l)}</section>`;}
function lxRefresh(kind,id,focus){const el=document.querySelector(`[data-lxc="${kind}"][data-lxid="${id}"]`),l=lessons.find(x=>x.id===id);if(!el||!l)return;el.innerHTML=LX_INNER[kind](l);if(focus)el.querySelector(focus)?.focus({preventScroll:true});}
const lxHead=(eyebrow,title,sub)=>`<div class="lx-c-head"><span class="eyebrow">${eyebrow}</span><h3>${title}</h3>${sub?`<p>${sub}</p>`:''}</div>`;

/* ---------- Diagrams: one spec, six kinds, generated inline (HTML and SVG, no libraries) ---------- */
function lxCycleSvg(s){const n=s.length,R=116,cx=170,cy=160,r=38,gap=2*Math.asin((r+8)/(2*R)),step=2*Math.PI/n,P=a=>[cx+R*Math.cos(a),cy+R*Math.sin(a)];let arcs='',nodes='';for(let i=0;i<n;i++){const a=-Math.PI/2+i*step,[x1,y1]=P(a+gap),[x2,y2]=P(a+step-gap),[nx,ny]=P(a);arcs+=`<path class="lx-arc" d="M${x1.toFixed(1)} ${y1.toFixed(1)}A${R} ${R} 0 0 1 ${x2.toFixed(1)} ${y2.toFixed(1)}" marker-end="url(#lxArrow)"/>`;nodes+=`<g><circle class="lx-node" cx="${nx.toFixed(1)}" cy="${ny.toFixed(1)}" r="${r}"/><text class="lx-node-n" x="${nx.toFixed(1)}" y="${(ny-9).toFixed(1)}" text-anchor="middle">${i+1}</text><text class="lx-node-t" x="${nx.toFixed(1)}" y="${(ny+9).toFixed(1)}" text-anchor="middle">${esc(s[i][0])}</text></g>`;}return `<svg class="lx-svg lx-cycle-svg" viewBox="0 0 340 320" aria-hidden="true" focusable="false"><defs><marker id="lxArrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M1 1L9 5L1 9z" class="lx-arrowhead"/></marker></defs><text class="lx-hub" x="${cx}" y="${cy+4}" text-anchor="middle">repeat</text>${arcs}${nodes}</svg>`;}
function lxLayersSvg(s,id){const n=s.length,W=640,sw=66,pad=44,span=(W-2*pad-sw)/(n-1),blocked=Math.min(2,n-1);let out='';for(let i=0;i<n;i++){const x=pad+i*span,h=lxHash(id+i),holes=i===blocked?[44,150,185]:[109,44+(h%40),150+(h%30)];out+=`<rect class="lx-slice${i===blocked?' is-mine':''}" x="${x.toFixed(1)}" y="20" width="${sw}" height="190" rx="12"/>`;holes.forEach((y,k)=>{if(k===0||i!==blocked)out+=`<ellipse class="lx-hole" cx="${(x+sw/2+(k?((h>>k)%14-7):0)).toFixed(1)}" cy="${y}" rx="12" ry="14"/>`;});if(i===blocked)out+=`<ellipse class="lx-hole" cx="${(x+sw/2).toFixed(1)}" cy="44" rx="12" ry="14"/><ellipse class="lx-hole" cx="${(x+sw/2).toFixed(1)}" cy="185" rx="12" ry="14"/>`;}const bx=pad+blocked*span;return `<svg class="lx-svg lx-layers-svg" viewBox="0 0 ${W} 230" aria-hidden="true" focusable="false"><defs><marker id="lxHaz" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="7" markerHeight="7" orient="auto"><path d="M1 1L9 5L1 9z" class="lx-hazhead"/></marker></defs>${out}<path class="lx-haz" d="M6 109H${(bx-6).toFixed(1)}" marker-end="url(#lxHaz)"/><text class="lx-x" x="${(bx+sw/2).toFixed(1)}" y="${224}" text-anchor="middle">stopped here</text><text class="lx-x2" x="14" y="${96}" >hazard</text></svg>`;}
function lxViz(l){const v=lxD(l).viz,k=v.k,s=v.s,head=lxHead('DIAGRAM',esc(v.t),esc(v.c));let body='';
 if(k==='flow')body=`<ol class="lx-flow">${s.map(([t,x],i)=>`<li><span class="lx-flow-n" aria-hidden="true">${i+1}</span><b>${esc(t)}</b><span>${esc(x)}</span></li>`).join('')}</ol>`;
 else if(k==='timeline')body=`<ol class="lx-tl">${s.map(([t,x])=>`<li><b>${esc(t)}</b><span>${esc(x)}</span></li>`).join('')}</ol>`;
 else if(k==='cycle')body=`<div class="lx-cycle">${lxCycleSvg(s)}<ol class="lx-legend">${s.map(([t,x])=>`<li><b>${esc(t)}</b><span>${esc(x)}</span></li>`).join('')}</ol></div>`;
 else if(k==='layers')body=`<div class="lx-layers">${lxLayersSvg(s,l.id)}<ol class="lx-legend lx-legend-row">${s.map(([t,x],i)=>`<li class="${i===Math.min(2,s.length-1)?'is-mine':''}"><b>${esc(t)}</b><span>${esc(x)}</span></li>`).join('')}</ol></div>`;
 else if(k==='matrix')body=`<ul class="lx-mx">${s.map(([t,x,g])=>`<li><span class="lx-mx-tag">${esc(g||'')}</span><b>${esc(t)}</b><span>${esc(x)}</span></li>`).join('')}</ul>`;
 else if(k==='compare'){const h=v.h||['Weaker','Stronger'];body=`<div class="lx-cmp"><div class="lx-cmp-h" aria-hidden="true"><span>${esc(h[0])}</span><span>${esc(h[1])}</span></div>${s.map(([a,b])=>`<div class="lx-cmp-row"><p class="lx-cmp-l"><span class="lx-cmp-tag">${esc(h[0])}</span>${esc(a)}</p><p class="lx-cmp-r"><span class="lx-cmp-tag">${esc(h[1])}</span>${esc(b)}</p></div>`).join('')}</div>`;}
 return `<figure class="lx-c lx-viz lx-viz-${k}" aria-label="${esc(v.t)}">${head}${body}</figure>`;}

/* ---------- Components ---------- */
LX_INNER.fw=l=>{const f=lxD(l).fw,i=LX.fw[l.id]||0,p=f.p[i];return `${lxHead('FRAMEWORK',esc(f.n),esc(f.i))}<div class="lx-tiles" role="group" aria-label="${esc(f.n)}">${f.p.map((x,k)=>`<button type="button" class="lx-tile" data-action="lx-fw" data-arg0="${l.id}" data-arg1="${k}" data-lx-key="fw${k}" aria-pressed="${k===i}"><span class="lx-tile-tag" aria-hidden="true">${esc(x[0])}</span><span class="lx-tile-name">${esc(x[1])}</span></button>`).join('')}</div><div class="lx-tile-detail" role="region" aria-live="polite" aria-label="Detail: ${esc(p[1])}"><h4>${esc(p[1])}</h4><p>${esc(p[2])}</p></div>`;};
LX_INNER.flip=l=>{const t=lxD(l).terms,on=LX.fl[l.id]||(LX.fl[l.id]=new Set());return `${lxHead('KEY TERMS','Say it precisely','Try to say each definition in your own words, then turn the card over to compare.')}<div class="lx-flips">${t.map(([a,b],k)=>{const o=on.has(k);return `<button type="button" class="lx-flip" data-action="lx-flip" data-arg0="${l.id}" data-arg1="${k}" aria-pressed="${o}"><span class="lx-flip-in"><span class="lx-face lx-front" aria-hidden="${o}"><i>Term</i><b>${esc(a)}</b><em>Turn over</em></span><span class="lx-face lx-back" aria-hidden="${!o}"><i>${esc(a)}</i><span>${esc(b)}</span></span></span></button>`;}).join('')}</div>`;};
function lxScState(id){return LX.sc[id]||(LX.sc[id]={stage:'intro',a:null,b:null});}
function lxScore(st,s){return s.a.o[st.a][1]+s.b.o[st.b][1];}
LX_INNER.sc=l=>{const s=lxD(l).sc,st=lxScState(l.id),steps=['Decision 1','Decision 2','Outcome'],cur=({intro:-1,a:0,fa:0,b:1,fb:1,end:2})[st.stage];
 const track=`<ol class="lx-sc-steps" aria-label="Progress">${steps.map((t,i)=>`<li class="${i<cur?'is-done':i===cur?'is-now':''}"${i===cur?' aria-current="step"':''}>${t}</li>`).join('')}</ol>`;
 const opts=(node,n)=>{const q=s[node],chosen=st[node],done=chosen!==null&&(st.stage==='f'+node||st.stage==='end');return `<h4 class="lx-sc-q" id="lxq${node}">${esc(q.q)}</h4><div class="lx-opts" role="group" aria-labelledby="lxq${node}">${lxRot(l.id,n).map(i=>{const o=q.o[i],tn=LX_TONE[o[1]],mine=chosen===i;return `<button type="button" class="lx-opt${done?(mine?' is-picked tone-'+tn[1]:' is-dim'):''}" data-action="lx-pick" data-arg0="${l.id}" data-arg1="${node}" data-arg2="${i}" data-lx-key="o${i}" ${done?'disabled':''} ${mine?'aria-current="true"':''}><span>${esc(o[0])}</span></button>`;}).join('')}</div>`;};
 const fb=node=>{const q=s[node],o=q.o[st[node]],tn=LX_TONE[o[1]];return `<div class="lx-fb tone-${tn[1]}" role="status" tabindex="-1" data-lx-key="fb"><b><span aria-hidden="true">${tn[2]}</span> ${tn[0]}</b><p>${esc(o[2])}</p></div><details class="lx-others"><summary>See why the other options land differently</summary>${q.o.map((x,i)=>i===st[node]?'':`<p><b>${LX_TONE[x[1]][0]}.</b> “${esc(x[0])}” ${esc(x[2])}</p>`).join('')}</details>`;};
 let body='';
 if(st.stage==='intro')body=`<p class="lx-sc-setup">${esc(s.s)}</p><p class="lx-note">Two decisions. There is no timer and no penalty. Fictional people and events; within your role and local policy.</p><button type="button" class="button primary" data-action="lx-sc" data-arg0="${l.id}" data-arg1="start" data-lx-key="go">Begin the scenario</button>`;
 else if(st.stage==='a')body=`<p class="lx-sc-setup">${esc(s.s)}</p>${opts('a',0)}`;
 else if(st.stage==='fa')body=`<p class="lx-sc-setup">${esc(s.s)}</p>${opts('a',0)}${fb('a')}<button type="button" class="button primary" data-action="lx-sc" data-arg0="${l.id}" data-arg1="next" data-lx-key="go">Continue</button>`;
 else if(st.stage==='b'||st.stage==='fb'){const up=s.a.o[st.a][1]>=2;body=`<p class="lx-sc-setup lx-sc-then"><b>What happens next.</b> ${esc(up?s.b.up:s.b.dn)}</p>${opts('b',1)}${st.stage==='fb'?`${fb('b')}<button type="button" class="button primary" data-action="lx-sc" data-arg0="${l.id}" data-arg1="next" data-lx-key="go">See the outcome</button>`:''}`;}
 else{const sc=lxScore(st,s),e=s.end[sc>=3?2:sc>=2?1:0],best=lxR(l.id).sc;body=`<div class="lx-outcome tone-${sc>=3?'strong':sc>=2?'mixed':'weak'}" role="status" tabindex="-1" data-lx-key="fb"><b>Your path: ${sc} of 4</b><p>${esc(e)}</p></div><ol class="lx-trail"><li><span>Decision 1</span> ${esc(s.a.o[st.a][0])} <em>${LX_TONE[s.a.o[st.a][1]][0]}</em></li><li><span>Decision 2</span> ${esc(s.b.o[st.b][0])} <em>${LX_TONE[s.b.o[st.b][1]][0]}</em></li></ol><p class="lx-note">${best>=0?`Best path so far: ${best} of 4. `:''}A learning aid, not an assessment.</p><div class="lx-actions"><button type="button" class="button secondary" data-action="lx-sc" data-arg0="${l.id}" data-arg1="restart" data-lx-key="go">Try a different path</button><button type="button" class="button primary" data-action="lesson-tab" data-arg0="practice">Continue to the check</button></div>`;}
 return `${lxHead('BRANCHING SCENARIO · FICTIONAL','What would you do?','Make a decision, see the consequence, then decide again.')}${track}<div class="lx-sc-body">${body}</div>`;};
LX_INNER.spot=l=>{const s=lxD(l).spot,st=LX.sp[l.id]||(LX.sp[l.id]={m:[],c:false}),n=s.l.length,score=s.l.filter(([,bad],k)=>st.m.includes(k)===!!bad).length;return `${lxHead('SPOT THE PROBLEM','Which lines weaken it?',esc(s.t))}<ol class="lx-lines">${s.l.map(([t,bad,why],k)=>{const m=st.m.includes(k),ok=m===!!bad,verdict=!st.c?'':bad?(m?'Spotted':'Missed'):(m?'This one is fine':'Fine');return `<li class="lx-line${st.c?(ok?' is-ok':' is-miss')+(bad?' is-bad':''):''}"><button type="button" class="lx-line-btn" data-action="lx-spot" data-arg0="${l.id}" data-arg1="${k}" data-lx-key="sp${k}" aria-pressed="${m}" ${st.c?'disabled':''}><span class="lx-line-flag" aria-hidden="true">⚑</span><span class="lx-line-text">${esc(t)}</span><span class="lx-line-state">${m?'Flagged':'Flag'}</span></button>${st.c?`<p class="lx-line-why"><b>${verdict}.</b> ${esc(why)}</p>`:''}</li>`;}).join('')}</ol><div class="lx-actions">${st.c?`<span class="lx-score" role="status">${score} of ${n} judged correctly</span><button type="button" class="button secondary" data-action="lx-spot-reset" data-arg0="${l.id}" data-lx-key="go">Try again</button>`:`<button type="button" class="button primary" data-action="lx-spot-check" data-arg0="${l.id}" data-lx-key="go">Check my answers</button><span class="lx-note">${st.m.length} flagged</span>`}</div>`;};
function lxLadFill(l,v){const s=lxD(l).lad,x=s.s[v];return {label:x[0],ex:x[1],note:x[2]};}
LX_INNER.lad=l=>{const s=lxD(l).lad,v=LX.lad[l.id]??0,x=s.s[v];return `${lxHead('SLIDER',esc(s.t),esc(s.h))}<div class="lx-lad"><label class="lx-lad-range"><span class="lx-vh">${esc(s.t)}</span><input type="range" min="0" max="${s.s.length-1}" step="1" value="${v}" data-oninput="lx-lad" data-arg0="${l.id}" aria-valuetext="${esc(x[0])}: ${esc(x[1])}"></label><div class="lx-lad-stops" role="group" aria-label="Jump to a point on the slider">${s.s.map((y,i)=>`<button type="button" data-action="lx-lad-set" data-arg0="${l.id}" data-arg1="${i}" aria-pressed="${i===v}">${esc(y[0])}</button>`).join('')}</div><div class="lx-lad-out" role="status" aria-live="polite"><div class="lx-lad-meter" aria-hidden="true"><i style="width:${(v+1)/s.s.length*100}%"></i></div><b class="lx-lad-label">${esc(x[0])}</b><p class="lx-lad-ex">${esc(x[1])}</p><p class="lx-lad-note">${esc(x[2])}</p></div></div>`;};
function lxCalcOut(){const b=LX.calc.base,rr=LX.calc.rr,after=b*(1-rr/100),arr=b-after,nnt=arr>0?100/arr:0,f=n=>Number.isInteger(+n.toFixed(1))?String(Math.round(n)):n.toFixed(1),beforeN=Math.round(b),avoid=Math.max(0,Math.min(beforeN,Math.round(arr)));let dots='';for(let i=0;i<100;i++){const col=i%10,row=Math.floor(i/10),cls=i<avoid?'is-avoid':i<beforeN?'is-event':'';dots+=`<circle class="lx-dot ${cls}" cx="${12+col*22}" cy="${12+row*22}" r="8"/>`;}
 return `<svg class="lx-svg lx-dots" viewBox="0 0 220 220" role="img" aria-label="Icon array of 100 people: ${beforeN} with the outcome at baseline, of whom about ${avoid} avoided with the change.">${dots}</svg><div class="lx-calc-txt"><p><b>From ${f(b)} in 100 to ${f(after)} in 100</b></p><ul><li>Relative reduction: <b>${rr}%</b></li><li>Absolute reduction: <b>${f(arr)} in 100</b> (${f(arr)} percentage points)</li><li>Number needed to treat: <b>${nnt?'about '+Math.round(nnt):'not defined'}</b>${nnt?' (1 divided by '+(arr/100).toFixed(3).replace(/0+$/,'')+')':''}</li></ul><p class="lx-note">The same relative figure gives a very different absolute change at a different baseline. Try 1 in 100 and then 20 in 100. Dots are rounded to whole people. Fictional arithmetic for learning, not a clinical calculator.</p></div>`;}
LX_INNER.calc=l=>`${lxHead('TRY THE NUMBERS','Same “50%”, different meaning','Move the sliders and watch the relative and absolute figures separate.')}<div class="lx-calc"><div class="lx-calc-ctl"><label>Starting risk: <b id="lxBaseV">${LX.calc.base} in 100</b><input type="range" min="1" max="30" step="1" value="${LX.calc.base}" data-oninput="lx-calc" data-arg0="${l.id}" data-arg1="base" aria-label="Starting risk per 100 people"></label><label>Relative reduction: <b id="lxRrV">${LX.calc.rr}%</b><input type="range" min="10" max="90" step="5" value="${LX.calc.rr}" data-oninput="lx-calc" data-arg0="${l.id}" data-arg1="rr" aria-label="Relative reduction percent"></label></div><div class="lx-calc-out" role="status" aria-live="polite">${lxCalcOut()}</div></div>`;
LX_INNER.chk=l=>{const c=lxD(l).chk,on=lxR(l.id).tk;return `${lxHead('QUICK REFERENCE','Your one-page checklist','Tick what you do reliably. Ticks are saved on this device. Use it before the real thing, within your role and local policy.')}<ul class="lx-checks">${c.map((t,k)=>`<li><label class="lx-check"><input type="checkbox" data-onchange="lx-tick" data-arg0="${l.id}" data-arg1="${k}" ${on.includes(k)?'checked':''}><span>${esc(t)}</span></label></li>`).join('')}</ul><div class="lx-check-foot"><span class="lx-check-count" role="status">${on.filter(k=>k<c.length).length} of ${c.length} ticked</span><span class="lx-bar" aria-hidden="true"><i style="width:${on.filter(k=>k<c.length).length/c.length*100}%"></i></span><button type="button" class="button ghost" data-action="lx-tick-clear" data-arg0="${l.id}">Clear ticks</button><button type="button" class="button secondary" data-action="lx-tick-save" data-arg0="${l.id}">Save as text</button></div>`;};
const lxMyths=l=>`<section class="lx-c lx-myths">${lxHead('COMMON PITFALLS','Myth or reality?','Open each one to compare it with what works.')}<div class="lx-myth-list">${lxD(l).myths.map(([m,r])=>`<details class="lx-myth"><summary><span class="lx-myth-tag">Myth</span>${esc(m)}</summary><p><span class="lx-myth-tag is-real">Reality</span>${esc(r)}</p></details>`).join('')}</div></section>`;
const lxGood=l=>`<section class="lx-c lx-good">${lxHead('WHAT GOOD LOOKS LIKE','Signs it is working')}<ul>${lxD(l).good.map(g=>`<li>${esc(g)}</li>`).join('')}</ul></section>`;
function lxRelated(l){const d=lxD(l),e=P2_DATA.examples[l.id],act=relatedActivity(l);return `<section class="lx-c lx-rel">${lxHead('KEEP GOING','Related lessons and tools')}<div class="lx-rel-grid">${d.rel.map(id=>{const x=lessons.find(q=>q.id===id);return x?`<button type="button" class="lx-rel-card" data-action="lesson" data-arg0="${id}"><span class="lx-lv lv-${lxLv(x).toLowerCase()}">${lxLv(x)}</span><b>${esc(x.title)}</b><small>${esc(x.tag)} · ${x.time} min</small></button>`:'';}).join('')}<button type="button" class="lx-rel-card is-tool" data-action="tool" data-arg0="${e.tool}"><span class="lx-lv">Toolkit</span><b>${esc((TOOLS.find(t=>t[0]===e.tool)||[,'Practice tool'])[1])}</b><small>Rehearse it with a template</small></button><button type="button" class="lx-rel-card is-tool" data-action="activity" data-arg0="${act.id}"><span class="lx-lv">Practice</span><b>${esc(act.title)}</b><small>Try it in a fictional activity</small></button></div></section>`;}
function lxEvidenceStrip(l){const e=CC_EVIDENCE[l.evidence];if(!e)return '';return `<div class="lx-evid"><div><span class="eyebrow">EVIDENCE IN THIS APP</span><p><b>${esc(e.source)}</b> · ${esc(e.type)}. ${esc(e.finding)} <span class="lx-muted">${esc(e.context.split('. ')[0])}.</span></p></div>${btn('Read the findings and limits','lesson-evidence',[l.id],'secondary')}</div>`;}
const lxPager=(tab)=>{const i=LX_TABS.indexOf(tab),p=LX_TABS[i-1],n=LX_TABS[i+1];return `<nav class="lx-pager" aria-label="Lesson sections">${p?btn('← '+LX_TAB_LABEL[p],'lesson-tab',[p],'secondary'):'<span></span>'}${n?btn(LX_TAB_LABEL[n]+' →','lesson-tab',[n],'primary'):''}</nav>`;};
const lxVisualRow=l=>`<section class="lx-c lx-vis"><button type="button" class="lx-vis-art reading-art" data-action="infographics" data-arg0="${l.id}" aria-label="Open the three-page visual guide for ${esc(l.title)}"><img src="${INFO_PNG[l.id][0]}" alt="" loading="lazy" decoding="async"></button><div>${lxHead('VISUAL GUIDE','Three illustrated pages','Understand, Apply and Remember. Open the full-size guide, save the pages or follow them in the slide journey.')}<div class="lx-actions">${btn('Open visual guide','infographics',[l.id],'secondary')}${studioCardButton(l)}</div></div></section>`;

/* Worked example with the “Why it helps” bullets repaired where the source repeated the lesson text */
function lxWhyFix(id){const l=lessons.find(x=>x.id===id),e=P2_DATA.examples[id],d=LX_DATA[id];if(!l||!e||!d)return e?e.why:[];const dup=t=>l.steps.some(s=>s[1]===t)||t.length>150&&e.why.filter(w=>w===t).length>0&&l.steps.some(s=>s[1].includes(t.slice(0,60)));let g=0;return e.why.map(w=>dup(w)&&d.good[g]?'Look for: '+d.good[g++]:w);}
renderWorkedExample=function(l){const e=P2_DATA.examples[l.id],mode=exampleModes[l.id]||'poor',why=lxWhyFix(l.id),copy=(kind,label)=>`<section class="example-copy ${kind}"><h4>${label}</h4><p>“${readingText(e[kind])}”</p></section>`;return `<section class="worked-example"><span class="eyebrow">FICTIONAL WORKED EXAMPLE</span><h3>Notice the difference.</h3><p>${esc(e.situation)}</p><div class="segmented">${[['poor','Needs improvement'],['good','Stronger approach'],['compare','Compare both']].map(([v,t])=>btn(t,'example',[v],mode===v?'selected':'ghost',`aria-pressed="${mode===v}"`)).join('')}</div><div class="${mode==='compare'?'comparison':''}">${mode==='compare'?copy('poor','Needs improvement')+copy('good','Stronger approach'):copy(mode,mode==='good'?'Stronger approach':'Needs improvement')}</div><details ${mode!=='poor'?'open':''}><summary>Why the approach matters</summary><ul>${why.map(t=>`<li>${esc(t)}</li>`).join('')}</ul></details>${btn('Try the related tool →','tool',[e.tool],'secondary')}</section>`;};
{const oP=infographicPages;infographicPages=function(l){const p=oP(l);try{p[1].blocks[2].text=lxWhyFix(l.id).join(' ');}catch{}return p;};}
if(typeof ccStudioDeck==='function'){const oD=ccStudioDeck;ccStudioDeck=function(id){const d=oD(id);try{const s=d&&d.slides.find(x=>x.id==='cmp');if(s)s.why=lxWhyFix(id);}catch{}return d;};}

/* ---------- Lesson page ---------- */
function lxStageNav(l,tab){const st=lxStages(l);return LX_TABS.map((key,i)=>`<button role="tab" id="tab-${key}" data-action="lesson-tab" data-arg0="${key}" aria-controls="lessonPanel" aria-selected="${tab===key}" tabindex="${tab===key?0:-1}" class="${st[key]?'is-done':''}"><span aria-hidden="true">${st[key]&&tab!==key?'✓':i+1}</span>${LX_TAB_LABEL[key]}${st[key]?'<i class="lx-vh"> (done)</i>':''}</button>`).join('');}
function lxOverview(l){const d=lxD(l),context=CC_USE[l.id]||['Healthcare learners and practitioners.','When preparing or reflecting on this topic.'],st=lxStages(l),stageText={overview:['Overview','What this lesson is and why it matters'],learn:['Learn','Framework, three ideas, key terms and a worked example'],scenario:['Scenario','Branching decisions, spot the problem and a slider'],practice:['Practise','A check question and your quick-reference checklist'],reflect:['Reflect','One next action and a review date']};
 return `${studioLessonCard(l)}<section class="lesson-opening lx-open"><div class="lesson-opening-copy"><span class="eyebrow">THE LESSON · ${l.time} MINUTES OF CORE READING</span><h3>Start here</h3><p class="lead">${readingText(l.description)}</p><ul class="lx-facts"><li><span>Level</span><b>${lxLv(l)}</b></li><li><span>Dimension</span><b>${esc(l.cat[0].toUpperCase()+l.cat.slice(1))}</b></li><li><span>Includes</span><b>Scenario · checklist · ${lxD(l).terms.length} key terms</b></li></ul><p class="lx-note">${esc(LX_LEVELS[lxLv(l)])}</p></div><button type="button" class="reading-art" data-action="infographics" data-arg0="${l.id}" aria-label="Open three infographic pages for ${esc(l.title)}"><img src="${INFO_PNG[l.id][0]}" alt="Preview of the ${esc(l.title)} visual guide" decoding="async"><span>Explore 3 infographic pages ↗</span></button></section>
 <section class="lx-why"><span class="eyebrow">WHY IT MATTERS</span>${d.why.map(p=>`<p>${readingText(p)}</p>`).join('')}</section>${lxEvidenceStrip(l)}
 <section class="learning-brief"><div><strong>Who it helps</strong><p>${esc(context[0])}</p></div><div><strong>Use it when</strong><p>${esc(context[1])}</p></div><div class="full"><strong>One action to practise</strong><p>${readingText(P2_DATA.examples[l.id].action)}</p></div></section>
 <section class="outcomes"><h3>By the end, you can…</h3><ul><li>${esc(l.outcome||'Explain '+l.tag.toLowerCase()+' using a clear principle and a worked example.')}</li><li>Use ${esc(d.fw.n)} to structure what you say or do.</li><li>Recognise a less helpful response, explain why and choose a stronger one.</li><li>Choose one action to rehearse within your role and local policy.</li></ul></section>
 ${lxViz(l)}
 <section class="lx-path"><span class="eyebrow">YOUR PATH THROUGH THE LESSON</span><ol>${LX_TABS.map((k,i)=>`<li class="${st[k]?'is-done':''}"><button type="button" data-action="lesson-tab" data-arg0="${k}"><span class="lx-path-n" aria-hidden="true">${st[k]?'✓':i+1}</span><span><b>${stageText[k][0]}</b><small>${stageText[k][1]}</small></span><i class="lx-vh">${st[k]?'Done':'Not yet done'}</i></button></li>`).join('')}</ol></section>${lxPager('overview')}`;}
function lxLearn(l){const d=lxD(l);return `${lxWrap('fw',l)}<div class="lesson-reading-title"><span class="eyebrow">CORE READING</span><h3>Three ideas to use in practice</h3><p>Take these in order. Each explains what to notice and how to respond within your role and local policy.</p></div>${l.steps.map(([t,b],i)=>`<section class="learning-step" data-paragraph="${i}"><span class="step-num">${i+1}</span><div><h3>${esc(t)}</h3><p>${readingText(b)}</p></div></section>`).join('')}<section class="lesson-transfer"><span class="eyebrow">DEEPER READING</span><h3>What to notice and carry forward</h3>${LESSON_NOTES[l.id].map((note,i)=>`<div class="transfer-note"><span>${i===0?'Notice':'Use it'}</span><p>${readingText(note)}</p></div>`).join('')}</section>${lxWrap('flip',l)}${lxVisualRow(l)}${renderWorkedExample(l)}${lxMyths(l)}<div class="takeaway"><span class="eyebrow">ONE THING TO REMEMBER</span><p>${readingText(l.takeaway)}</p></div>${lxPager('learn')}`;}
function lxScenarioTab(l){return `<p class="lx-intro">Three short activities that make you decide. They are fictional and carry no score that is stored beyond your own best attempt.</p>${lxWrap('sc',l)}${lxWrap('spot',l)}${lxWrap('lad',l)}${lxD(l).calc?lxWrap('calc',l):''}${lxPager('scenario')}`;}
function lxPractice(l){const chosen=lessonAnswers[l.id];return `${ui.review?`<div class="review-session">Smart Review · ${ui.review.index+1} of ${ui.review.ids.length} · A learning aid, not an assessment</div>`:''}<section class="lx-check-q"><span class="eyebrow">PROMPT ${hcaQuestionIndex+1} OF 3</span><p>Choose a response, then explore the reasoning for every option.</p><h3 class="question">${esc(l.question)}</h3><div class="answer-list">${l.answers.map((a,i)=>btn(`<span class="letter">${'ABC'[i]}</span><span>${esc(a)}</span>`,'answer',[i],`answer ${chosen!==undefined?(i===l.correct?'correct':chosen===i?'incorrect':''):''}`,chosen!==undefined?'disabled':'')).join('')}</div>${chosen!==undefined?`<section class="feedback ${chosen===l.correct?'good':''}" role="status"><h3>${chosen===l.correct?'A useful approach.':'A useful moment to pause.'}</h3><p>${esc(l.rationales[chosen])}</p></section><details class="reasoning"><summary>Explore every option</summary>${l.answers.map((a,i)=>`<div><strong>${'ABC'[i]} · ${i===l.correct?'More helpful approach':'Alternative approach'}</strong><p>${esc(l.rationales[i])}</p></div>`).join('')}</details><div class="row">${btn('Try another prompt','next-prompt',[],'secondary')}${ui.review?btn('Next review →','review-next'):btn('Continue to reflection →','lesson-tab',['reflect'])}</div>`:''}</section>${lxWrap('chk',l)}${lxGood(l)}${ui.review?'':lxPager('practice')}`;}
function lxReflect(l){const action=state.actions.find(a=>a.lesson===l.id&&a.status==='planned'),d=lxD(l);return `<section class="lx-prompts"><span class="eyebrow">REFLECTIVE PROMPTS</span><h3>Turn one insight into a next step.</h3><p>${esc(l.reflect)}</p><p class="lx-note">More ways in. Select one to add it to your reflection.</p><ul>${d.pr.map(p=>`<li><button type="button" class="lx-prompt" data-action="lx-prompt" data-arg0="${esc(p)}">${esc(p)}</button></li>`).join('')}</ul></section><label>My reflection (optional)<textarea id="reflection" data-field="reflection" data-draft="${l.id}" maxlength="3000" placeholder="One thing I will try differently…">${esc(state.reflections[l.id]||'')}</textarea></label><p class="field-hint">Saved as you type. Private notes stay on this device; keep confidential details out.</p><section class="outcomes"><h3>Make it useful beyond this page.</h3><label>My next action<textarea id="actionText" maxlength="700" data-field="action-draft" placeholder="${esc(P2_DATA.examples[l.id].action)}">${esc(state.toolDrafts['action-'+l.id]?.[0]??action?.text??'')}</textarea></label><label>Return to review it<input id="actionDue" data-field="action-draft" type="date" value="${state.toolDrafts['action-'+l.id]?.[1]||action?.due||laterDay(7)}"></label>${btn('Save my action & review date','save-action',[l.id],'secondary')}</section>${disclosure('Learning activity · not clinical competence or CPD/CME credit')}<div class="row">${btn(state.completed.includes(l.id)?'Save & finish ✓':'Mark as reviewed ✓','complete')}</div>${lxRelated(l)}${lxPager('reflect')}`;}
renderLesson=function(){const l=activeLesson,tab=LX_TABS.includes(lessonTab)?lessonTab:'learn';lessonTab=tab;lxMark(l.id,tab);const notes=state.notes.filter(n=>n.lesson===l.id),speech=!!window.speechSynthesis,pct=lxPct(l),done=Object.values(lxStages(l)).filter(Boolean).length;
 const body=tab==='overview'?lxOverview(l):tab==='learn'?lxLearn(l):tab==='scenario'?lxScenarioTab(l):tab==='practice'?lxPractice(l):lxReflect(l);
 return `${header('Learn',l.tag)}<header class="lesson-header lx-head"><div class="lx-head-top"><div class="lx-head-title"><span class="eyebrow">${esc(l.cat)} · <span class="lx-lv lv-${lxLv(l).toLowerCase()}">${lxLv(l)}</span> · ${l.time} min core reading</span><h2>${esc(l.title)}</h2></div><div class="lesson-controls">${btn(icon('save'),'save',[l.id],'icon-button',`aria-label="Save lesson" aria-pressed="${state.saved.includes(l.id)}"`)}${btn(icon('research'),'lesson-evidence',[l.id],'icon-button','aria-label="Evidence and sources"')}${btn('Infographics','infographics',[l.id],'secondary')}${btn('Focus','focus',[],'secondary','aria-label="Toggle focus view"')}</div></div><div class="lesson-tabs" role="tablist" aria-label="Lesson sections">${lxStageNav(l,tab)}</div><div class="lx-head-prog">${progress(pct,'Lesson progress')}<span>${done} of ${LX_TABS.length} sections done</span></div></header><div class="lesson-layout lx-layout"><div class="reading lx-reading" id="lessonPanel" role="tabpanel" aria-labelledby="tab-${tab}" tabindex="-1">${speech&&(tab==='learn'||tab==='overview')?`<div class="read-aloud">${btn(icon('play')+' Read aloud','speak',[],'ghost')}${btn('Pause / resume','speech-pause',[],'ghost')}<label>Speed<select data-field="speech-speed">${[.8,1,1.2,1.5].map(n=>option(String(n),n+'×',String(ui.readSpeed))).join('')}</select></label><span id="speechStatus" role="status"></span></div>`:''}${body}${ui.completion===l.id?renderCompletion(l):''}<div class="next-learning"><h3>Keep a useful thought moving.</h3><div class="card-grid two"><div><span class="eyebrow">NEXT LESSON</span>${btn(esc(nextLesson(l).title)+' →','lesson',[nextLesson(l).id],'secondary')}</div><div><span class="eyebrow">RELATED PRACTICE</span>${btn(esc(relatedActivity(l).title)+' →','activity',[relatedActivity(l).id],'secondary')}</div></div></div></div><aside class="notes-sidebar"><div class="section-title"><h3>Your notes</h3>${btn('+','note',[],'icon-button','aria-label="Add a lesson note"')}</div><p class="field-hint">Select reading text to highlight it or attach a note.</p>${notes.length?notes.map(renderNote).join(''):'<p class="muted">A thought worth keeping can start here.</p>'}${btn('Evidence & sources →','lesson-evidence',[l.id],'secondary')}</aside></div>`;};

/* ---------- Learn library ---------- */
const lxFocusPath={communication:'communication',safety:'safety',leadership:'team',digital:'digital',wellbeing:'team'};
function lxNext(){const s=state.lastSession,cur=s&&s.kind==='lesson'?lessons.find(l=>l.id===s.lesson):null;if(cur&&!state.completed.includes(cur.id)&&lxPct(cur)<100)return {l:cur,resume:true,tab:LX_TABS.includes(s.tab)?s.tab:'learn'};const l=focusLessons().find(x=>!state.completed.includes(x.id))||lessons[0];return {l,resume:false,tab:'overview'};}
function lxLibraryHero(){const n=lxNext(),l=n.l,rev=state.completed.length,due=hcaDue().length,prog=lessons.filter(x=>lxPct(x)>0&&!state.completed.includes(x.id)).length;return `<section class="lx-hero"><div class="lx-hero-main"><span class="eyebrow">${n.resume?'PICK UP WHERE YOU LEFT OFF':'A GOOD PLACE TO START'}</span><h2>${esc(l.title)}</h2><p>${esc(l.description)}</p><p class="lx-hero-meta"><span class="lx-lv lv-${lxLv(l).toLowerCase()}">${lxLv(l)}</span><span>${l.time} min core reading</span><span>${n.resume?'Section: '+LX_TAB_LABEL[n.tab]:lxStatusWord(l)}</span></p><div class="lx-actions">${btn(n.resume?'Resume lesson →':'Start lesson →','lesson',[l.id,n.tab],'primary')}${studioCardButton(l)}</div></div><div class="lx-hero-side"><div class="lx-hero-ring">${ring(rev/lessons.length*100)}<span>${rev} of ${lessons.length} lessons reviewed</span></div><ul class="lx-hero-stats"><li><b>${prog}</b><span>in progress</span></li><li><b>${due}</b><span>reviews due</span></li><li><b>${state.saved.length}</b><span>saved</span></li></ul></div></section>`;}
function lxLevelBar(){const f=ui.filters.level||'all';return `<div class="lx-chiprow" role="group" aria-label="Level">${[['all','Any level'],...Object.keys(LX_LEVELS).map(k=>[k,k])].map(([v,t])=>`<button type="button" class="lx-chip" data-action="lx-level" data-arg0="${v}" aria-pressed="${f===v}">${t}</button>`).join('')}</div><p class="lx-note lx-level-note">${f==='all'?'Levels are editorial guidance on how much prior structure a lesson assumes. They are not a competency grade.':esc(LX_LEVELS[f])}</p>`;}
function lxCatBar(){const f=ui.filters.category;return `<div class="lx-chiprow" role="group" aria-label="Dimension">${[['all','All dimensions'],['knowledge','Knowledge'],['skills','Skills'],['attitudes','Attitudes']].map(([v,t])=>`<button type="button" class="lx-chip" data-action="category" data-arg0="${v}" aria-pressed="${f===v}">${t}</button>`).join('')}</div>`;}
function lxResults(){const f=ui.filters,list=filteredLessons(),filtered=f.category!=='all'||f.topic!=='all'||f.length!=='all'||f.status!=='all'||(f.level&&f.level!=='all')||(f.q||'').trim(),defaultGroup=ui.layout==='grouped'&&currentPage==='library'&&!filtered;
 const count=`<div class="result-count" role="status"><b>${list.length}</b> ${list.length===1?'lesson':'lessons'}<span>·</span>${lessons.length} in the library<span>·</span>each with a scenario, checklist and 3 visual pages</div>`;
 if(!list.length)return count+`<div class="empty"><h2>A different route might help.</h2><p>${currentPage==='saved'?'Save a lesson with the bookmark on any card and it will appear here.':'Clear the filters to return to all lessons.'}</p>${currentPage==='saved'?btn('Browse all lessons','navigate',['library'],'secondary'):btn('Reset your view','reset-filters',[],'secondary')}</div>`;
 return count+(defaultGroup?['knowledge','skills','attitudes'].map(cat=>`<section class="learning-group"><div class="section-title"><h2>${cat[0].toUpperCase()+cat.slice(1)}</h2><span class="group-count">10 lessons · ${cat==='knowledge'?'know it, then use it':cat==='skills'?'practise it':'notice and choose'}</span></div><div class="card-grid">${list.filter(l=>l.cat===cat).map(lessonCard).join('')}</div></section>`).join(''):`<div class="card-grid ${ui.layout==='list'?'list-layout':''}">${list.map(lessonCard).join('')}</div>`);}
renderLearn=function(){const f=ui.filters,saved=currentPage==='saved';return `${header(saved?'Saved lessons':'Learn',saved?'Lessons you bookmarked, ready to pick up again.':'Thirty lessons for the work you do: frameworks, scenarios, checklists and visual guides.')}<div class="collection-tabs">${btn('All lessons','navigate',['library'],currentPage==='library'?'selected':'ghost')}${btn('Pathways','navigate',['pathways'],'ghost')}${btn('Saved ('+state.saved.length+')','navigate',['saved'],saved?'selected':'ghost')}</div>${saved?'':lxLibraryHero()}<div class="filter-bar lx-filters" aria-label="Filter learning"><div class="lx-filter-top"><label class="lx-search">${icon('search')}<span class="lx-vh">Search lessons</span><input type="search" id="lxSearch" placeholder="Search lessons, ideas and key terms" value="${esc(f.q||'')}" data-oninput="lx-search" autocomplete="off"></label><div class="layout-options">${btn(icon('room'),'layout',['grouped'],ui.layout==='grouped'?'selected':'icon-button','aria-label="Grouped grid"')}${btn(icon('book'),'layout',['list'],ui.layout==='list'?'selected':'icon-button','aria-label="Compact list"')}${btn('Reset','reset-filters',[],'ghost')}</div></div><div class="lx-chips">${lxLevelBar()}</div><div class="lx-filter-selects">${filterSelect('category','Dimension',[['all','All dimensions'],['knowledge','Knowledge'],['skills','Skills'],['attitudes','Attitudes']],f.category)}${filterSelect('topic','Topic',[['all','All topics'],...lessons.map(l=>[l.tag,l.tag])],f.topic)}${filterSelect('length','Length',[['all','Any length'],['5','5 min or less'],['10','10 min or less']],f.length)}${filterSelect('status','Status',[['all','Any status'],...['Not started','In progress','Reviewed','Review due','Saved'].map(x=>[x,x])],f.status)}${filterSelect('sort','Sort',[['recommended','Recommended'],['shortest','Shortest'],['az','A–Z']],f.sort)}</div></div><div id="lxResults">${lxResults()}</div>`;};
{const old=filteredLessons;filteredLessons=function(){let list=old();const f=ui.filters;if(f.level&&f.level!=='all')list=list.filter(l=>lxLv(l)===f.level);const q=(f.q||'').trim();if(q)list=list.filter(l=>{const d=lxD(l)||{terms:[]};return searchRank(l.title+' '+l.tag+' '+l.description+' '+l.steps.map(s=>s[0]).join(' ')+' '+d.terms.map(t=>t[0]).join(' ')+' '+(d.fw?d.fw.n:''),q)>=0;});return list;};}
lessonCard=function(l){const s=lxStatusWord(l),saved=state.saved.includes(l.id),pct=lxPct(l),d=lxD(l)||{};return `<div class="card lesson-card lx-card" data-action="lesson" data-arg0="${l.id}" data-card-id="${l.id}" role="link" tabindex="0" aria-label="Open ${esc(l.title)}"><button type="button" class="card-art infographic-card-art" data-action="infographics" data-arg0="${l.id}" aria-label="Open infographic pages for ${esc(l.title)}"><img src="${INFO_PNG[l.id][0]}" alt="" loading="lazy" decoding="async"><span>View visual guide ↗</span></button><div class="card-copy"><div class="card-meta"><span class="category ${l.cat}">${l.cat}</span><span class="lx-lv lv-${lxLv(l).toLowerCase()}">${lxLv(l)}</span><span>${l.time} min</span></div><h3>${esc(l.title)}</h3><p>${esc(l.description)}</p>${d.fw?`<p class="lx-card-fw">${esc(d.fw.n)}</p>`:''}<div class="lx-card-prog"><span class="lx-bar" aria-hidden="true"><i style="width:${pct}%"></i></span><span>${pct?pct+'% of sections':'Not started'}</span></div><div class="cs-card-row">${btn('Open visual guide ↗','infographics',[l.id],'secondary infographic-entry',`aria-label="View infographics: ${esc(l.title)}"`)}${studioCardButton(l)}</div><div class="card-status ${s==='Review due'?'is-due':''}">${icon(s==='Reviewed'?'check':'clock')}${s} · ${pct?'Continue':'Start'} lesson →</div></div><div class="card-controls">${btn(icon('save'),'save',[l.id],'icon-button',`aria-label="${saved?'Unsave':'Save'} ${esc(l.title)}" aria-pressed="${saved}"`)}${btn(icon('preview'),'preview',[l.id],'icon-button quick-look',`aria-label="Preview ${esc(l.title)}"`)}</div></div>`;};

/* ---------- Pathways ---------- */
renderPathways=function(){const rec=lxFocusPath[state.learningFocus]||'communication';return `${header('Learning pathways','Five connected routes through the lessons and practice. Pick one, or follow the recommendation for your focus.')}<div class="collection-tabs">${btn('All lessons','navigate',['library'],'ghost')}${btn('Pathways','navigate',['pathways'],'selected')}${btn('Saved ('+state.saved.length+')','navigate',['saved'],'ghost')}</div><div class="pathway-grid lx-paths">${PATHWAYS.map(p=>{const ls=p.lessons.map(id=>lessons.find(l=>l.id===id)).filter(Boolean),count=p.lessons.filter(id=>state.completed.includes(id)).length+p.activities.filter(id=>state.studioAttempts.some(r=>activityRecordMatches(r.activity,id))||state.branchRecords.some(r=>r.case===id)).length,total=p.lessons.length+p.activities.length,mins=ls.reduce((n,l)=>n+l.time,0),lv=[...new Set(ls.map(lxLv))],nextId=p.lessons.find(id=>!state.completed.includes(id))||p.lessons[0];return `<article class="card pathway-card lx-path-card"><div class="lx-path-top">${ring(count/total*100)}<div><h2>${p.title}${p.id===rec?'<span class="lx-rec">Recommended for your focus</span>':''}</h2><p>${p.description}</p></div></div><p class="lx-path-meta"><span>${ls.length} lessons</span><span>about ${mins} min</span><span class="chip">${count} / ${total} explored</span><span>${lv.join(' · ')}</span></p><ol class="lx-path-steps">${ls.map(l=>`<li class="${state.completed.includes(l.id)?'is-done':''}"><button type="button" data-action="lesson" data-arg0="${l.id}"><span class="lx-path-n" aria-hidden="true">${state.completed.includes(l.id)?'✓':ls.indexOf(l)+1}</span><span class="lx-path-t">${esc(l.title)}</span><span class="lx-lv lv-${lxLv(l).toLowerCase()}">${lxLv(l)}</span><span class="lx-path-time">${l.time} min</span><i class="lx-vh">${state.completed.includes(l.id)?'Reviewed':lxStatusWord(l)}</i></button></li>`).join('')}</ol><div class="pathway-activities">${p.activities.map(id=>btn(icon('practice')+' '+esc(HCA_ACTIVITIES.find(a=>a.id===id).title),'activity',[id],'secondary')).join('')}</div>${count===total?`<div class="completion"><h3>You explored this pathway.</h3><p>Choose one action to try and return to reflect. This records learning activity, not clinical competence.</p></div>`:btn('Continue pathway →','lesson',[nextId],'primary')}</article>`;}).join('')}</div>`;};

/* ---------- Popups: quick look and evidence ---------- */
previewLesson=function(id){const l=lessons.find(l=>l.id===id),d=lxD(l),saved=state.saved.includes(id);showModal(esc(l.title),`Quick look · ${lxLv(l)} · ${l.cat} · ${l.time} min core reading`,`<div class="lx-quick"><img class="preview-art" src="${ccTopicArtwork(id,l.cat)}" alt="" loading="lazy"><div><p class="lead">${esc(l.description)}</p><p>${esc(d.why[0])}</p></div></div><h3>Inside this lesson</h3><ul class="lx-inside"><li><b>${esc(d.fw.n)}</b> framework tiles</li><li><b>${d.terms.length}</b> key-term flip cards</li><li><b>1</b> branching scenario, a spot-the-problem activity and a slider</li><li><b>${d.chk.length}</b>-point quick-reference checklist</li><li><b>3</b> illustrated visual pages</li></ul><h3>Three ideas</h3><ol>${l.steps.map(([t])=>`<li>${esc(t)}</li>`).join('')}</ol><p class="lx-take"><b>Remember:</b> ${esc(l.takeaway)}</p><div class="lx-actions">${btn('Begin this lesson →','lesson',[id,'overview'])}${studioCardButton(l)}${btn('Visual guide','infographics',[id],'secondary')}${btn(saved?'Saved ✓':'Save for later','save',[id],'secondary',`aria-pressed="${saved}"`)}</div>`);};
{const oE=lessonEvidence;lessonEvidence=function(id){oE(id);const l=lessons.find(x=>x.id===id),d=lxD(l),body=$('#modalBody');if(!body||!d)return;body.insertAdjacentHTML('afterbegin',`<section class="lx-method"><h3>How this lesson was built</h3><ul><li><b>Framework taught:</b> ${esc(d.fw.n)}. It is a standard, widely taught tool; local policy decides how you use it.</li><li><b>Worked example and scenario:</b> original and fictional, written for learning. They are not clinical instruction.</li><li><b>Numbers:</b> the only study figures are in the evidence card below. The risk calculator and examples are fictional arithmetic.</li><li><b>Review status:</b> original educational synthesis. Independent clinical peer review remains pending, and nothing here is accredited CPD or CME.</li></ul></section>`);};}

/* ---------- Actions ---------- */
const LX_ACTIONS={
 'lx-fw':([id,i])=>{LX.fw[id]=+i;lxRefresh('fw',id,`[data-lx-key="fw${i}"]`);},
 'lx-flip':([id,i],e,el)=>{const set=LX.fl[id]||(LX.fl[id]=new Set()),k=+i,on=!set.has(k);on?set.add(k):set.delete(k);el.setAttribute('aria-pressed',String(on));el.querySelector('.lx-front').setAttribute('aria-hidden',String(on));el.querySelector('.lx-back').setAttribute('aria-hidden',String(!on));},
 'lx-sc':([id,what])=>{const st=lxScState(id);if(what==='start')st.stage='a';else if(what==='restart'){LX.sc[id]={stage:'a',a:null,b:null};}else if(what==='next'){if(st.stage==='fa')st.stage='b';else if(st.stage==='fb'){st.stage='end';const s=lxD(lessons.find(l=>l.id===id)).sc,sc=lxScore(st,s),p=lxP(id);if(sc>p.sc){p.sc=sc;}persist();render();return;}}lxRefresh('sc',id,'[data-lx-key="o0"],[data-lx-key="o1"],[data-lx-key="o2"],[data-lx-key="go"]');if(what==='start'||what==='restart'||what==='next')document.querySelector(`[data-lxc="sc"][data-lxid="${id}"] .lx-sc-q`)?.scrollIntoView({block:'nearest'});},
 'lx-pick':([id,node,i])=>{const st=lxScState(id);if(st[node]!==null)return;st[node]=+i;st.stage='f'+node;const l=lessons.find(x=>x.id===id);if(node==='b'){const p=lxP(id);if(p.sc<0)p.sc=0;persist();}lxRefresh('sc',id,'[data-lx-key="fb"]');},
 'lx-spot':([id,k])=>{const st=LX.sp[id]||(LX.sp[id]={m:[],c:false});if(st.c)return;k=+k;st.m=st.m.includes(k)?st.m.filter(x=>x!==k):[...st.m,k];lxRefresh('spot',id,`[data-lx-key="sp${k}"]`);},
 'lx-spot-check':([id])=>{const st=LX.sp[id]||(LX.sp[id]={m:[],c:false}),l=lessons.find(x=>x.id===id),s=lxD(l).spot;st.c=true;const score=s.l.filter(([,bad],k)=>st.m.includes(k)===!!bad).length,p=lxP(id);if(score>p.sp)p.sp=score;persist();lxRefresh('spot',id,'.lx-score');},
 'lx-spot-reset':([id])=>{LX.sp[id]={m:[],c:false};lxRefresh('spot',id,'[data-lx-key="sp0"]');},
 'lx-lad':([id],e,el)=>lxLadPaint(id,+el.value),
 'lx-lad-set':([id,i])=>{lxLadPaint(id,+i);document.querySelector(`[data-lxc="lad"][data-lxid="${id}"] input[type=range]`)?.focus({preventScroll:true});},
 'lx-calc':([id,key],e,el)=>{LX.calc[key]=+el.value;const root=document.querySelector('[data-lxc="calc"]');if(!root)return;root.querySelector('#lxBaseV').textContent=LX.calc.base+' in 100';root.querySelector('#lxRrV').textContent=LX.calc.rr+'%';root.querySelector('.lx-calc-out').innerHTML=lxCalcOut();},
 'lx-tick':([id,k],e,el)=>{const p=lxP(id),n=+k;p.tk=el.checked?[...new Set([...p.tk,n])]:p.tk.filter(x=>x!==n);persist();lxTickPaint(id);},
 'lx-tick-clear':([id])=>{lxP(id).tk=[];persist();lxRefresh('chk',id,'.lx-check input');},
 'lx-tick-save':([id])=>{const l=lessons.find(x=>x.id===id),on=lxR(id).tk,c=lxD(l).chk;downloadFile(['CARECRAFT QUICK REFERENCE · '+l.title,'Educational checklist. Use within your role and local policy. Not clinical instruction.','',...c.map((t,k)=>(on.includes(k)?'[x] ':'[ ] ')+t),'','Saved '+new Date().toLocaleDateString('en-GB')].join('\n'),'carecraft-'+id+'-checklist.txt');toast('Checklist saved as a text file.');},
 'lx-level':([v])=>{ui.filters.level=v;render();},
 'lx-search':([],e,el)=>{ui.filters.q=el.value;const out=$('#lxResults');if(out)out.innerHTML=lxResults();},
 'lx-prompt':([text])=>{const el=$('#reflection');if(!el)return;if(!el.value.includes(text))el.value=(el.value?el.value.replace(/\s*$/,'')+'\n\n':'')+text+'\n';state.reflections[activeLesson.id]=el.value;persist();el.focus();el.setSelectionRange(el.value.length,el.value.length);},
 'reset-filters':()=>{ui.filters={category:'all',topic:'all',length:'all',status:'all',sort:'recommended',level:'all',q:''};navigate('library');},
 lesson:([id,tab])=>{const p=lxR(id);openLesson(id,LX_TABS.includes(tab)?tab:(p.last&&!state.completed.includes(id)?p.last:p.v.length?'learn':'overview'));}
};
function lxLadPaint(id,v){const l=lessons.find(x=>x.id===id),root=document.querySelector(`[data-lxc="lad"][data-lxid="${id}"]`);if(!root)return;LX.lad[id]=v;const s=lxD(l).lad,x=s.s[v],r=root.querySelector('input[type=range]');r.value=v;r.setAttribute('aria-valuetext',x[0]+': '+x[1]);root.querySelector('.lx-lad-label').textContent=x[0];root.querySelector('.lx-lad-ex').textContent=x[1];root.querySelector('.lx-lad-note').textContent=x[2];root.querySelector('.lx-lad-meter i').style.width=((v+1)/s.s.length*100)+'%';root.querySelectorAll('.lx-lad-stops button').forEach((b,i)=>b.setAttribute('aria-pressed',String(i===v)));}
function lxTickPaint(id){const root=document.querySelector(`[data-lxc="chk"][data-lxid="${id}"]`),l=lessons.find(x=>x.id===id);if(!root)return;const c=lxD(l).chk.length,n=lxR(id).tk.filter(k=>k<c).length;root.querySelector('.lx-check-count').textContent=n+' of '+c+' ticked';root.querySelector('.lx-bar i').style.width=(n/c*100)+'%';}
{const oB=bootstrap;bootstrap=function(){Object.assign(actions,LX_ACTIONS);return oB.apply(this,arguments);};}

