function dispatchAction(element,event,type='click'){const key=type==='click'?'action':'on'+type,name=element.dataset[key];if(!name)return;const args=[];for(let i=0;element.hasAttribute('data-arg'+i);i++)args.push(element.getAttribute('data-arg'+i));if(name.startsWith('engine-')){if(['dragover','dragleave'].includes(type)){ENGINE_ACTIONS[name]?.(event,element,args);return;}if(/(?:resetHygiene|resetSbar|hcaOpenRoom|ccOpenStudio|ccOpenSimulation|openAdv|setFlowCapacity|ccRiskChange)\s*\(/.test(ENGINE_ACTIONS[name]?.toString()||'')){ui.activitySaved=false;ui.lastSavedAttempt=null;ui.history=[];}if(['click','change','drop'].includes(type)&&ui.activity&&!activityFinished()&&!/ccShowEvidence|closeModal|logStudio|ccSave|saveFlowLearning/.test(ENGINE_ACTIONS[name]?.toString()||'')){captureActivity();(ui.history||(ui.history=[])).push(structuredClone(state.lastSession));ui.history=ui.history.slice(-50);}const encoded=element.getAttribute('data-'+name);if(encoded){try{args.splice(0,args.length,...JSON.parse(encoded));}catch{return;}}if(!['closeModal','ccShowEvidence'].some(s=>ENGINE_ACTIONS[name]?.toString().includes(s)))ui.dirty=!!ui.activity;ENGINE_ACTIONS[name]?.(event,element,args);}else actions[name]?.(args,event,element);captureActivity();syncActivityUI();}
