function drawSbar(c,t){c.fillStyle=cGradient(c,0,0,720,500,'#edf3ec','#dce8dc');c.fillRect(0,0,720,500);cRound(c,80,100,560,240,22,'#f4f7ed','#dce6d8');cRound(c,0,361,720,139,0,'#d7e4d5');cPlant(c,648,351,.8);cStandingPerson(c,148,190,.84,'#c99b78','#54856c',.3);cStandingPerson(c,575,190,.84,'#876246','#789486',.45);cText(c,'SENDER',147,381,10,'#5e7b65',700,'center');cText(c,'RECEIVER',575,381,10,'#5e7b65',700,'center');let phase=Math.min(4,Math.floor(t/3.2));for(let i=0;i<4;i++){let x=242+i*65;cRound(c,x,105,45,41,9,i===phase?'#386f50':'#e3ebe0');cText(c,'SBAR'[i],x+22,132,18,i===phase?'#fff':'#86a089',800,'center')}c.save();c.setLineDash([4,6]);cLine(c,205,235,518,235,'#bccfbb',2);c.restore();let local=(t%3.2)/3.2,ack=phase===4,x=ack?518-313*local:205+313*local;let title=ack?'Confirm the plan':sbarParts[Math.min(phase,3)].name;let color=ack?'#c19560':'#5b9871';cEllipse(c,x,235,14,14,color);cText(c,ack?'✓':'SBAR'[phase],x,240,13,'white',700,'center');cRound(c,230,270,266,62,12,'#fffffff0','#d7e2d2');cText(c,title,363,294,14,'#4c7151',700,'center');cText(c,ack?'Owner · timing · contingency':'Relevant information, clearly shared',363,316,10,'#79917b',400,'center');if(ack){cRound(c,273,163,180,36,9,'#f7eee0');cText(c,'Close the loop',363,186,12,'#a07b48',700,'center')}let caption=$('#studioCaption');if(caption){let descriptions=['Lead with the immediate concern and urgency.','Share only the background that helps the next decision.','State observed findings, concern, and uncertainty within your role.','Make a specific request for action or review.','Confirm responsibility, timing, and the contingency plan.'];caption.innerHTML=`<strong>${ack?'Closed loop':sbarParts[Math.min(phase,3)].name}</strong>${descriptions[phase]}`}}
function drawMovement(c,time){let m=movements[movementId],duration=m.duration,max=duration*movementCycles,atEnd=time>=max,p=atEnd?1:(time%duration)/duration,phase=Math.min(3,Math.floor(p*4)),cycle=Math.min(movementCycles,Math.floor(time/duration));c.fillStyle=cGradient(c,0,0,720,500,'#f0f4e9','#e3ecdc');c.fillRect(0,0,720,500);cEllipse(c,362,256,187,187,'#e2ebd8');cEllipse(c,362,256,158,158,'#e9f0df');cLine(c,50,410,670,410,'#cfdec7',2);cPlant(c,90,402,.82);cRound(c,615,154,37,154,18,'#e0e9d5');cRound(c,625,164,17,134,8,'#f3f6e9');let open=0;if(movementId==='chest'){open=p<.125?0:p<.25?smooth((p-.125)/.125):p<.75?1:1-smooth((p-.75)/.25);cSeatedFront(c,open)}else if(movementId==='march'){let a=p>=.15&&p<=.48?Math.sin((p-.15)/.33*Math.PI)*35:0,b=p>=.58&&p<=.93?Math.sin((p-.58)/.35*Math.PI)*35:0;cSeatedSide(c,a,b)}else{let extension=p<.18?0:p<.35?smooth((p-.18)/.17):p<.85?1:1-smooth((p-.85)/.15);let angle=p<.35?0:p<.58?smooth((p-.35)/.23)*.6:p<.8?.6-smooth((p-.58)/.22)*1.2:-.6*(1-smooth((p-.8)/.2));cSeatedSide(c,0,0,extension,angle)}cText(c,'COMFORT, NOT RANGE',360,442,9,'#8c9d81',600,'center');let ring=$('#movementRing');if(ring)ring.style.setProperty('--cycle',(p*100)+'%');let label=$('#movementLoop');if(label)label.innerHTML=`${cycle} / ${movementCycles}<br><span style="font-size:var(--t-12)">LOOPS</span>`;let cue=$('#movementCue');if(cue)cue.textContent=atEnd?'Illustration complete. Rest comfortably.':m.phases[phase];document.querySelectorAll('[data-movement-step]').forEach((el,i)=>el.classList.toggle('active',i===phase));let scrub=$('#movementScrub');if(scrub&&document.activeElement!==scrub)scrub.value=Math.round(p*100);let percent=$('#movementPercent');if(percent)percent.textContent=Math.round(p*100)+'%'}
function smooth(t){t=Math.max(0,Math.min(1,t));return t*t*(3-2*t)}
