(()=>{const H=()=>window.HCA||{},locked=()=>!!(H().locked&&H().locked('carecraft')),fl=id=>CC_FREE.lessons.includes(id),fa=id=>CC_FREE.activities.includes(id),pay=w=>setTimeout(()=>H().paywall('carecraft',w));const oL=openLesson,oA=launchActivity,oR=render,oP=scenarioPool,oS=startReview;startReview=function(){if(locked()){pay('Smart Review');return;}return oS.apply(this,arguments);};actions.review=()=>startReview();openLesson=function(id,...r){if(locked()&&!fl(id)){pay('this lesson');return;}return oL.call(this,id,...r);};launchActivity=function(id,...r){if(locked()&&!fa(id)){pay('this practice activity');return;}return oA.call(this,id,...r);};scenarioPool=function(){const p=oP();if(!locked())return p;const f=p.filter(l=>fl(l.id));return f.length?f:p;};render=function(){if(locked()){if(currentPage==='lesson'&&activeLesson&&!fl(activeLesson.id)){currentPage='library';currentFilter='all';history.replaceState(null,'','#/library');pay('this lesson');}else if(currentPage==='studio'&&ui.activity&&!fa(ui.activity)){studioDispose();currentPage='practice';ui.activity=null;history.replaceState(null,'','#/practice');pay('this practice activity');}}return oR.apply(this,arguments);};H().ready&&H().ready.then(()=>{if(locked()&&(currentPage==='lesson'||currentPage==='studio'))render();});})();
